import { LowpassCombFilter } from "../component/filter/LowpassCombFilter.js";
import { Frequency, NormalRange, Time } from "../core/type/Units.js";
import { deepMerge } from "../core/util/Defaults.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { RecursivePartial } from "../core/util/Interface.js";
import { Noise } from "../source/Noise.js";
import { Instrument, InstrumentOptions } from "./Instrument.js";

export interface PluckSynthOptions extends InstrumentOptions {
	attackNoise: number;
	dampening: Frequency;
	resonance: NormalRange;
	release: Time;
}

/**
 * Karplus-Strong string synthesis.
 * @example
 * const plucky = new Tone.PluckSynth().toDestination();
 * plucky.triggerAttack("C4", "+0.5");
 * plucky.triggerAttack("C3", "+1");
 * plucky.triggerAttack("C2", "+1.5");
 * plucky.triggerAttack("C1", "+2");
 * @category Instrument
 */
export class PluckSynth extends Instrument<PluckSynthOptions> {
	readonly name = "PluckSynth";

	/**
	 * Noise burst at the beginning
	 */
	private _noise: Noise;
	private _lfcf: LowpassCombFilter;

	/**
	 * The amount of noise at the attack.
	 * Nominal range of [0.1, 20]
	 * @min 0.1
	 * @max 20
	 */
	attackNoise: number;

	/**
	 * The amount of resonance of the pluck. Also correlates to the sustain duration.
	 */
	resonance: NormalRange;

	/**
	 * The release time which corresponds to a resonance ramp down to 0
	 */
	release: Time;

	constructor(options?: RecursivePartial<PluckSynthOptions>);
	constructor() {
		const options = optionsFromArguments(
			PluckSynth.getDefaults(),
			arguments
		);
		super(options);

		this._noise = new Noise({
			context: this.context,
			type: "pink",
		});

		this.attackNoise = options.attackNoise;

		this._lfcf = new LowpassCombFilter({
			context: this.context,
			dampening: options.dampening,
			resonance: options.resonance,
		});

		this.resonance = options.resonance;
		this.release = options.release;

		this._noise.connect(this._lfcf);
		this._lfcf.connect(this.output);
	}

	static getDefaults(): PluckSynthOptions {
		return deepMerge(Instrument.getDefaults(), {
			attackNoise: 1,
			dampening: 4000,
			resonance: 0.7,
			release: 1,
		});
	}

	/**
	 * The dampening control. i.e. the lowpass filter frequency of the comb filter
	 * @min 0
	 * @max 7000
	 */
	get dampening(): Frequency {
		return this._lfcf.dampening;
	}
	set dampening(fq) {
		this._lfcf.dampening = fq;
	}

	triggerAttack(note: Frequency, time?: Time): this {
		const freq = this.toFrequency(note);
		time = this.toSeconds(time);
		const delayAmount = 1 / freq;
		this._lfcf.delayTime.setValueAtTime(delayAmount, time);
		this._noise.start(time);
		this._noise.stop(time + delayAmount * this.attackNoise);
		this._lfcf.resonance.cancelScheduledValues(time);
		this._lfcf.resonance.setValueAtTime(this.resonance, time);
		return this;
	}

	/**
	 * Ramp down the {@link resonance} to 0 over the duration of the release time.
	 */
	triggerRelease(time?: Time): this {
		this._lfcf.resonance.linearRampTo(0, this.release, time);
		return this;
	}

	dispose(): this {
		super.dispose();
		this._noise.dispose();
		this._lfcf.dispose();
		return this;
	}
}

import { expect } from "chai";

import { BasicTests, warns } from "../../test/helper/Basic.js";
import { CompareToFile } from "../../test/helper/CompareToFile.js";
import { atTime, Offline } from "../../test/helper/Offline.js";
import { OutputAudio } from "../../test/helper/OutputAudio.js";
import { FMSynth } from "./FMSynth.js";
import { MembraneSynth } from "./MembraneSynth.js";
import { MetalSynth } from "./MetalSynth.js";
import { PluckSynth } from "./PluckSynth.js";
import { PolySynth } from "./PolySynth.js";
import { Synth } from "./Synth.js";

describe("PolySynth", () => {
	BasicTests(PolySynth);

	it("matches a file", () => {
		return CompareToFile(
			() => {
				const synth = new PolySynth().toDestination();
				synth.triggerAttackRelease("C4", 0.2, 0);
				synth.triggerAttackRelease("C4", 0.1, 0.1);
				synth.triggerAttackRelease("E4", 0.1, 0.2);
				synth.triggerAttackRelease("E4", 0.1, 0.3);
				synth.triggerAttackRelease("G4", 0.1, 0.4);
				synth.triggerAttackRelease("B4", 0.1, 0.4);
				synth.triggerAttackRelease("C4", 0.2, 0.5);
			},
			"polySynth.wav",
			0.6
		);
	});

	it("matches another file", () => {
		return CompareToFile(
			() => {
				const synth = new PolySynth().toDestination();
				synth.triggerAttackRelease(["C4", "E4", "G4", "B4"], 0.2, 0);
				synth.triggerAttackRelease(["C4", "E4", "G4", "B4"], 0.2, 0.3);
			},
			"polySynth2.wav",
			0.6
		);
	});

	it("matches a file and chooses the right voice", () => {
		return CompareToFile(
			() => {
				const synth = new PolySynth().toDestination();
				synth.triggerAttackRelease(["C4", "E4"], 1, 0);
				synth.triggerAttackRelease("G4", 0.1, 0.2);
				synth.triggerAttackRelease("B4", 0.1, 0.4);
				synth.triggerAttackRelease("G4", 0.1, 0.6);
			},
			"polySynth3.wav",
			0.5
		);
	});

	it("can be constructed with monophonic synths", () => {
		expect(() => {
			const polySynth = new PolySynth(Synth);
			polySynth.dispose();
		}).to.not.throw(Error);
		expect(() => {
			const polySynth = new PolySynth(FMSynth);
			polySynth.dispose();
		}).to.not.throw(Error);
		expect(() => {
			const polySynth = new PolySynth(MetalSynth);
			polySynth.dispose();
		}).to.not.throw(Error);
		expect(() => {
			const polySynth = new PolySynth(MembraneSynth);
			polySynth.dispose();
		}).to.not.throw(Error);
	});

	context("Playing Notes", () => {
		it("triggerAttackRelease can take an array of durations", async () => {
			await OutputAudio(() => {
				const polySynth = new PolySynth();
				polySynth.toDestination();
				polySynth.triggerAttackRelease(["C4", "D4"], [0.1, 0.2]);
			});
		});

		it("triggerAttack and triggerRelease can be invoked without arrays", async () => {
			const buffer = await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.set({ envelope: { release: 0.1 } });
				polySynth.toDestination();
				polySynth.triggerAttack("C4", 0);
				polySynth.triggerRelease("C4", 0.1);
			}, 0.3);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.2)).to.be.closeTo(0, 0.01);
		});

		it("can stop all of the currently playing sounds", async () => {
			const buffer = await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.set({ envelope: { release: 0.1 } });
				polySynth.toDestination();
				polySynth.triggerAttack(["C4", "E4", "G4", "B4"], 0);
				return atTime(0.1, () => {
					polySynth.releaseAll();
				});
			}, 0.3);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0, 0.01);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.2, 0.01);
		});

		it("is silent before being triggered", async () => {
			const buffer = await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.toDestination();
			});
			expect(buffer.isSilent()).to.be.true;
		});

		it("can be scheduled to start in the future", async () => {
			const buffer = await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.toDestination();
				polySynth.triggerAttack("C4", 0.1);
			}, 0.3);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0.1, 0.01);
		});

		it("can stop all sounds scheduled to start in the future when disposed", async () => {
			const buffer = await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.set({ envelope: { release: 0.1 } });
				polySynth.toDestination();
				polySynth.triggerAttackRelease(["C4", "E4", "G4", "B4"], 0.2);
				return atTime(0.1, () => {
					polySynth.dispose();
				});
			}, 0.3);
			expect(buffer.isSilent()).to.be.true;
		});

		it("disposes voices when they are no longer used", async () => {
			await Offline(() => {
				const polySynth = new PolySynth(Synth, {
					envelope: {
						release: 0.1,
					},
				});
				polySynth.toDestination();
				polySynth.triggerAttackRelease(
					["C4", "E4", "G4", "B4", "D5"],
					0.1,
					0
				);
				return [
					atTime(0, () => {
						expect(polySynth.activeVoices).to.equal(5);
					}),
					atTime(0.3, () => {
						expect(polySynth.activeVoices).to.equal(0);
					}),
				];
			}, 10);
		});

		it("warns when too much polyphony is attempted and notes are dropped", () => {
			warns(() => {
				return Offline(() => {
					const polySynth = new PolySynth({
						maxPolyphony: 2,
					});
					polySynth.toDestination();
					polySynth.triggerAttack(["C4", "D4", "G4"], 0.1);
				}, 0.3);
			});
		});

		it("reports the active notes", async () => {
			await Offline(() => {
				const polySynth = new PolySynth();
				polySynth.set({ envelope: { release: 0.1 } });
				polySynth.toDestination();
				polySynth.triggerAttackRelease("C4", 0.1, 0.1);
				polySynth.triggerAttackRelease("D4", 0.1, 0.2);
				polySynth.triggerAttackRelease("C4", 0.1, 0.5);
				polySynth.triggerAttackRelease("C4", 0.1, 0.6);
				return [
					atTime(0, () => {
						expect(polySynth.activeVoices).to.equal(0);
					}),
					atTime(0.1, () => {
						expect(polySynth.activeVoices).to.equal(1);
					}),
					atTime(0.2, () => {
						expect(polySynth.activeVoices).to.equal(2);
					}),
					atTime(0.3, () => {
						expect(polySynth.activeVoices).to.equal(1);
					}),
					atTime(0.4, () => {
						expect(polySynth.activeVoices).to.equal(0);
					}),
					atTime(0.5, () => {
						expect(polySynth.activeVoices).to.equal(1);
					}),
					atTime(0.6, () => {
						expect(polySynth.activeVoices).to.equal(2);
					}),
					atTime(0.7, () => {
						expect(polySynth.activeVoices).to.equal(1);
					}),
					atTime(0.8, () => {
						expect(polySynth.activeVoices).to.equal(0);
					}),
				];
			}, 1);
		});

		it("can trigger another attack before the release has ended", async () => {
			// compute the end time
			const buffer = await Offline(() => {
				const synth = new PolySynth(Synth, {
					envelope: {
						release: 0.1,
					},
				});
				synth.toDestination();
				synth.triggerAttack("C4", 0.05);
				synth.triggerRelease("C4", 0.1);
				synth.triggerAttack("C4", 0.15);
				synth.triggerRelease("C4", 0.2);
			}, 1);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.3, 0.01);
		});

		it("can trigger another attack right after the release has ended", async () => {
			// compute the end time
			const buffer = await Offline(() => {
				const synth = new PolySynth(Synth, {
					envelope: {
						release: 0.1,
					},
				});
				synth.toDestination();
				synth.triggerAttack("C4", 0.05);
				synth.triggerRelease("C4", 0.1);
				synth.triggerAttack("C4", 0.2);
				synth.triggerRelease("C4", 0.3);
				return atTime(0.41, () => {
					expect(synth.activeVoices).to.equal(0);
				});
			}, 1);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.4, 0.01);
		});
	});

	context("Transport sync", () => {
		it("can be synced to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const polySynth = new PolySynth(Synth, {
					envelope: {
						release: 0.1,
					},
				}).sync();
				polySynth.toDestination();
				polySynth.triggerAttackRelease("C4", 0.1, 0.1);
				polySynth.triggerAttackRelease("E4", 0.1, 0.3);
				transport.start(0.1);
			}, 0.8);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0.2, 0.01);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.6, 0.01);
		});

		it("is silent until the transport is started", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new PolySynth(Synth).sync().toDestination();
				synth.triggerAttackRelease("C4", 0.5);
				transport.start(0.5);
			}, 1);
			expect(buffer.getTimeOfFirstSound()).is.closeTo(0.5, 0.1);
		});

		it("stops when the transport is stopped", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new PolySynth(Synth, {
					envelope: {
						release: 0,
					},
				})
					.sync()
					.toDestination();
				synth.triggerAttackRelease("C4", 0.5);
				transport.start(0.5).stop(1);
			}, 1.5);
			expect(buffer.getTimeOfLastSound()).is.closeTo(1, 0.1);
		});

		it("goes silent at the loop boundary", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new PolySynth(Synth, {
					envelope: {
						release: 0,
					},
				})
					.sync()
					.toDestination();
				synth.triggerAttackRelease("C4", 0.8, 0.5);
				transport.loopEnd = 1;
				transport.loop = true;
				transport.start();
			}, 2);
			expect(buffer.getRmsAtTime(0)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(0.6)).to.be.closeTo(0.2, 0.05);
			expect(buffer.getRmsAtTime(1.1)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(1.6)).to.be.closeTo(0.2, 0.05);
		});

		it("can unsync", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new PolySynth(Synth, {
					envelope: {
						sustain: 1,
						release: 0,
					},
				})
					.sync()
					.toDestination()
					.unsync();
				synth.triggerAttackRelease("C4", 1, 0.5);
				transport.start().stop(1);
			}, 2);
			expect(buffer.getRmsAtTime(0)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(0.6)).to.be.closeTo(0.6, 0.05);
			expect(buffer.getRmsAtTime(1.4)).to.be.closeTo(0.6, 0.05);
			expect(buffer.getRmsAtTime(1.6)).to.be.closeTo(0, 0.05);
		});
	});

	context("API", () => {
		it("can be constructed with an options object", () => {
			const polySynth = new PolySynth(Synth, {
				envelope: {
					sustain: 0.3,
				},
			});
			expect(polySynth.get().envelope.sustain).to.equal(0.3);
			polySynth.dispose();
		});

		it("throws an error when used without a monophonic synth", () => {
			expect(() => {
				// @ts-ignore
				new PolySynth(PluckSynth);
			}).throws(Error);
		});

		it("can pass in the volume", () => {
			const polySynth = new PolySynth({
				volume: -12,
			});
			expect(polySynth.volume.value).to.be.closeTo(-12, 0.1);
			polySynth.dispose();
		});

		it("can get/set attributes", () => {
			const polySynth = new PolySynth();
			polySynth.set({
				envelope: { decay: 3 },
			});
			expect(polySynth.get().envelope.decay).to.equal(3);
			polySynth.dispose();
		});
	});
});

import { MidiClass } from "../core/type/Midi.js";
import {
	Frequency,
	MidiNote,
	NormalRange,
	Seconds,
	Time,
} from "../core/type/Units.js";
import { assert, warn } from "../core/util/Debug.js";
import {
	deepMerge,
	omitFromObject,
	optionsFromArguments,
} from "../core/util/Defaults.js";
import { RecursivePartial } from "../core/util/Interface.js";
import { isArray, isNumber } from "../core/util/TypeCheck.js";
import { AMSynth, AMSynthOptions } from "./AMSynth.js";
import { FMSynth, FMSynthOptions } from "./FMSynth.js";
import { Instrument, InstrumentOptions } from "./Instrument.js";
import { MembraneSynth, MembraneSynthOptions } from "./MembraneSynth.js";
import { MetalSynth, MetalSynthOptions } from "./MetalSynth.js";
import { Monophonic } from "./Monophonic.js";
import { MonoSynth, MonoSynthOptions } from "./MonoSynth.js";
import { Synth, SynthOptions } from "./Synth.js";

type VoiceConstructor<V> = {
	getDefaults: () => VoiceOptions<V>;
} & (new (...args: any[]) => V);

type OmitMonophonicOptions<T> = Omit<T, "context" | "onsilence">;

type VoiceOptions<T> = T extends MembraneSynth
	? MembraneSynthOptions
	: T extends MetalSynth
		? MetalSynthOptions
		: T extends FMSynth
			? FMSynthOptions
			: T extends MonoSynth
				? MonoSynthOptions
				: T extends AMSynth
					? AMSynthOptions
					: T extends Synth
						? SynthOptions
						: T extends Monophonic<infer U>
							? U
							: never;

/**
 * The settable synth options. excludes monophonic options.
 */
type PartialVoiceOptions<T> = RecursivePartial<
	OmitMonophonicOptions<VoiceOptions<T>>
>;

export interface PolySynthOptions<Voice> extends InstrumentOptions {
	maxPolyphony: number;
	voice: VoiceConstructor<Voice>;
	options: PartialVoiceOptions<Voice>;
}

/**
 * PolySynth handles voice creation and allocation for any
 * instruments passed in as the second parameter. PolySynth is
 * not a synthesizer by itself, it merely manages voices of
 * one of the other types of synths, allowing any of the
 * monophonic synthesizers to be polyphonic.
 *
 * @example
 * const synth = new Tone.PolySynth().toDestination();
 * // set the attributes across all the voices using 'set'
 * synth.set({ detune: -1200 });
 * // play a chord
 * synth.triggerAttackRelease(["C4", "E4", "A4"], 1);
 * @category Instrument
 */
export class PolySynth<
	Voice extends Monophonic<any> = Synth,
> extends Instrument<VoiceOptions<Voice>> {
	readonly name: string = "PolySynth";

	/**
	 * The voices which are not currently in use
	 */
	private _availableVoices: Voice[] = [];

	/**
	 * The currently active voices
	 */
	private _activeVoices: Array<{
		midi: MidiNote;
		voice: Voice;
		released: boolean;
	}> = [];

	/**
	 * All of the allocated voices for this synth.
	 */
	private _voices: Voice[] = [];

	/**
	 * The options that are set on the synth.
	 */
	private options: VoiceOptions<Voice>;

	/**
	 * The polyphony limit.
	 */
	maxPolyphony: number;

	/**
	 * The voice constructor
	 */
	private readonly voice: VoiceConstructor<Voice>;

	/**
	 * A voice used for holding the get/set values
	 */
	private _dummyVoice: Voice;

	/**
	 * The GC timeout. Held so that it could be cancelled when the node is disposed.
	 */
	private _gcTimeout = -1;

	/**
	 * A moving average of the number of active voices
	 */
	private _averageActiveVoices = 0;

	/**
	 * @param voice The constructor of the voices
	 * @param options	The options object to set the synth voice
	 */
	constructor(
		voice?: VoiceConstructor<Voice>,
		options?: PartialVoiceOptions<Voice>
	);
	constructor(options?: Partial<PolySynthOptions<Voice>>);
	constructor() {
		const options = optionsFromArguments(
			PolySynth.getDefaults(),
			arguments,
			["voice", "options"]
		);
		super(options);

		// check against the old API (pre 14.3.0)
		assert(
			!isNumber(options.voice),
			"DEPRECATED: The polyphony count is no longer the first argument."
		);

		const defaults = options.voice.getDefaults();
		this.options = Object.assign(
			defaults,
			options.options
		) as VoiceOptions<Voice>;
		this.voice = options.voice as unknown as VoiceConstructor<Voice>;
		this.maxPolyphony = options.maxPolyphony;

		// create the first voice
		this._dummyVoice = this._getNextAvailableVoice() as Voice;
		// remove it from the voices list
		const index = this._voices.indexOf(this._dummyVoice);
		this._voices.splice(index, 1);
		// kick off the GC interval
		this._gcTimeout = this.context.setInterval(
			this._collectGarbage.bind(this),
			1
		);
	}

	static getDefaults(): PolySynthOptions<Synth> {
		return Object.assign(Instrument.getDefaults(), {
			maxPolyphony: 32,
			options: {},
			voice: Synth,
		});
	}

	/**
	 * The number of active voices.
	 */
	get activeVoices(): number {
		return this._activeVoices.length;
	}

	/**
	 * Invoked when the source is done making sound, so that it can be
	 * re-added to the pool of available voices
	 */
	private _makeVoiceAvailable(voice: Voice): void {
		this._availableVoices.push(voice);
		// remove the midi note from 'active voices'
		const activeVoiceIndex = this._activeVoices.findIndex(
			(e) => e.voice === voice
		);
		this._activeVoices.splice(activeVoiceIndex, 1);
	}

	/**
	 * Get an available voice from the pool of available voices.
	 * If one is not available and the maxPolyphony limit is reached,
	 * steal a voice, otherwise return null.
	 */
	private _getNextAvailableVoice(): Voice | undefined {
		// if there are available voices, return the first one
		if (this._availableVoices.length) {
			return this._availableVoices.shift();
		} else if (this._voices.length < this.maxPolyphony) {
			// otherwise if there is still more maxPolyphony, make a new voice
			const voice = new this.voice(
				Object.assign(this.options, {
					context: this.context,
					onsilence: this._makeVoiceAvailable.bind(this),
				})
			);
			assert(
				voice instanceof Monophonic,
				"Voice must extend Monophonic class"
			);
			voice.connect(this.output);
			this._voices.push(voice);
			return voice;
		} else {
			warn("Max polyphony exceeded. Note dropped.");
		}
	}

	/**
	 * Occasionally check if there are any allocated voices which can be cleaned up.
	 */
	private _collectGarbage(): void {
		this._averageActiveVoices = Math.max(
			this._averageActiveVoices * 0.95,
			this.activeVoices
		);
		if (
			this._availableVoices.length &&
			this._voices.length > Math.ceil(this._averageActiveVoices + 1)
		) {
			// take off an available note
			const firstAvail = this._availableVoices.shift() as Voice;
			const index = this._voices.indexOf(firstAvail);
			this._voices.splice(index, 1);
			if (!this.context.isOffline) {
				firstAvail.dispose();
			}
		}
	}

	/**
	 * Internal method which triggers the attack
	 */
	private _triggerAttack(
		notes: Frequency[],
		time: Seconds,
		velocity?: NormalRange
	): void {
		notes.forEach((note) => {
			const midiNote = new MidiClass(this.context, note).toMidi();
			const voice = this._getNextAvailableVoice();
			if (voice) {
				voice.triggerAttack(note, time, velocity);
				this._activeVoices.push({
					midi: midiNote,
					voice,
					released: false,
				});
				this.log("triggerAttack", note, time);
			}
		});
	}

	/**
	 * Internal method which triggers the release
	 */
	private _triggerRelease(notes: Frequency[], time: Seconds): void {
		notes.forEach((note) => {
			const midiNote = new MidiClass(this.context, note).toMidi();
			const event = this._activeVoices.find(
				({ midi, released }) => midi === midiNote && !released
			);
			if (event) {
				// trigger release on that note
				event.voice.triggerRelease(time);
				// mark it as released
				event.released = true;
				this.log("triggerRelease", note, time);
			}
		});
	}

	/**
	 * Schedule the attack/release events. If the time is in the future, then it should set a timeout
	 * to wait for just-in-time scheduling
	 */
	private _scheduleEvent(
		type: "attack" | "release",
		notes: Frequency[],
		time: Seconds,
		velocity?: NormalRange
	): void {
		assert(!this.disposed, "Synth was already disposed");
		// if the notes are greater than this amount of time in the future, they should be scheduled with setTimeout
		if (time <= this.now()) {
			// do it immediately
			if (type === "attack") {
				this._triggerAttack(notes, time, velocity);
			} else {
				this._triggerRelease(notes, time);
			}
		} else {
			// schedule it to start in the future
			this.context.setTimeout(() => {
				if (!this.disposed) {
					this._scheduleEvent(type, notes, time, velocity);
				}
			}, time - this.now());
		}
	}

	/**
	 * Trigger the attack portion of the note
	 * @param  notes The notes to play. Accepts a single Frequency or an array of frequencies.
	 * @param  time  The start time of the note.
	 * @param velocity The velocity of the note.
	 * @example
	 * const synth = new Tone.PolySynth(Tone.FMSynth).toDestination();
	 * // trigger a chord immediately with a velocity of 0.2
	 * synth.triggerAttack(["Ab3", "C4", "F5"], Tone.now(), 0.2);
	 */
	triggerAttack(
		notes: Frequency | Frequency[],
		time?: Time,
		velocity?: NormalRange
	): this {
		if (!Array.isArray(notes)) {
			notes = [notes];
		}
		const computedTime = this.toSeconds(time);
		this._scheduleEvent("attack", notes, computedTime, velocity);
		return this;
	}

	/**
	 * Trigger the release of the note. Unlike monophonic instruments,
	 * a note (or array of notes) needs to be passed in as the first argument.
	 * @param  notes The notes to play. Accepts a single Frequency or an array of frequencies.
	 * @param  time  When the release will be triggered.
	 * @example
	 * const poly = new Tone.PolySynth(Tone.AMSynth).toDestination();
	 * poly.triggerAttack(["Ab3", "C4", "F5"]);
	 * // trigger the release of the given notes.
	 * poly.triggerRelease(["Ab3", "C4"], "+1");
	 * poly.triggerRelease("F5", "+3");
	 */
	triggerRelease(notes: Frequency | Frequency[], time?: Time): this {
		if (!Array.isArray(notes)) {
			notes = [notes];
		}
		const computedTime = this.toSeconds(time);
		this._scheduleEvent("release", notes, computedTime);
		return this;
	}

	/**
	 * Trigger the attack and release after the specified duration
	 * @param  notes The notes to play. Accepts a single  Frequency or an array of frequencies.
	 * @param  duration the duration of the note
	 * @param  time  if no time is given, defaults to now
	 * @param  velocity the velocity of the attack (0-1)
	 * @example
	 * const poly = new Tone.PolySynth(Tone.AMSynth).toDestination();
	 * // can pass in an array of durations as well
	 * poly.triggerAttackRelease(["Eb3", "G4", "Bb4", "D5"], [4, 3, 2, 1]);
	 */
	triggerAttackRelease(
		notes: Frequency | Frequency[],
		duration: Time | Time[],
		time?: Time,
		velocity?: NormalRange
	): this {
		const computedTime = this.toSeconds(time);
		this.triggerAttack(notes, computedTime, velocity);
		if (isArray(duration)) {
			assert(
				isArray(notes),
				"If the duration is an array, the notes must also be an array"
			);
			notes = notes as Frequency[];
			for (let i = 0; i < notes.length; i++) {
				const d = duration[Math.min(i, duration.length - 1)];
				const durationSeconds = this.toSeconds(d);
				assert(
					durationSeconds > 0,
					"The duration must be greater than 0"
				);
				this.triggerRelease(notes[i], computedTime + durationSeconds);
			}
		} else {
			const durationSeconds = this.toSeconds(duration);
			assert(durationSeconds > 0, "The duration must be greater than 0");
			this.triggerRelease(notes, computedTime + durationSeconds);
		}
		return this;
	}

	sync(): this {
		if (this._syncState()) {
			this._syncMethod("triggerAttack", 1);
			this._syncMethod("triggerRelease", 1);

			// make sure that the sound doesn't play after its been stopped
			this.context.transport.on("stop", this._syncedRelease);
			this.context.transport.on("pause", this._syncedRelease);
			this.context.transport.on("loopEnd", this._syncedRelease);
		}
		return this;
	}

	/**
	 * The release which is scheduled to the timeline.
	 */
	protected _syncedRelease = (time: number) => this.releaseAll(time);

	/**
	 * Set a member/attribute of the voices
	 * @example
	 * const poly = new Tone.PolySynth().toDestination();
	 * // set all of the voices using an options object for the synth type
	 * poly.set({
	 * 	envelope: {
	 * 		attack: 0.25
	 * 	}
	 * });
	 * poly.triggerAttackRelease("Bb3", 0.2);
	 */
	set(options: RecursivePartial<VoiceOptions<Voice>>): this {
		// remove options which are controlled by the PolySynth
		const sanitizedOptions = omitFromObject(options, [
			"onsilence",
			"context",
		]);
		// store all of the options
		this.options = deepMerge(this.options, sanitizedOptions);
		this._voices.forEach((voice) => voice.set(sanitizedOptions));
		this._dummyVoice.set(sanitizedOptions);
		return this;
	}

	get(): VoiceOptions<Voice> {
		return this._dummyVoice.get();
	}

	/**
	 * Trigger the release portion of all the currently active voices immediately.
	 * Useful for silencing the synth.
	 */
	releaseAll(time?: Time): this {
		const computedTime = this.toSeconds(time);
		this._activeVoices.forEach(({ voice }) => {
			voice.triggerRelease(computedTime);
		});
		return this;
	}

	dispose(): this {
		super.dispose();
		this._dummyVoice.dispose();
		this._voices.forEach((v) => v.dispose());
		this._activeVoices = [];
		this._availableVoices = [];
		this.context.clearInterval(this._gcTimeout);
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../test/helper/Basic.js";
import { CompareToFile } from "../../test/helper/CompareToFile.js";
import { InstrumentTest } from "../../test/helper/InstrumentTests.js";
import { atTime, Offline } from "../../test/helper/Offline.js";
import { ToneAudioBuffer } from "../core/context/ToneAudioBuffer.js";
import { getContext } from "../core/Global.js";
import { Sampler } from "./Sampler.js";

describe("Sampler", () => {
	const A4_buffer = new ToneAudioBuffer();

	beforeEach(() => {
		return A4_buffer.load("./test/audio/sine.wav");
	});

	BasicTests(Sampler);

	InstrumentTest(
		Sampler,
		"A4",
		{
			69: A4_buffer,
		},
		1
	);

	it("matches a file", () => {
		return CompareToFile(
			() => {
				const sampler = new Sampler(
					{
						69: A4_buffer,
					},
					{
						release: 0.4,
					}
				).toDestination();
				sampler.triggerAttackRelease("C4", 0.1, 0, 0.2);
				sampler.triggerAttackRelease("E4", 0.1, 0.2, 0.4);
				sampler.triggerAttackRelease("G4", 0.1, 0.4, 0.6);
				sampler.triggerAttackRelease("B4", 0.1, 0.6, 0.8);
				sampler.triggerAttackRelease("C4", 0.1, 0.8);
			},
			"sampler.wav",
			0.01
		);
	});

	context("Constructor", () => {
		it("can be constructed with an options object", () => {
			const sampler = new Sampler(
				{
					69: A4_buffer,
				},
				{
					attack: 0.2,
					release: 0.3,
                    loop: true
				}
			);
			expect(sampler.attack).to.equal(0.2);
			expect(sampler.release).to.equal(0.3);
			sampler.dispose();
		});

		it("can be constructed with an options object with urls object", () => {
			const sampler = new Sampler({
				attack: 0.4,
				release: 0.5,
				urls: {
					69: A4_buffer,
				},
			});
			expect(sampler.attack).to.equal(0.4);
			expect(sampler.release).to.equal(0.5);
			sampler.dispose();
		});

		it("urls can be described as either midi or notes", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler({
					A4: A4_buffer,
				}).toDestination();
				sampler.triggerAttack("A4");
			});
			expect(buffer.isSilent()).to.be.false;
		});

		it("get() reports back the urls, baseUrl, onload and onerror it was constructed with", () => {
			const onload = () => {};
			const onerror = () => {};
			const sampler = new Sampler({
				urls: {
					69: A4_buffer,
				},
				baseUrl: "./test/audio/",
				onload,
				onerror,
			});
			const options = sampler.get();
			expect(options.urls).to.deep.equal({
				69: A4_buffer,
			});
			expect(options.baseUrl).to.equal("./test/audio/");
			expect(options.onload).to.equal(onload);
			expect(options.onerror).to.equal(onerror);
			sampler.dispose();
		});

		it("throws an error if there are no available notes to play", () => {
			expect(() => {
				const sampler = new Sampler();
				sampler.triggerAttack("C4");
			}).throws(Error);
		});

		it("throws an error if the url key is not midi or pitch notation", () => {
			expect(() => {
				const sampler = new Sampler({
					urls: {
						note: A4_buffer,
					},
				});
			}).throws(Error);
		});

		it("invokes onerror if the ", async () => {
			const sampler = new Sampler({
				urls: {
					40: "./nosuchfile.wav",
				},
				onerror(e) {
					expect(e).to.be.instanceOf(Error);
					sampler.dispose();
				},
			});
			await Offline(() => {});
		});

		it("can get and set envelope attributes", () => {
			const sampler = new Sampler();
			sampler.attack = 0.1;
			sampler.release = 0.1;
			expect(sampler.attack).to.equal(0.1);
			expect(sampler.release).to.equal(0.1);
			sampler.dispose();
		});

		it("invokes the callback when loaded", (done) => {
			const sampler = new Sampler(
				{
					A4: "./test/audio/sine.wav",
				},
				() => {
					expect(sampler.loaded).to.be.true;
					done();
				}
			);
		});

		it("invokes onload when triggerAttack runs before the buffer loads", async () => {
			let loaded = false;
			const sampler = new Sampler({
				onload(): void {
					loaded = true;
				},
				urls: {
					A4: "./test/audio/sine.wav",
				},
			});
			expect(() => {
				sampler.triggerAttack("A4");
			}).throws(Error, /not loaded/);
			await ToneAudioBuffer.loaded();
			expect(loaded).to.be.true;
			expect(sampler.loaded).to.be.true;
			sampler.dispose();
		});

		it("can pass in a callback and baseUrl", (done) => {
			const sampler = new Sampler(
				{
					A4: A4_buffer,
				},
				() => {
					expect(sampler.loaded).to.be.true;
					done();
				},
				"./baseUrl"
			);
		});

		it("can dispose while playing sounds", () => {
			return Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttack("A4", 0);
				sampler.triggerRelease("A4", 0.2);
				sampler.dispose();
			}, 0.3);
		});
	});

	context("Makes sound", () => {
		it("repitches the note", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler({
					A4: A4_buffer,
				}).toDestination();
				sampler.triggerAttack("G4");
			});
			expect(buffer.isSilent()).to.be.false;
		});

		it("is silent after the release", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttack("A4", 0);
				sampler.triggerRelease("A4", 0.2);
			}, 0.3);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.2, 0.01);
		});

		it("can triggerRelease after the buffer has already stopped", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttack("A4", 0);
				return atTime(A4_buffer.duration + 0.01, () => {
					sampler.triggerRelease("A4");
				});
			}, A4_buffer.duration + 0.1);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(
				A4_buffer.duration,
				0.01
			);
		});

		it("can release multiple notes", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttack("A4", 0);
				sampler.triggerAttack("C4", 0);
				sampler.triggerAttack("A4", 0.1);
				sampler.triggerAttack("G4", 0.1);
				sampler.releaseAll(0.2);
			}, 0.3);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.2, 0.01);
		});

		it("can trigger the attack and release", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttackRelease("A4", 0.2, 0.1);
			}, 0.4);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0.1, 0.01);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.3, 0.01);
		});

		it("can trigger polyphonic attack release", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler(
					{
						A4: A4_buffer,
					},
					{
						release: 0,
					}
				).toDestination();
				sampler.triggerAttackRelease(["A4", "C4"], [0.2, 0.3], 0.1);
			}, 0.5);
			expect(buffer.getTimeOfFirstSound()).to.be.closeTo(0.1, 0.01);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.4, 0.01);
		});
	});

    context("Looping", () => {

        it("can be set to loop", () => {
            const sampler = new Sampler();
            sampler.loop = true;
            expect(sampler.loop).to.be.true;
            sampler.dispose();
        });

        it("can set the loop points", () => {
            const sampler = new Sampler();
            sampler.loopStart = 0.2;
            expect(sampler.loopStart).to.equal(0.2);
            sampler.loopEnd = 0.7;
            expect(sampler.loopEnd).to.equal(0.7);
            sampler.setLoopPoints(0, 0.5);
            expect(sampler.loopStart).to.equal(0);
            expect(sampler.loopEnd).to.equal(0.5);
            sampler.dispose();
        });

        it("loops the audio", async () => {
            const buff = await Offline(() => {
                const sampler = new Sampler({
                    urls: {
                        A4: A4_buffer
                    }
                });
                sampler.loop = true;
                sampler.toDestination();
                sampler.triggerAttack("A4");
            }, A4_buffer.duration * 1.5);
            expect(buff.getRmsAtTime(0)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 0.5)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 1.2)).to.be.above(0);
        });

        it("setting the loop multiple times has no affect", async () => {
            const buff = await Offline(() => {
                const sampler = new Sampler({
                    urls: {
                        A4: A4_buffer
                    }
                });
                sampler.loop = true;
                sampler.loop = true;
                sampler.toDestination();
                sampler.triggerAttack("A4");
            }, A4_buffer.duration * 1.5);
            expect(buff.getRmsAtTime(0)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 0.5)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 1.2)).to.be.above(0);
        });

        it("loops the audio when loop is set after start", async () => {
            const buff = await Offline(() => {
                const sampler = new Sampler({
                    urls: {
                        A4: A4_buffer
                    }
                });
                sampler.toDestination();
                sampler.triggerAttack("A4");
                sampler.loop = true;
            }, A4_buffer.duration * 1.5);
            expect(buff.getRmsAtTime(0)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 0.5)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration)).to.be.above(0);
            expect(buff.getRmsAtTime(A4_buffer.duration * 1.2)).to.be.above(0);
        });

        it("starts buffers at loopStart when set to loop", async () => {
            const testSample =
                A4_buffer.toArray(0)[Math.floor(0.1 * getContext().sampleRate)];
            const buff = await Offline(() => {
                const sampler = new Sampler({
                    urls: {
                        A4: A4_buffer
                    }
                });
                sampler.loopStart = 0.1;
                sampler.loop = true;
                sampler.toDestination();
                sampler.triggerAttack("A4");
            }, 0.05);
            expect(buff.toArray()[0][0]).to.equal(testSample);
        });
    });

	context("add samples", () => {
		it("can add a note with its midi value", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler().toDestination();
				sampler.add(69, A4_buffer);
				sampler.triggerAttack("B4");
			});
			expect(buffer.isSilent()).to.be.false;
		});

		it("can add a note with its note name", async () => {
			const buffer = await Offline(() => {
				const sampler = new Sampler().toDestination();
				sampler.add("A4", A4_buffer);
				sampler.triggerAttack("G4");
			});
			expect(buffer.isSilent()).to.be.false;
		});

		it("can pass in a url and invokes the callback", (done) => {
			const sampler = new Sampler();
			sampler.add("A4", "./test/audio/sine.wav", () => {
				done();
			});
		});

		it("throws an error if added note key is not midi or note name", () => {
			expect(() => {
				const sampler = new Sampler().toDestination();
				// @ts-ignore
				sampler.add("nope", A4_buffer);
			}).throws(Error);
		});
	});
});

import { ToneAudioBuffer } from "../core/context/ToneAudioBuffer.js";
import { ToneAudioBuffers } from "../core/context/ToneAudioBuffers.js";
import { ftomf, intervalToFrequencyRatio } from "../core/type/Conversions.js";
import { FrequencyClass } from "../core/type/Frequency.js";
import {
	Frequency,
	Interval,
	MidiNote,
	NormalRange,
	Note,
	Time,
} from "../core/type/Units.js";
import { assert, assertRange } from "../core/util/Debug.js";
import { timeRange } from "../core/util/Decorator.js";
import { defaultArg, optionsFromArguments } from "../core/util/Defaults.js";
import { noOp } from "../core/util/Interface.js";
import { isArray, isNote, isNumber } from "../core/util/TypeCheck.js";
import { Instrument, InstrumentOptions } from "../instrument/Instrument.js";
import {
	ToneBufferSource,
	ToneBufferSourceCurve,
} from "../source/buffer/ToneBufferSource.js";

interface SamplesMap {
	[note: string]: ToneAudioBuffer | AudioBuffer | string;
	[midi: number]: ToneAudioBuffer | AudioBuffer | string;
}

export interface SamplerOptions extends InstrumentOptions {
	attack: Time;
	release: Time;
	onload: () => void;
	onerror: (error: Error) => void;
	baseUrl: string;
	curve: ToneBufferSourceCurve;
	urls: SamplesMap;
	loop: boolean;
	loopEnd: number;
	loopStart: number;
}

/**
 * Pass in an object which maps the note's pitch or midi value to the url,
 * then you can trigger the attack and release of that note like other instruments.
 * By automatically repitching the samples, it is possible to play pitches which
 * were not explicitly included which can save loading time.
 *
 * For sample or buffer playback where repitching is not necessary,
 * use {@link Player}.
 * @example
 * const sampler = new Tone.Sampler({
 * 	urls: {
 * 		A1: "A1.mp3",
 * 		A2: "A2.mp3",
 * 	},
 * 	baseUrl: "https://tonejs.github.io/audio/casio/",
 * 	onload: () => {
 * 		sampler.triggerAttackRelease(["C1", "E1", "G1", "B1"], 0.5);
 * 	}
 * }).toDestination();
 * @category Instrument
 */
export class Sampler extends Instrument<SamplerOptions> {
	readonly name: string = "Sampler";

	/**
	 * The stored and loaded buffers
	 */
	private _buffers: ToneAudioBuffers;

	/**
	 * The object of all currently playing BufferSources
	 */
	private _activeSources: Map<MidiNote, ToneBufferSource[]> = new Map();

	/**
	 * The list of all provided midi notes
	 */
	private _providedMidiNotes: MidiNote[] = [];

	/**
	 * if the buffer should loop once its over
	 */
	private _loop: boolean;

	/**
	 * if 'loop' is true, the loop will start at this position
	 */
	private _loopStart: Time;

	/**
	 * if 'loop' is true, the loop will end at this position
	 */
	private _loopEnd: Time;

	/**
	 * The envelope applied to the beginning of the sample.
	 * @min 0
	 * @max 1
	 */
	@timeRange(0)
	attack: Time;

	/**
	 * The envelope applied to the end of the envelope.
	 * @min 0
	 * @max 1
	 */
	@timeRange(0)
	release: Time;

	/**
	 * The shape of the attack/release curve.
	 * Either "linear" or "exponential"
	 */
	curve: ToneBufferSourceCurve;

	/**
	 * The urls passed in the constructor, kept so `get()` can report them back.
	 */
	private _urls: SamplesMap;

	/**
	 * The baseUrl passed in the constructor, kept so `get()` can report it back.
	 */
	private _baseUrl: string;

	/**
	 * The onload callback passed in the constructor, kept so `get()` can report it back.
	 */
	private _onload: () => void;

	/**
	 * The onerror callback passed in the constructor, kept so `get()` can report it back.
	 */
	private _onerror: (error: Error) => void;

	/**
	 * @param samples An object of samples mapping either Midi Note Numbers or
	 * 			Scientific Pitch Notation to the url of that sample.
	 * @param onload The callback to invoke when all of the samples are loaded.
	 * @param baseUrl The root URL of all of the samples, which is prepended to all the URLs.
	 */
	constructor(samples?: SamplesMap, onload?: () => void, baseUrl?: string);
	/**
	 * @param samples An object of samples mapping either Midi Note Numbers or
	 * 			Scientific Pitch Notation to the url of that sample.
	 * @param options The remaining options associated with the sampler
	 */
	constructor(
		samples?: SamplesMap,
		options?: Partial<Omit<SamplerOptions, "urls">>
	);
	constructor(options?: Partial<SamplerOptions>);
	constructor() {
		const options = optionsFromArguments(
			Sampler.getDefaults(),
			arguments,
			["urls", "onload", "baseUrl"],
			"urls"
		);
		super(options);

		const urlMap = {};
		Object.keys(options.urls).forEach((note) => {
			const noteNumber = parseInt(note, 10);
			assert(
				isNote(note) || (isNumber(noteNumber) && isFinite(noteNumber)),
				`url key is neither a note or midi pitch: ${note}`
			);
			if (isNote(note)) {
				// convert the note name to MIDI
				const mid = new FrequencyClass(this.context, note).toMidi();
				urlMap[mid] = options.urls[note];
			} else if (isNumber(noteNumber) && isFinite(noteNumber)) {
				// otherwise if it's numbers assume it's midi
				urlMap[noteNumber] = options.urls[noteNumber];
			}
		});

		this._buffers = new ToneAudioBuffers({
			urls: urlMap,
			onload: options.onload,
			baseUrl: options.baseUrl,
			onerror: options.onerror,
		});
		this.attack = options.attack;
		this.release = options.release;
		this.curve = options.curve;
		this._urls = options.urls;
		this._baseUrl = options.baseUrl;
		this._onload = options.onload;
		this._onerror = options.onerror;
		this._loop = options.loop;
		this._loopStart = options.loopStart;
		this._loopEnd = options.loopEnd;

		// invoke the callback if it's already loaded
		if (this._buffers.loaded) {
			// invoke onload deferred
			Promise.resolve().then(options.onload);
		}
	}

	static getDefaults(): SamplerOptions {
		return Object.assign(Instrument.getDefaults(), {
			attack: 0,
			baseUrl: "",
			curve: "exponential" as const,
			onload: noOp,
			onerror: noOp,
			release: 0.1,
			urls: {},
			loop: false,
			loopEnd: 0,
			loopStart: 0,
		});
	}

	/**
	 * urls, baseUrl, onload and onerror aren't stored as regular class
	 * properties (unlike attack/release/curve), so the base implementation
	 * can't find them via `Reflect.has` and they'd be silently missing here.
	 */
	get(): SamplerOptions {
		return Object.assign(super.get(), {
			urls: this._urls,
			baseUrl: this._baseUrl,
			onload: this._onload,
			onerror: this._onerror,
		});
	}

	/**
	 * Returns the difference in steps between the given midi note at the closets sample.
	 */
	private _findClosest(midi: MidiNote): Interval {
		// searches within 8 octaves of the given midi note
		const MAX_INTERVAL = 96;
		let interval = 0;
		while (interval < MAX_INTERVAL) {
			// check above and below
			if (this._buffers.has(midi + interval)) {
				return -interval;
			} else if (this._buffers.has(midi - interval)) {
				return interval;
			}
			interval++;
		}
		throw new Error(`No available buffers for note: ${midi}`);
	}

	/**
	 * @param  notes	The note to play, or an array of notes.
	 * @param  time     When to play the note
	 * @param  velocity The velocity to play the sample back.
	 */
	triggerAttack(
		notes: Frequency | Frequency[],
		time?: Time,
		velocity: NormalRange = 1
	): this {
		this.log("triggerAttack", notes, time, velocity);
		if (!Array.isArray(notes)) {
			notes = [notes];
		}
		const offset = defaultArg(this._loopStart, 0);
		notes.forEach((note) => {
			const midiFloat = ftomf(
				new FrequencyClass(this.context, note).toFrequency()
			);
			const midi = Math.round(midiFloat) as MidiNote;
			const remainder = midiFloat - midi;
			// find the closest note pitch
			const difference = this._findClosest(midi);
			const closestNote = midi - difference;
			const buffer = this._buffers.get(closestNote);
			const playbackRate = intervalToFrequencyRatio(
				difference + remainder
			);
			const duration = this._loop
				? undefined
				: buffer.duration / playbackRate;
			// play that note
			const source = new ToneBufferSource({
				url: buffer,
				context: this.context,
				curve: this.curve,
				fadeIn: this.attack,
				fadeOut: this.release,
				loop: this._loop,
				loopStart: this._loopStart,
				loopEnd: this._loopEnd,
				playbackRate,
			}).connect(this.output);
			source.start(time, offset, duration, velocity);
			// add it to the active sources
			if (!isArray(this._activeSources.get(midi))) {
				this._activeSources.set(midi, []);
			}
			(this._activeSources.get(midi) as ToneBufferSource[]).push(source);

			// remove it when it's done
			source.onended = () => {
				if (this._activeSources?.has(midi)) {
					const sources = this._activeSources.get(
						midi
					) as ToneBufferSource[];
					const index = sources.indexOf(source);
					if (index !== -1) {
						sources.splice(index, 1);
					}
				}
			};
		});
		return this;
	}

	/**
	 * @param  notes	The note to release, or an array of notes.
	 * @param  time     	When to release the note.
	 */
	triggerRelease(notes: Frequency | Frequency[], time?: Time): this {
		this.log("triggerRelease", notes, time);
		if (!Array.isArray(notes)) {
			notes = [notes];
		}
		notes.forEach((note) => {
			const midi = new FrequencyClass(this.context, note).toMidi();
			// find the note
			if (
				this._activeSources.has(midi) &&
				(this._activeSources.get(midi) as ToneBufferSource[]).length
			) {
				const sources = this._activeSources.get(
					midi
				) as ToneBufferSource[];
				time = this.toSeconds(time);
				sources.forEach((source) => {
					source.stop(time);
				});
				this._activeSources.set(midi, []);
			}
		});
		return this;
	}

	/**
	 * Release all currently active notes.
	 * @param  time     	When to release the notes.
	 */
	releaseAll(time?: Time): this {
		const computedTime = this.toSeconds(time);
		this._activeSources.forEach((sources) => {
			while (sources.length) {
				const source = sources.shift() as ToneBufferSource;
				source.stop(computedTime);
			}
		});
		return this;
	}

	sync(): this {
		if (this._syncState()) {
			this._syncMethod("triggerAttack", 1);
			this._syncMethod("triggerRelease", 1);
		}
		return this;
	}

	/**
	 * Invoke the attack phase, then after the duration, invoke the release.
	 * @param  notes	The note to play and release, or an array of notes.
	 * @param  duration The time the note should be held
	 * @param  time     When to start the attack
	 * @param  velocity The velocity of the attack
	 */
	triggerAttackRelease(
		notes: Frequency[] | Frequency,
		duration: Time | Time[],
		time?: Time,
		velocity: NormalRange = 1
	): this {
		const computedTime = this.toSeconds(time);
		this.triggerAttack(notes, computedTime, velocity);
		if (isArray(duration)) {
			assert(
				isArray(notes),
				"notes must be an array when duration is array"
			);
			(notes as Frequency[]).forEach((note, index) => {
				const d = duration[Math.min(index, duration.length - 1)];
				this.triggerRelease(note, computedTime + this.toSeconds(d));
			});
		} else {
			this.triggerRelease(notes, computedTime + this.toSeconds(duration));
		}
		return this;
	}

	/**
	 * Add a note to the sampler.
	 * @param  note      The buffer's pitch.
	 * @param  url  Either the url of the buffer, or a buffer which will be added with the given name.
	 * @param  callback  The callback to invoke when the url is loaded.
	 */
	add(
		note: Note | MidiNote,
		url: string | ToneAudioBuffer | AudioBuffer,
		callback?: () => void
	): this {
		assert(
			isNote(note) || isFinite(note),
			`note must be a pitch or midi: ${note}`
		);
		if (isNote(note)) {
			// convert the note name to MIDI
			const mid = new FrequencyClass(this.context, note).toMidi();
			this._buffers.add(mid, url, callback);
		} else {
			// otherwise if it's numbers assume it's midi
			this._buffers.add(note, url, callback);
		}
		return this;
	}

	/**
	 * If the buffers are loaded or not
	 */
	get loaded(): boolean {
		return this._buffers.loaded;
	}

	/**
	 * Set the loop start and end. Will only loop if loop is set to true.
	 * @param loopStart The loop start time
	 * @param loopEnd The loop end time
	 * @example
	 * const sampler = new Tone.Sampler({
	 *      urls: {
	 *           A1: "https://tonejs.github.io/audio/berklee/guitar_chord4.mp3",
	 *      },
	 * }).toDestination();
	 * // loop between the given points
	 * sampler.setLoopPoints(0.2, 0.3);
	 * sampler.loop = true;
	 */
	setLoopPoints(loopStart: Time, loopEnd: Time): this {
		this.loopStart = loopStart;
		this.loopEnd = loopEnd;
		return this;
	}

	/**
	 * If loop is true, the loop will start at this position.
	 */
	get loopStart(): Time {
		return this._loopStart;
	}
	set loopStart(loopStart) {
		this._loopStart = loopStart;
		this._providedMidiNotes.forEach((midiNote) => {
			const buffer = this._buffers.get(midiNote);
			if (buffer.loaded) {
				assertRange(this.toSeconds(loopStart), 0, buffer.duration);
			}
		});
		// get the current sources
		this._activeSources.forEach((sourceList) => {
			sourceList.forEach((source) => {
				source.loopStart = loopStart;
			});
		});
	}

	/**
	 * If loop is true, the loop will end at this position.
	 */
	get loopEnd(): Time {
		return this._loopEnd;
	}
	set loopEnd(loopEnd) {
		this._loopEnd = loopEnd;
		this._providedMidiNotes.forEach((midiNote) => {
			const buffer = this._buffers.get(midiNote);
			if (buffer.loaded) {
				assertRange(this.toSeconds(loopEnd), 0, buffer.duration);
			}
		});
		// get the current sources
		this._activeSources.forEach((sourceList) => {
			sourceList.forEach((source) => {
				source.loopEnd = loopEnd;
			});
		});
	}

	/**
	 * If the buffers should loop once they are over.
	 * @example
	 * const sampler = new Tone.Sampler({
	 *      urls: {
	 *           A4: "https://tonejs.github.io/audio/berklee/femalevoice_aa_A4.mp3",
	 *      },
	 * }).toDestination();
	 * sampler.loop = true;
	 */
	get loop(): boolean {
		return this._loop;
	}
	set loop(loop) {
		// if no change, do nothing
		if (this._loop === loop) {
			return;
		}
		this._loop = loop;
		// set the loop of all of the sources
		this._activeSources.forEach((sourceList) => {
			sourceList.forEach((source) => {
				source.loop = loop;
			});
		});
	}

	/**
	 * Clean up
	 */
	dispose(): this {
		super.dispose();
		this._buffers.dispose();
		this._activeSources.forEach((sources) => {
			sources.forEach((source) => source.dispose());
		});
		this._activeSources.clear();
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../test/helper/Basic.js";
import { CompareToFile } from "../../test/helper/CompareToFile.js";
import { InstrumentTest } from "../../test/helper/InstrumentTests.js";
import { MonophonicTest } from "../../test/helper/MonophonicTests.js";
import { Offline } from "../../test/helper/Offline.js";
import { Frequency } from "../core/type/Frequency.js";
import { Synth } from "./Synth.js";

describe("Synth", () => {
	BasicTests(Synth);
	InstrumentTest(Synth, "C4");
	MonophonicTest(Synth, "C4");

	it("matches a file basic", () => {
		return CompareToFile(
			() => {
				const synth = new Synth().toDestination();
				synth.triggerAttackRelease("C4", 0.1, 0.05);
			},
			"synth_basic.wav",
			0.3
		);
	});

	it("matches a file melody", () => {
		return CompareToFile(
			() => {
				const synth = new Synth().toDestination();
				synth.triggerAttack("C4", 0);
				synth.triggerAttack("E4", 0.1, 0.5);
				synth.triggerAttackRelease("G4", 0.5, 0.3);
				synth.triggerAttackRelease("B4", 0.5, 0.5, 0.2);
			},
			"synth_melody.wav",
			0.3
		);
	});

	context("API", () => {
		it("can get and set oscillator attributes", () => {
			const simple = new Synth();
			simple.oscillator.type = "triangle";
			expect(simple.oscillator.type).to.equal("triangle");
			simple.dispose();
		});

		it("can get and set envelope attributes", () => {
			const simple = new Synth();
			simple.envelope.attack = 0.24;
			expect(simple.envelope.attack).to.equal(0.24);
			simple.dispose();
		});

		it("can be constructed with an options object", () => {
			const simple = new Synth({
				envelope: {
					sustain: 0.3,
				},
				oscillator: {
					type: "sine",
				},
				volume: -5,
			});
			expect(simple.envelope.sustain).to.equal(0.3);
			expect(simple.oscillator.type).to.equal("sine");
			expect(simple.volume.value).to.be.closeTo(-5, 0.1);
			simple.dispose();
		});

		it("can get/set attributes", () => {
			const simple = new Synth();
			simple.set({
				envelope: {
					decay: 0.24,
				},
			});
			expect(simple.get().envelope.decay).to.equal(0.24);
			simple.dispose();
		});

		it("can get does not include omitted oscillator attributes", () => {
			const simple = new Synth();
			expect(simple.get().oscillator).to.not.have.key("frequency");
			expect(simple.get().oscillator).to.not.have.key("detune");
			expect(Object.keys(simple.get().oscillator)).to.include("type");
			simple.dispose();
		});

		it("can be trigged with a Tone.Frequency", async () => {
			const buffer = await Offline(() => {
				const synth = new Synth().toDestination();
				synth.triggerAttack(Frequency("C4"), 0);
			});
			expect(buffer.isSilent()).to.be.false;
		});

		it("is silent after triggerAttack if sustain is 0", async () => {
			const buffer = await Offline(() => {
				const synth = new Synth({
					envelope: {
						attack: 0.1,
						decay: 0.1,
						sustain: 0,
					},
				}).toDestination();
				synth.triggerAttack("C4", 0);
			}, 0.5);
			expect(buffer.getTimeOfLastSound()).to.be.closeTo(0.2, 0.01);
		});
	});

	context("Transport sync", () => {
		it("is silent until the transport is started", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new Synth().sync().toDestination();
				synth.triggerAttackRelease("C4", 0.5);
				transport.start(0.5);
			}, 1);
			expect(buffer.getTimeOfFirstSound()).is.closeTo(0.5, 0.1);
		});

		it("stops when the transport is stopped", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new Synth({
					envelope: {
						release: 0,
					},
				})
					.sync()
					.toDestination();
				synth.triggerAttackRelease("C4", 0.5);
				transport.start(0.5).stop(1);
			}, 1.5);
			expect(buffer.getTimeOfLastSound()).is.closeTo(1, 0.1);
		});

		it("goes silent at the loop boundary", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new Synth({
					envelope: {
						release: 0,
					},
				})
					.sync()
					.toDestination();
				synth.triggerAttackRelease("C4", 0.8, 0.5);
				transport.loopEnd = 1;
				transport.loop = true;
				transport.start();
			}, 2);
			expect(buffer.getRmsAtTime(0)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(0.6)).to.be.closeTo(0.2, 0.05);
			expect(buffer.getRmsAtTime(1.1)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(1.6)).to.be.closeTo(0.2, 0.05);
		});

		it("can unsync", async () => {
			const buffer = await Offline(({ transport }) => {
				const synth = new Synth({
					envelope: {
						sustain: 1,
						release: 0,
					},
				})
					.sync()
					.toDestination()
					.unsync();
				synth.triggerAttackRelease("C4", 1, 0.5);
				transport.start().stop(1);
			}, 2);
			expect(buffer.getRmsAtTime(0)).to.be.closeTo(0, 0.05);
			expect(buffer.getRmsAtTime(0.6)).to.be.closeTo(0.6, 0.05);
			expect(buffer.getRmsAtTime(1.4)).to.be.closeTo(0.6, 0.05);
			expect(buffer.getRmsAtTime(1.6)).to.be.closeTo(0, 0.05);
		});
	});

	context("Portamento", () => {
		it("can play notes with a portamento", async () => {
			const buffer = await Offline(() => {
				const synth = new Synth({
					portamento: 0.1,
				});
				expect(synth.portamento).to.equal(0.1);
				synth.frequency.toDestination();
				synth.triggerAttack(440, 0);
				synth.triggerAttack(880, 0.1);
			}, 0.2);
			buffer.forEach((val, time) => {
				if (time < 0.1) {
					expect(val).to.be.closeTo(440, 1);
				} else if (time < 0.2) {
					expect(val).to.within(440, 880);
				} else {
					expect(val).to.be.closeTo(880, 1);
				}
			});
		});
	});
});

import { AmplitudeEnvelope } from "../component/envelope/AmplitudeEnvelope.js";
import { Envelope, EnvelopeOptions } from "../component/envelope/Envelope.js";
import {
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { NormalRange, Seconds, Time } from "../core/type/Units.js";
import { omitFromObject, optionsFromArguments } from "../core/util/Defaults.js";
import { readOnly } from "../core/util/Interface.js";
import { RecursivePartial } from "../core/util/Interface.js";
import { Signal } from "../signal/Signal.js";
import { OmniOscillator } from "../source/oscillator/OmniOscillator.js";
import {
	OmniOscillatorOptions,
	OmniOscillatorSynthOptions,
} from "../source/oscillator/OscillatorInterface.js";
import { Source } from "../source/Source.js";
import { Monophonic, MonophonicOptions } from "./Monophonic.js";

export interface SynthOptions extends MonophonicOptions {
	oscillator: OmniOscillatorSynthOptions;
	envelope: Omit<EnvelopeOptions, keyof ToneAudioNodeOptions>;
}

/**
 * Synth is composed simply of a {@link OmniOscillator} routed through an {@link AmplitudeEnvelope}.
 * ```
 * +----------------+   +-------------------+
 * | OmniOscillator +>--> AmplitudeEnvelope +>--> Output
 * +----------------+   +-------------------+
 * ```
 * @example
 * const synth = new Tone.Synth().toDestination();
 * synth.triggerAttackRelease("C4", "8n");
 * @category Instrument
 */
export class Synth<
	Options extends SynthOptions = SynthOptions,
> extends Monophonic<Options> {
	readonly name: string = "Synth";

	/**
	 * The oscillator.
	 */
	readonly oscillator: OmniOscillator<any>;

	/**
	 * The frequency signal
	 */
	readonly frequency: Signal<"frequency">;

	/**
	 * The detune signal
	 */
	readonly detune: Signal<"cents">;

	/**
	 * The envelope
	 */
	readonly envelope: AmplitudeEnvelope;

	/**
	 * @param options the options available for the synth.
	 */
	constructor(options?: RecursivePartial<SynthOptions>);
	constructor() {
		const options = optionsFromArguments(Synth.getDefaults(), arguments);
		super(options);

		this.oscillator = new OmniOscillator(
			Object.assign(
				{
					context: this.context,
					detune: options.detune,
					onstop: () => this.onsilence(this),
				},
				options.oscillator
			)
		);

		this.frequency = this.oscillator.frequency;
		this.detune = this.oscillator.detune;

		this.envelope = new AmplitudeEnvelope(
			Object.assign(
				{
					context: this.context,
				},
				options.envelope
			)
		);

		// connect the oscillators to the output
		this.oscillator.chain(this.envelope, this.output);
		readOnly(this, ["oscillator", "frequency", "detune", "envelope"]);
	}

	static getDefaults(): SynthOptions {
		return Object.assign(Monophonic.getDefaults(), {
			envelope: Object.assign(
				omitFromObject(
					Envelope.getDefaults(),
					Object.keys(ToneAudioNode.getDefaults())
				),
				{
					attack: 0.005,
					decay: 0.1,
					release: 1,
					sustain: 0.3,
				}
			),
			oscillator: Object.assign(
				omitFromObject(OmniOscillator.getDefaults(), [
					...Object.keys(Source.getDefaults()),
					"frequency",
					"detune",
				]),
				{
					type: "triangle",
				}
			) as OmniOscillatorOptions,
		});
	}

	/**
	 * start the attack portion of the envelope
	 * @param time the time the attack should start
	 * @param velocity the velocity of the note (0-1)
	 */
	protected _triggerEnvelopeAttack(time: Seconds, velocity: number): void {
		// the envelopes
		this.envelope.triggerAttack(time, velocity);
		this.oscillator.start(time);
		// if there is no release portion, stop the oscillator
		if (this.envelope.sustain === 0) {
			const computedAttack = this.toSeconds(this.envelope.attack);
			const computedDecay = this.toSeconds(this.envelope.decay);
			this.oscillator.stop(time + computedAttack + computedDecay);
		}
	}

	/**
	 * start the release portion of the envelope
	 * @param time the time the release should start
	 */
	protected _triggerEnvelopeRelease(time: Seconds): void {
		this.envelope.triggerRelease(time);
		this.oscillator.stop(time + this.toSeconds(this.envelope.release));
	}

	getLevelAtTime(time: Time): NormalRange {
		time = this.toSeconds(time);
		return this.envelope.getValueAtTime(time);
	}

	/**
	 * clean up
	 */
	dispose(): this {
		super.dispose();
		this.oscillator.dispose();
		this.envelope.dispose();
