			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.33 / 2)).to.be.closeTo(0.5, 0.01);
			expect(buffer.getValueAtTime(0.33)).to.be.closeTo(1, 0.02);
			expect(buffer.getValueAtTime(0.66)).to.be.closeTo(0.5, 0.02);
			expect(buffer.getValueAtTime(0.99)).to.be.closeTo(0.2, 0.02);
		});

		it("can set a value curve in the future", async () => {
			const buffer = await Offline(() => {
				const sig = new Signal(0).toDestination();
				sig.setValueCurveAtTime([0, 1, 0.5, 0.2], 0.5, 1);
			}, 1.5);
			expect(buffer.getValueAtTime(0 + 0.5)).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.33 / 2 + 0.5)).to.be.closeTo(
				0.5,
				0.01
			);
			expect(buffer.getValueAtTime(0.33 + 0.5)).to.be.closeTo(1, 0.02);
			expect(buffer.getValueAtTime(0.66 + 0.5)).to.be.closeTo(0.5, 0.02);
			expect(buffer.getValueAtTime(0.99 + 0.5)).to.be.closeTo(0.2, 0.02);
		});

		it("can set an exponential approach", async () => {
			const buffer = await Offline(() => {
				const sig = new Signal(0).toDestination();
				sig.exponentialApproachValueAtTime(2, 0.1, 0.5);
			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.1)).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.4)).to.be.closeTo(1.9, 0.1);
			expect(buffer.getValueAtTime(0.6)).to.be.closeTo(2, 0.01);
		});

		it("can set a target at time", async () => {
			const buffer = await Offline(() => {
				const sig = new Signal(0).toDestination();
				sig.setTargetAtTime(2, 0.1, 0.1);
			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.01);
			expect(buffer.getValueAtTime(0.6)).to.be.closeTo(2, 0.1);
		});
	});

	context("Units", () => {
		it("can be created with specific units", () => {
			const signal = new Signal(0, "bpm");
			expect(signal.units).to.equal("bpm");
			signal.dispose();
		});

		it("can evaluate the given units", () => {
			const signal = new Signal(2, "time");
			signal.value = 0.5;
			expect(signal.value).to.be.closeTo(0.5, 0.001);
			signal.dispose();
		});

		it("converts the given units when passed in the constructor", () => {
			return ConstantOutput(() => {
				const signal = new Signal({
					units: "decibels",
					value: -10,
				}).toDestination();
			}, 0.315);
		});

		it("can be set to not convert the given units in constructor", () => {
			return ConstantOutput(() => {
				const signal = new Signal({
					convert: false,
					units: "decibels",
					value: -10,
				}).toDestination();
			}, -10);
		});

		it("can be set to not convert the given units in member", () => {
			return ConstantOutput(() => {
				const signal = new Signal({
					units: "decibels",
				}).toDestination();
				signal.convert = false;
				signal.value = -10;
			}, -10);
		});

		it("converts Frequency units", () => {
			const signal = new Signal("50hz", "frequency");
			expect(signal.value).to.be.closeTo(50, 0.01);
			signal.dispose();
		});

		it("converts Time units", () => {
			const signal = new Signal("4n", "time");
			expect(signal.value).to.be.closeTo(0.5, 0.01);
			signal.dispose();
		});

		it("converts NormalRange units", () => {
			expect(() => {
				new Signal(2, "normalRange");
			}).to.throw(RangeError);
			const signal = new Signal(1, "normalRange");
			expect(signal.value).to.be.closeTo(1, 0.01);
			expect(signal.minValue).to.be.equal(0);
			expect(signal.maxValue).to.be.equal(1);
			signal.dispose();
		});

		it("converts AudioRange units", () => {
			expect(() => {
				new Signal(-2, "audioRange");
			}).to.throw(RangeError);
			const signal = new Signal(-1, "audioRange");
			expect(signal.value).to.be.closeTo(-1, 0.01);
			expect(signal.minValue).to.be.equal(-1);
			expect(signal.maxValue).to.be.equal(1);
			signal.dispose();
		});

		it("converts Positive units", () => {
			expect(() => {
				new Signal(-2, "positive");
			}).to.throw(RangeError);
			const signal = new Signal(100, "positive");
			expect(signal.value).to.be.closeTo(100, 0.01);
			expect(signal.minValue).to.be.equal(0);
			signal.dispose();
		});
	});

	context("Transport Syncing", () => {
		it("maintains its original value after being synced to the transport", () => {
			return ConstantOutput(({ transport }) => {
				const sig = new Signal(3).toDestination();
				transport.syncSignal(sig);
			}, 3);
		});

		it("keeps the ratio when the bpm changes", () => {
			return ConstantOutput(({ transport }) => {
				transport.bpm.value = 120;
				const sig = new Signal(5).toDestination();
				transport.syncSignal(sig);
				transport.bpm.value = 240;
			}, 10);
		});

		it("keeps the ratio of a time signal when the bpm changes", () => {
			return ConstantOutput(({ transport }) => {
				transport.bpm.value = 120;
				const sig = new Signal("4n", "time").toDestination();
				transport.syncSignal(sig);
				transport.bpm.value = 240;
			}, 0.25);
		});

		it("outputs 0 when the signal is 0", () => {
			return ConstantOutput(({ transport }) => {
				transport.bpm.value = 120;
				const sig = new Signal(0).toDestination();
				transport.syncSignal(sig);
				transport.bpm.value = 240;
			}, 0);
		});

		it("can ramp along with the bpm", async () => {
			const buffer = await Offline(({ transport }) => {
				transport.bpm.value = 120;
				const sig = new Signal(2).toDestination();
				transport.syncSignal(sig);
				transport.bpm.rampTo(240, 0.5);
			});
			buffer.forEach((sample, time) => {
				if (time >= 0.5) {
					expect(sample).to.be.closeTo(4, 0.04);
				} else if (time < 0.4) {
					expect(sample).to.be.within(1.95, 3);
				}
			});
		});

		it("returns to the original value when unsynced", () => {
			return ConstantOutput(({ transport }) => {
				transport.bpm.value = 120;
				const sig = new Signal(5).toDestination();
				transport.syncSignal(sig);
				transport.bpm.value = 240;
				transport.unsyncSignal(sig);
			}, 5);
		});
	});

	context("connectSignal/disconnectSignal", () => {
		it("can connect a Signal to an AudioNode", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const gain = new Gain({
					gain: 0.5,
					context,
				}).toDestination();
				connectSignal(sig, gain);
			}, 1.5);
		});

		it("can connect a Signal to a Param", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const scalar = new Signal({
					value: 2,
					context,
				});
				const gain = new Gain({
					gain: 0.5,
					context,
				}).toDestination();
				connectSignal(sig, gain);
				connectSignal(scalar, gain.gain);
				// gain of 0.5 is overridden
				expect(gain.gain.value).to.equal(0);
			}, 6);
		});

		it("can connect a Signal to a Signal", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const output = new Signal({
					value: 0.5,
					context,
				}).toDestination();

				connectSignal(sig, output);
				expect(output.overridden).to.be.true;
			}, 3);
		});

		it("can disconnect a Signal from an AudioNode", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const gain = new Gain({
					gain: 0.5,
					context,
				}).toDestination();
				connectSignal(sig, gain);
				disconnectSignal(sig, gain);
			}, 0);
		});

		it("can disconnect a Signal from a Param", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const scalar = new Signal({
					value: 2,
					context,
				});
				const gain = new Gain({
					gain: 0.5,
					context,
				}).toDestination();
				connectSignal(sig, gain);
				connectSignal(scalar, gain.gain);
				// gain of 0.5 is overridden
				expect(gain.gain.value).to.equal(0);

				disconnectSignal(scalar, gain.gain);
				// the original value is restored
				expect(gain.gain.value).to.equal(0.5);
			}, 1.5);
		});

		it("can disconnect a Signal from a Signal", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const output = new Signal({
					value: 2,
					context,
				}).toDestination();

				connectSignal(sig, output);
				expect(output.overridden).to.be.true;
				expect(output.value).to.equal(0);

				disconnectSignal(sig, output);
				expect(output.value).to.equal(2);
				expect(output.overridden).to.be.false;
			}, 2);
		});

		it("can disconnect from all the connected nodes", async () => {
			await ConstantOutput(async (context) => {
				// initially destination is 2
				const output0 = new Signal(1).toDestination();
				const output1 = new Signal(1).toDestination();

				// both should now equal 0
				const sig = new Signal(0).connect(output0).connect(output1);

				// disconnect from both
				sig.disconnect();
			}, 2);
		});

		it("can disconnect from a specific node", async () => {
			await ConstantOutput(() => {
				// initially destination is 3
				const output0 = new Signal(1).toDestination();
				const output1 = new Signal(2).toDestination();

				const sig = new Signal(3);
				sig.connect(output0);
				sig.connect(output1);

				// output0 goes back to 1 after disconnecting
				sig.disconnect(output0);
			}, 4); // 1 + 3
		});

		it("disconnects every input when no input is passed in", async () => {
			await ConstantOutput(() => {
				// initially destination is 1
				const output = new Signal(1).toDestination();

				// overwrites it with 0
				const sig = new Signal(0).connect(output, 0);

				// disconnects the signal and goes back to 1
				sig.disconnect(output);
			}, 1);
		});

		it("disconnects every output when no output is passed in", async () => {
			await ConstantOutput(() => {
				// initially destination is 1
				const output = new Signal(1).toDestination();

				// overwrites it with 0
				const sig = new Signal(0).connect(output, undefined, 0);

				// disconnects the signal and goes back to 1
				sig.disconnect(output);
			}, 1);
		});

		it("disconnects everything if no destination is passed in", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const output = new Signal({
					value: 2,
					context,
				}).toDestination();

				// overridden with value of 3
				connectSignal(sig, output);
				expect(output.overridden).to.be.true;

				// disconnect goes back to 2
				sig.disconnect();
				expect(output.overridden).to.be.false;
			}, 2);
		});

		it("can connect multiple times with no affect", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const output = new Signal({
					value: 2,
					context,
				}).toDestination();

				connectSignal(sig, output);
				expect(output.overridden).to.be.true;

				// no affect when called again
				connectSignal(sig, output);
			}, 3);
		});

		it("disconnecting multiple times throws an error", () => {
			return ConstantOutput((context) => {
				const sig = new Signal({
					value: 3,
					context,
				});
				const output = new Signal({
					value: 2,
					context,
				}).toDestination();

				connectSignal(sig, output);

				disconnectSignal(sig, output);
				expect(() => disconnectSignal(sig, output)).to.throw(Error);
			}, 2);
		});
	});
});

import { AbstractParam } from "../core/context/AbstractParam.js";
import { Param } from "../core/context/Param.js";
import {
	disconnect,
	InputNode,
	OutputNode,
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { connect } from "../core/context/ToneAudioNode.js";
import { Time, UnitMap, UnitName } from "../core/type/Units.js";
import { isAudioParam } from "../core/util/AdvancedTypeCheck.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { isUndef } from "../core/util/TypeCheck.js";
import { ToneConstantSource } from "./ToneConstantSource.js";

export interface SignalOptions<TypeName extends UnitName>
	extends ToneAudioNodeOptions {
	value: UnitMap[TypeName];
	units: TypeName;
	convert: boolean;
	minValue?: number;
	maxValue?: number;
}

/**
 * A signal is an audio-rate value. Tone.Signal is a core component of the library.
 * Unlike a number, Signals can be scheduled with sample-level accuracy. Tone.Signal
 * has all of the methods available to native Web Audio
 * [AudioParam](http://webaudio.github.io/web-audio-api/#the-audioparam-interface)
 * as well as additional conveniences. Read more about working with signals
 * [here](https://github.com/Tonejs/Tone.js/wiki/Signals).
 *
 * @example
 * const osc = new Tone.Oscillator().toDestination().start();
 * // a schedulable signal which can be connected to control an AudioParam or another Signal
 * const signal = new Tone.Signal({
 * 	value: "C4",
 * 	units: "frequency"
 * }).connect(osc.frequency);
 * // the scheduled ramp controls the connected signal
 * signal.rampTo("C2", 4, "+0.5");
 * @category Signal
 */
export class Signal<TypeName extends UnitName = "number">
	extends ToneAudioNode<SignalOptions<any>>
	implements AbstractParam<TypeName>
{
	readonly name: string = "Signal";

	/**
	 * Indicates if the value should be overridden on connection.
	 */
	readonly override: boolean = true;

	/**
	 * The constant source node which generates the signal
	 */
	protected _constantSource: ToneConstantSource<TypeName>;
	readonly output: OutputNode;
	protected _param: Param<TypeName>;
	readonly input: InputNode;

	/**
	 * @param value Initial value of the signal
	 * @param units The unit name, e.g. "frequency"
	 */
	constructor(value?: UnitMap[TypeName], units?: TypeName);
	constructor(options?: Partial<SignalOptions<TypeName>>);
	constructor() {
		const options = optionsFromArguments(Signal.getDefaults(), arguments, [
			"value",
			"units",
		]) as SignalOptions<TypeName>;
		super(options);

		this.output = this._constantSource = new ToneConstantSource({
			context: this.context,
			convert: options.convert,
			offset: options.value,
			units: options.units,
			minValue: options.minValue,
			maxValue: options.maxValue,
		});
		this._constantSource.start(0);
		this.input = this._param = this._constantSource.offset;
	}
	/** @inheritdoc */
	static getDefaults(): SignalOptions<any> {
		return Object.assign(ToneAudioNode.getDefaults(), {
			convert: true,
			units: "number" as UnitName,
			value: 0,
		});
	}
	/** @inheritdoc */
	connect(destination: InputNode, outputNum = 0, inputNum = 0): this {
		// start it only when connected to something
		connectSignal(this, destination, outputNum, inputNum);
		return this;
	}
	/** @inheritdoc */
	disconnect(
		destination?: InputNode,
		outputNum?: number,
		inputNum?: number
	): this {
		// disconnect the signal
		disconnectSignal(this, destination, outputNum, inputNum);
		return this;
	}
	/** @inheritdoc */
	dispose(): this {
		super.dispose();
		this._param.dispose();
		this._constantSource.dispose();
		return this;
	}

	//-------------------------------------
	// ABSTRACT PARAM INTERFACE
	// just a proxy for the ConstantSourceNode's offset AudioParam
	// all docs are generated from AbstractParam.ts
	//-------------------------------------

	/** @inheritdoc */
	setValueAtTime(value: UnitMap[TypeName], time: Time): this {
		this._param.setValueAtTime(value, time);
		return this;
	}
	/** @inheritdoc */
	getValueAtTime(time: Time): UnitMap[TypeName] {
		return this._param.getValueAtTime(time);
	}
	/** @inheritdoc */
	setRampPoint(time: Time): this {
		this._param.setRampPoint(time);
		return this;
	}
	/** @inheritdoc */
	linearRampToValueAtTime(value: UnitMap[TypeName], time: Time): this {
		this._param.linearRampToValueAtTime(value, time);
		return this;
	}
	/** @inheritdoc */
	exponentialRampToValueAtTime(value: UnitMap[TypeName], time: Time): this {
		this._param.exponentialRampToValueAtTime(value, time);
		return this;
	}
	/** @inheritdoc */
	exponentialRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this {
		this._param.exponentialRampTo(value, rampTime, startTime);
		return this;
	}
	/** @inheritdoc */
	linearRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this {
		this._param.linearRampTo(value, rampTime, startTime);
		return this;
	}
	/** @inheritdoc */
	targetRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this {
		this._param.targetRampTo(value, rampTime, startTime);
		return this;
	}
	/** @inheritdoc */
	exponentialApproachValueAtTime(
		value: UnitMap[TypeName],
		time: Time,
		rampTime: Time
	): this {
		this._param.exponentialApproachValueAtTime(value, time, rampTime);
		return this;
	}
	/** @inheritdoc */
	setTargetAtTime(
		value: UnitMap[TypeName],
		startTime: Time,
		timeConstant: number
	): this {
		this._param.setTargetAtTime(value, startTime, timeConstant);
		return this;
	}
	/** @inheritdoc */
	setValueCurveAtTime(
		values: UnitMap[TypeName][],
		startTime: Time,
		duration: Time,
		scaling?: number
	): this {
		this._param.setValueCurveAtTime(values, startTime, duration, scaling);
		return this;
	}
	/** @inheritdoc */
	cancelScheduledValues(time: Time): this {
		this._param.cancelScheduledValues(time);
		return this;
	}
	/** @inheritdoc */
	cancelAndHoldAtTime(time: Time): this {
		this._param.cancelAndHoldAtTime(time);
		return this;
	}
	/** @inheritdoc */
	rampTo(value: UnitMap[TypeName], rampTime: Time, startTime?: Time): this {
		this._param.rampTo(value, rampTime, startTime);
		return this;
	}
	/** @inheritdoc */
	get value(): UnitMap[TypeName] {
		return this._param.value;
	}
	set value(value: UnitMap[TypeName]) {
		this._param.value = value;
	}
	/** @inheritdoc */
	get convert(): boolean {
		return this._param.convert;
	}
	set convert(convert: boolean) {
		this._param.convert = convert;
	}
	/** @inheritdoc */
	get units(): UnitName {
		return this._param.units;
	}
	/** @inheritdoc */
	get overridden(): boolean {
		return this._param.overridden;
	}
	set overridden(overridden: boolean) {
		this._param.overridden = overridden;
	}
	/** @inheritdoc */
	get maxValue(): number {
		return this._param.maxValue;
	}
	get minValue(): number {
		return this._param.minValue;
	}

	/**
	 * @see {@link Param.apply}.
	 */
	apply(param: Param | AudioParam): this {
		this._param.apply(param);
		return this;
	}
}

/**
 * Keep track of connected signals so they can be disconnected and restored to their previous value
 */
const connectedSignals = new WeakMap<
	OutputNode,
	Array<{
		destination: Param | AudioParam | Signal;
		outputNum: number;
		inputNum: number;
		/**
		 * The value before overriding
		 */
		previousValue: number;
	}>
>();

/**
 * When connecting from a signal, it's necessary to zero out the node destination
 * node if that node is also a signal. If the destination is not 0, then the values
 * will be summed. This method insures that the output of the destination signal will
 * be the same as the source signal, making the destination signal a pass through node.
 * @param signal The output signal to connect from
 * @param destination the destination to connect to
 * @param outputNum the optional output number
 * @param inputNum the input number
 */
export function connectSignal(
	signal: OutputNode,
	destination: InputNode,
	outputNum?: number,
	inputNum?: number
): void {
	if (
		destination instanceof Param ||
		isAudioParam(destination) ||
		(destination instanceof Signal && destination.override)
	) {
		const previousValue = destination.value;
		// cancel changes
		destination.cancelScheduledValues(0);
		// reset the value
		destination.setValueAtTime(0, 0);
		// mark the value as overridden
		if (destination instanceof Signal || destination instanceof Param) {
			destination.overridden = true;
		}
		// store the connection
		if (!connectedSignals.has(signal)) {
			connectedSignals.set(signal, []);
		}
		connectedSignals.get(signal)?.push({
			destination,
			outputNum: outputNum || 0,
			inputNum: inputNum || 0,
			previousValue,
		});
	}
	connect(signal, destination, outputNum, inputNum);
}

/**
 * Disconnect a signal connection and restore the value of the destination if
 * it was a signal that was overridden by the connection.
 * @param signal
 * @param destination
 * @param outputNum
 * @param inputNum
 */
export function disconnectSignal(
	signal: OutputNode,
	destination?: InputNode,
	outputNum?: number,
	inputNum?: number
): void {
	if (
		destination instanceof Param ||
		isAudioParam(destination) ||
		(destination instanceof Signal && destination.override) ||
		destination === undefined
	) {
		if (connectedSignals.has(signal)) {
			let connections = connectedSignals.get(signal)!;

			if (destination) {
				connections = connections.filter((conn) => {
					return (
						conn.destination === destination &&
						(isUndef(outputNum) || conn.outputNum === outputNum) &&
						(isUndef(inputNum) || conn.inputNum === inputNum)
					);
				});
			}

			if (!connections.length) {
				throw new Error("Not connected to destination node");
			}

			// restore the value
			connections.forEach((connection) => {
				if (
					connection.destination instanceof Signal ||
					connection.destination instanceof Param
				) {
					connection.destination.overridden = false;
				}
				connection.destination.setValueAtTime(
					connection.previousValue,
					0
				);
			});
			// remove the connection from the stored array
			connectedSignals.set(
				signal,
				connectedSignals
					.get(signal)!
					.filter((conn) => !connections.includes(conn))
			);
		}
	}
	disconnect(signal, destination, outputNum, inputNum);
}

