describe("SignalOperator", () => {
	class TestSignalOperator extends SignalOperator<SignalOperatorOptions> {
		name = "TestSignalOperator";

		input: Signal;
		output: Signal;

		constructor(options: SignalOperatorOptions) {
			super(options);
