import {
	InputNode,
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { connectSignal, disconnectSignal } from "./Signal.js";

export type SignalOperatorOptions = ToneAudioNodeOptions;

/**
 * A signal operator has an input and output and modifies the signal.
 */
export abstract class SignalOperator<
	Options extends SignalOperatorOptions,
> extends ToneAudioNode<Options> {
	constructor(options?: Partial<Options>);
	constructor() {
		super(
			optionsFromArguments(SignalOperator.getDefaults(), arguments, [
				"context",
			])
		);
	}

	/** @inheritdoc */
	connect(destination: InputNode, outputNum = 0, inputNum = 0): this {
		connectSignal(this, destination, outputNum, inputNum);
		return this;
	}

	/** @inheritdoc */
	disconnect(destination: InputNode, outputNum = 0, inputNum = 0): this {
		disconnectSignal(this, destination, outputNum, inputNum);
		return this;
	}
}

import { BasicTests } from "../../test/helper/Basic.js";
import { connectFrom, connectTo } from "../../test/helper/Connect.js";
import { ConstantOutput } from "../../test/helper/ConstantOutput.js";
import { Signal } from "./Signal.js";
import { Subtract } from "./Subtract.js";

describe("Subtract", () => {
	BasicTests(Subtract);

	context("Subtraction", () => {
		it("handles input and output connections", () => {
			const subtract = new Subtract();
			connectFrom().connect(subtract);
			connectFrom().connect(subtract.subtrahend);
			subtract.connect(connectTo());
			subtract.dispose();
		});

		it("correctly subtracts a signal and a number", () => {
			return ConstantOutput(() => {
				const signal = new Signal(0);
				const sub = new Subtract(3);
				signal.connect(sub);
				sub.toDestination();
			}, -3);
		});

		it("can set the scalar value after construction", () => {
			return ConstantOutput(() => {
				const signal = new Signal(-2);
				const sub = new Subtract(0);
				sub.value = 4;
				signal.connect(sub);
				sub.toDestination();
			}, -6);
		});

		it("can handle negative values", () => {
			return ConstantOutput(() => {
				const signal = new Signal(4);
				const sub = new Subtract(-2);
				signal.connect(sub);
				sub.toDestination();
			}, 6);
		});

		it("can subtract two signals", () => {
			return ConstantOutput(() => {
				const sigA = new Signal(1);
				const sigB = new Signal(4);
				const sub = new Subtract();
				sigA.connect(sub);
				sigB.connect(sub.subtrahend);
				sub.toDestination();
			}, -3);
		});
	});
});

import { Gain } from "../core/context/Gain.js";
import { Param } from "../core/context/Param.js";
import { connectSeries } from "../core/context/ToneAudioNode.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { Negate } from "../signal/Negate.js";
import { Signal, SignalOptions } from "../signal/Signal.js";

/**
 * Subtract the signal connected to the input is subtracted from the signal connected
 * The subtrahend.
 *
 * @example
 * // subtract a scalar from a signal
 * const sub = new Tone.Subtract(1);
 * const sig = new Tone.Signal(4).connect(sub);
 * // the output of sub is 3.
 * @example
 * // subtract two signals
 * const sub = new Tone.Subtract();
 * const sigA = new Tone.Signal(10);
 * const sigB = new Tone.Signal(2.5);
 * sigA.connect(sub);
 * sigB.connect(sub.subtrahend);
 * // output of sub is 7.5
 * @category Signal
 */
export class Subtract extends Signal {
	override = false;

	readonly name: string = "Subtract";

	/**
	 * the summing node
	 */
	private _sum: Gain = new Gain({ context: this.context });
	readonly input: Gain = this._sum;
	readonly output: Gain = this._sum;

	/**
	 * Negate the input of the second input before connecting it to the summing node.
	 */
	private _neg: Negate = new Negate({ context: this.context });

	/**
	 * The value which is subtracted from the main signal
	 */
	subtrahend: Param<"number"> = this._param;

	/**
	 * @param value The value to subtract from the incoming signal. If the value
	 *             is omitted, it will subtract the second signal from the first.
	 */
	constructor(value?: number);
	constructor(options?: Partial<SignalOptions<"number">>);
	constructor() {
		super(
			optionsFromArguments(Subtract.getDefaults(), arguments, ["value"])
		);

		connectSeries(this._constantSource, this._neg, this._sum);
	}

	static getDefaults(): SignalOptions<"number"> {
		return Object.assign(Signal.getDefaults(), {
			value: 0,
		});
	}

	dispose(): this {
		super.dispose();
		this._neg.dispose();
		this._sum.dispose();
		return this;
	}
}

import "../core/clock/Transport.js";
import "../core/context/Destination.js";

import { expect } from "chai";

import { BasicTests } from "../../test/helper/Basic.js";
import { Offline } from "../../test/helper/Offline.js";
import { dbToGain } from "../core/type/Conversions.js";
import { SyncedSignal } from "./SyncedSignal.js";

describe("SyncedSignal", () => {
	BasicTests(SyncedSignal);

	context("Scheduling Events", () => {
		it("can schedule a change in the future", () => {
			const sched = new SyncedSignal(1);
			sched.setValueAtTime(2, 0.2);
			sched.dispose();
		});

		it("can schedule setValueAtTime relative to the Transport", async () => {
			const buffer = await Offline(
				({ transport }) => {
					const sched = new SyncedSignal(1).toDestination();
					sched.setValueAtTime(2, 0.1);
					sched.setValueAtTime(3, 0.2);
					transport.start(0.1);
				},
				0.4,
				1
			);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.1)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.201)).to.be.closeTo(2, 0.07);
			expect(buffer.getValueAtTime(0.301)).to.be.closeTo(3, 0.07);
		});

		it("can schedule linearRampToValueAtTime relative to the Transport", async () => {
			const buffer = await Offline(
				({ transport }) => {
					const sched = new SyncedSignal(1).toDestination();
					sched.setValueAtTime(1, 0.1);
					sched.linearRampToValueAtTime(2, 0.2);
					transport.start(0.1);
				},
				0.4,
				1
			);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.1)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.2)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.25)).to.be.closeTo(1.5, 0.07);
			expect(buffer.getValueAtTime(0.301)).to.be.closeTo(2, 0.07);
		});

		it("can schedule exponentialRampToValueAtTime relative to the Transport", async () => {
			const buffer = await Offline(
				({ transport }) => {
					const sched = new SyncedSignal(1).toDestination();
					sched.setValueAtTime(1, 0.1);
					sched.exponentialRampToValueAtTime(2, 0.2);
					transport.start(0.1);
				},
				0.4,
				1
			);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.1)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.2)).to.be.closeTo(1, 0.07);
			expect(buffer.getValueAtTime(0.25)).to.be.closeTo(1.4, 0.07);
			expect(buffer.getValueAtTime(0.301)).to.be.closeTo(2, 0.07);
		});

		it("can get exponential ramp value in the future", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0.5).toDestination();
				sched.setValueAtTime(0.5, 0);
				sched.exponentialRampToValueAtTime(1, 0.2);
				sched.exponentialRampToValueAtTime(0.5, 0.4);
				transport.start(0.1);
			}, 0.6);
			buffer.forEach((sample, time) => {
				expect(sample).to.be.closeTo(
					sched.getValueAtTime(time - 0.1),
					0.07
				);
			});
		});

		it("can get exponential approach in the future", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0.5).toDestination();
				sched.setValueAtTime(0.5, 0);
				sched.setTargetAtTime(1, 0.2, 0.2);
				transport.start(0.1);
			}, 0.6);
			buffer.forEach((sample, time) => {
				expect(sample).to.be.closeTo(
					sched.getValueAtTime(time - 0.1),
					0.07
				);
			});
		});

		it("can loop the signal when the Transport loops", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(1).toDestination();
				transport.setLoopPoints(0, 1);
				transport.loop = true;
				sched.setValueAtTime(1, 0);
				sched.setValueAtTime(2, 0.5);
				transport.start(0);
			}, 2);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(1, 0.01);
			expect(buffer.getValueAtTime(0.5)).to.be.closeTo(2, 0.01);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(1, 0.01);
			expect(buffer.getValueAtTime(1.5)).to.be.closeTo(2, 0.01);
		});

		it("can get set a curve in the future", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0).toDestination();
				sched.setValueCurveAtTime([0, 1, 0.2, 0.8, 0], 0, 1);
				transport.start(0.2);
			}, 1);
			buffer.forEach((sample, time) => {
				expect(sample).to.be.closeTo(
					sched.getValueAtTime(time - 0.2),
					0.07
				);
			});
		});

		it("can scale a curve value", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(1).toDestination();
				sched.setValueCurveAtTime([0, 1, 0], 0, 1, 0.5);
				transport.start(0);
			}, 1);
			buffer.forEach((sample) => {
				expect(sample).to.be.at.most(0.51);
			});
		});

		it("can schedule a linear ramp between two times", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0).toDestination();
				sched.linearRampTo(1, 1, 1);
				transport.start(0);
			}, 3);
			expect(buffer.getValueAtTime(0)).to.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(0.5)).to.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(1)).to.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(1.5)).to.closeTo(0.5, 0.1);
			expect(buffer.getValueAtTime(2)).to.closeTo(1, 0.1);
		});

		it("can get exponential ramp value between two times", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(1).toDestination();
				sched.exponentialRampTo(3, 1, 1);
				transport.start(0);
			}, 3);
			expect(buffer.getValueAtTime(0)).to.closeTo(1, 0.1);
			expect(buffer.getValueAtTime(0.5)).to.closeTo(1, 0.1);
			expect(buffer.getValueAtTime(1)).to.closeTo(1, 0.1);
			expect(buffer.getValueAtTime(1.5)).to.closeTo(1.75, 0.1);
			expect(buffer.getValueAtTime(2)).to.closeTo(3, 0.1);
		});

		it("can cancel and hold a scheduled value", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0).toDestination();
				sched.setValueAtTime(0, 0);
				sched.linearRampToValueAtTime(1, 1);
				sched.cancelAndHoldAtTime(0.5);
				transport.start(0);
			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(0.25)).to.be.closeTo(0.25, 0.1);
			expect(buffer.getValueAtTime(0.5)).to.be.closeTo(0.5, 0.1);
			expect(buffer.getValueAtTime(0.75)).to.be.closeTo(0.5, 0.1);
		});

		it("can cancel a scheduled value", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(0).toDestination();
				sched.setValueAtTime(0, 0);
				sched.linearRampToValueAtTime(1, 0.5);
				sched.linearRampToValueAtTime(0, 1);
				sched.cancelScheduledValues(0.6);
				transport.start(0);
			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(0.25)).to.be.closeTo(0.5, 0.1);
			expect(buffer.getValueAtTime(0.5)).to.be.closeTo(1, 0.1);
			expect(buffer.getValueAtTime(0.75)).to.be.closeTo(1, 0.1);
		});

		it("can automate values with different units", async () => {
			let sched;
			const buffer = await Offline(({ transport }) => {
				sched = new SyncedSignal(-10, "decibels").toDestination();
				sched.setValueAtTime(-5, 0);
				sched.linearRampToValueAtTime(-12, 0.5);
				sched.exponentialRampTo(-6, 0.1, 1);
				transport.start(0);
			}, 1.2);
			buffer.forEach((sample, time) => {
				if (time < 0.5) {
					expect(sample).to.be.within(
						dbToGain(-12.01),
						dbToGain(-4.99)
					);
				} else if (time < 1) {
					expect(sample).to.be.closeTo(dbToGain(-12), 0.1);
				} else if (time > 1.1) {
					expect(sample).to.be.closeTo(dbToGain(-6), 0.1);
				}
			});
		});

		it("can set a ramp point and then ramp from there", async () => {
			const buffer = await Offline(({ transport }) => {
				const sig = new SyncedSignal(0).toDestination();
				sig.setRampPoint(0);
				sig.linearRampToValueAtTime(1, 1);
				sig.setRampPoint(0.5);
				sig.linearRampToValueAtTime(0, 1);
				transport.start(0);
			}, 1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(0, 0.1);
			expect(buffer.getValueAtTime(0.5)).to.be.closeTo(0.5, 0.1);
			expect(buffer.getValueAtTime(1)).to.be.closeTo(0, 0.1);
		});

		it("can set a exponential approach ramp from the current time", async () => {
			const buffer = await Offline(({ transport }) => {
				const sig = new SyncedSignal(0).toDestination();
				sig.targetRampTo(1, 0.3);
				transport.start(0);
			}, 0.5);
			expect(buffer.getValueAtTime(0)).to.be.below(0.07);
			expect(buffer.getValueAtTime(0.3)).to.be.closeTo(1, 0.1);
		});
	});
});

import "../core/clock/Transport.js";

import { OutputNode } from "../core/context/ToneAudioNode.js";
import { TransportTimeClass } from "../core/type/TransportTime.js";
import {
	NormalRange,
	Seconds,
	Time,
	TransportTime,
	UnitMap,
	UnitName,
} from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { Signal, SignalOptions } from "./Signal.js";
import { ToneConstantSource } from "./ToneConstantSource.js";

/**
 * Adds the ability to synchronize the signal to the {@link TransportInstance}
 * @category Signal
 */
export class SyncedSignal<
	TypeName extends UnitName = "number",
> extends Signal<TypeName> {
	readonly name: string = "SyncedSignal";

	/**
	 * Don't override when something is connected to the input
	 */
	readonly override = false;

	readonly output: OutputNode;

	/**
	 * Keep track of the last value as an optimization.
	 */
	private _lastVal: UnitMap[TypeName];

	/**
	 * The ID returned from scheduleRepeat
	 */
	private _synced: number;

	/**
	 * Remember the callback value
	 */
	private _syncedCallback: (time: Seconds) => void;

	/**
	 * @param value Initial value of the signal
	 * @param units The unit name, e.g. "frequency"
	 */
	constructor(value?: UnitMap[TypeName], units?: TypeName);
	constructor(options?: Partial<SignalOptions<TypeName>>);
	constructor() {
		const options = optionsFromArguments(Signal.getDefaults(), arguments, [
			"value",
			"units",
		]) as SignalOptions<TypeName>;
		super(options);

		this._lastVal = options.value;
		this._synced = this.context.transport.scheduleRepeat(
			this._onTick.bind(this),
			"1i"
		);

		this._syncedCallback = this._anchorValue.bind(this);
		this.context.transport.on("start", this._syncedCallback);
		this.context.transport.on("pause", this._syncedCallback);
		this.context.transport.on("stop", this._syncedCallback);

		// disconnect the constant source from the output and replace it with another one
		this._constantSource.disconnect();
		this._constantSource.stop(0);

		// create a new one
		this._constantSource = this.output = new ToneConstantSource<TypeName>({
			context: this.context,
			offset: options.value,
			units: options.units,
		}).start(0);
		this.setValueAtTime(options.value, 0);
	}

	/**
	 * Callback which is invoked every tick.
	 */
	private _onTick(time: Seconds): void {
		const val = super.getValueAtTime(this.context.transport.seconds);
		// approximate ramp curves with linear ramps
		if (this._lastVal !== val) {
			this._lastVal = val;
			this._constantSource.offset.setValueAtTime(val, time);
		}
	}

	/**
	 * Anchor the value at the start and stop of the Transport
	 */
	private _anchorValue(time: Seconds): void {
		const val = super.getValueAtTime(this.context.transport.seconds);
		this._lastVal = val;
		this._constantSource.offset.cancelAndHoldAtTime(time);
		this._constantSource.offset.setValueAtTime(val, time);
	}

	getValueAtTime(time: TransportTime): UnitMap[TypeName] {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		return super.getValueAtTime(computedTime);
	}

	setValueAtTime(value: UnitMap[TypeName], time: TransportTime) {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		super.setValueAtTime(value, computedTime);
		return this;
	}

	linearRampToValueAtTime(value: UnitMap[TypeName], time: TransportTime) {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		super.linearRampToValueAtTime(value, computedTime);
		return this;
	}

	exponentialRampToValueAtTime(
		value: UnitMap[TypeName],
		time: TransportTime
	) {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		super.exponentialRampToValueAtTime(value, computedTime);
		return this;
	}

	setTargetAtTime(
		value,
		startTime: TransportTime,
		timeConstant: number
	): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		super.setTargetAtTime(value, computedTime, timeConstant);
		return this;
	}

	cancelScheduledValues(startTime: TransportTime): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		super.cancelScheduledValues(computedTime);
		return this;
	}

	setValueCurveAtTime(
		values: UnitMap[TypeName][],
		startTime: TransportTime,
		duration: Time,
		scaling: NormalRange
	): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		duration = this.toSeconds(duration);
		super.setValueCurveAtTime(values, computedTime, duration, scaling);
		return this;
	}

	cancelAndHoldAtTime(time: TransportTime): this {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		super.cancelAndHoldAtTime(computedTime);
		return this;
	}

	setRampPoint(time: TransportTime): this {
		const computedTime = new TransportTimeClass(
			this.context,
			time
		).toSeconds();
		super.setRampPoint(computedTime);
		return this;
	}

	exponentialRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: TransportTime
	): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		super.exponentialRampTo(value, rampTime, computedTime);
		return this;
	}

	linearRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: TransportTime
	): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		super.linearRampTo(value, rampTime, computedTime);
		return this;
	}

	targetRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: TransportTime
	): this {
		const computedTime = new TransportTimeClass(
			this.context,
			startTime
		).toSeconds();
		super.targetRampTo(value, rampTime, computedTime);
		return this;
	}

	dispose(): this {
		super.dispose();
		this.context.transport.clear(this._synced);
		this.context.transport.off("start", this._syncedCallback);
		this.context.transport.off("pause", this._syncedCallback);
		this.context.transport.off("stop", this._syncedCallback);
		this._constantSource.dispose();
		return this;
	}
}

import { expect, use } from "chai";
import sinon from "sinon";
import sinonChai from "sinon-chai";
use(sinonChai);

import { BasicTests } from "../../test/helper/Basic.js";
import { Offline, whenBetween } from "../../test/helper/Offline.js";
import { Context } from "../core/context/Context.js";
import { ToneConstantSource } from "./ToneConstantSource.js";

describe("ToneConstantSource", () => {
	BasicTests(ToneConstantSource);

	afterEach(() => {
		sinon.restore();
	});

	context("Constructor", () => {
		it("can be constructed with an offset", () => {
			const source = new ToneConstantSource(330);
			expect(source.offset.value).to.equal(330);
			source.dispose();
		});

		it("can be constructed with no arguments", () => {
			const source = new ToneConstantSource();
			expect(source.offset.value).to.equal(1);
			source.dispose();
		});

		it("can be constructed with an options object", () => {
			const source = new ToneConstantSource({
				offset: 2,
			});
			expect(source.offset.value).to.be.closeTo(2, 0.01);
			source.dispose();
		});
	});

	context("onended", () => {
		it("invokes the onended callback in the online context", async () => {
			const source = new ToneConstantSource();
			source.start();
			source.stop("+0.3");
			const now = source.now();
			await new Promise<void>((resolve) => {
				source.onended = () => resolve();
			});
			expect(source.now() - now).to.be.within(0.25, 0.6);
			source.dispose();
		});

		it("invokes the onended callback only once in the online context", async () => {
			const source = new ToneConstantSource();
			source.start();
			source.stop("+0.1");
			source.stop("+0.2");
			source.stop("+0.3");
			const now = source.now();
			await new Promise<void>((resolve) => {
				source.onended = () => resolve();
			});
			expect(source.now() - now).to.be.within(0.25, 0.6);
			source.dispose();
		});

		it("invokes the onended callback in the offline context", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const source = new ToneConstantSource();
				source.start(0);
				source.stop(0.2);
				source.onended = () => {
					expect(source.now() - 0.2).to.be.closeTo(0, 0.05);
					source.dispose();
					wasInvoked = true;
				};
			}, 0.3);
			expect(wasInvoked).to.equal(true);
		});

		it("invokes the onended callback only once in offline context", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const source = new ToneConstantSource();
				source.start(0);
				source.stop(0.1);
				source.stop(0.2);
				source.stop(0.3);
				source.onended = () => {
					expect(source.now() - 0.3).to.be.closeTo(0, 0.05);
					source.dispose();
					expect(wasInvoked).to.equal(false);
					wasInvoked = true;
				};
			}, 0.4);
			expect(wasInvoked).to.equal(true);
		});
	});

	context("Scheduling", () => {
		it("throw an error if start is called multiple time", () => {
			const source = new ToneConstantSource();
			source.start();
			expect(() => {
				source.start();
			}).to.throw();
			source.dispose();
		});

		it("can play for a specific duration", async () => {
			const buffer = await Offline(() => {
				const source = new ToneConstantSource().toDestination();
				source.start(0).stop(0.1);
			}, 0.4);
			expect(buffer.getValueAtTime(0)).to.be.above(0);
			expect(buffer.getValueAtTime(0.09)).to.be.above(0);
			expect(buffer.getValueAtTime(0.1)).to.equal(0);
		});

		it("can call stop multiple times and takes the last value", async () => {
			const buffer = await Offline(() => {
				const source = new ToneConstantSource().toDestination();
				source.start(0).stop(0.1).stop(0.2);
			}, 0.4);
			expect(buffer.getValueAtTime(0)).to.be.above(0);
			expect(buffer.getValueAtTime(0.1)).to.be.above(0);
			expect(buffer.getValueAtTime(0.19)).to.be.above(0);
			expect(buffer.getValueAtTime(0.2)).to.equal(0);
		});

		it("stops the native ConstantSourceNode once stop() takes effect", async () => {
			const stopSpy = sinon.spy(ConstantSourceNode.prototype, "stop");
			const source = new ToneConstantSource().start();
			source.stop();
			await new Promise<void>((resolve) => {
				source.onended = () => resolve();
			});
			expect(stopSpy).to.have.been.calledOnce;
			source.dispose();
		});

		it("clamps start time to the currentTime", () => {
			const source = new ToneConstantSource();
			source.start(0);
			const currentTime = source.context.currentTime;
			expect(source.getStateAtTime(0)).to.equal("stopped");
			expect(source.getStateAtTime(currentTime)).to.equal("started");
			source.dispose();
		});

		it("clamps stop time to the currentTime", (done) => {
			const source = new ToneConstantSource();
			source.start(0);
			let currentTime = source.context.currentTime;
			expect(source.getStateAtTime(0)).to.equal("stopped");
			expect(source.getStateAtTime(currentTime)).to.equal("started");
			setTimeout(() => {
				currentTime = source.now();
				source.stop(0);
				expect(source.getStateAtTime(currentTime + 0.01)).to.equal(
					"stopped"
				);
				source.dispose();
				done();
			}, 100);
		});
	});

	context("State", () => {
		it("reports the right state", () => {
			return Offline(() => {
				const source = new ToneConstantSource();
				source.start(0);
				source.stop(0.05);
				return (time) => {
					whenBetween(time, 0, 0.05, () => {
						expect(source.state).to.equal("started");
					});
					whenBetween(time, 0.05, 0.1, () => {
						expect(source.state).to.equal("stopped");
					});
				};
			}, 0.1);
		});

		it("can call stop multiple times, takes the last value", () => {
			return Offline(() => {
				const source = new ToneConstantSource();
				source.start(0);
				source.stop(0.05);
				source.stop(0.1);
				return (time) => {
					whenBetween(time, 0, 0.1, () => {
						expect(source.state).to.equal("started");
					});
					whenBetween(time, 0.1, 0.2, () => {
						expect(source.state).to.equal("stopped");
					});
				};
			}, 0.2);
		});
	});

	context("Suspended AudioContext", () => {
		it("does nothing when AudioContext returns to suspended", () => {
			const context = new Context();
			expect(context.state).to.equal("suspended");

			const source = new ToneConstantSource({
				context,
			});

			source.start(0);

			context.dispose();
			source.dispose();
		});

		it("starts when the audio context is resumed", async () => {
			const context = new Context();
			expect(context.state).to.equal("suspended");

			const source = new ToneConstantSource({
				context,
			});

			source.start(0);

			await context.resume();

			context.dispose();
			source.dispose();
		});

		it("schedules a future start when the audio context is resumed", async () => {
			const startSpy = sinon.spy(ConstantSourceNode.prototype, "start");
			const context = new Context();
			expect(context.state).to.equal("suspended");

			const source = new ToneConstantSource({
				context,
			});

			source.start(1);

			await context.resume();

			expect(startSpy).to.have.been.calledOnceWith(1);

			context.dispose();
			source.dispose();
		});

		it("does not start if stopped before scheduled start time while suspended", async () => {
			const startSpy = sinon.spy(ConstantSourceNode.prototype, "start");
			const context = new Context();
			expect(context.state).to.equal("suspended");

			const source = new ToneConstantSource({
				context,
			});

			source.start(2);
			source.stop(1);

			await context.resume();

			expect(startSpy).to.not.have.been.called;

			context.dispose();
			source.dispose();
		});

		it("context can be suspended again", async () => {
			const context = new Context();
			expect(context.state).to.equal("suspended");

			const source = new ToneConstantSource({
				context,
			});

			source.start(0);

			await context.resume();

			source.stop(0.1);

			await context.rawContext.suspend(0);

			// wait for the context to be suspended
			await new Promise<void>((resolve) =>
				context.on("statechange", () => {
					if (context.state === "suspended") {
						resolve();
					}
				})
			);

			context.dispose();
			source.dispose();
		});
	});
});

import { Param } from "../core/context/Param.js";
import { connect } from "../core/context/ToneAudioNode.js";
import { Seconds, Time, UnitMap, UnitName } from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import {
	OneShotSource,
	OneShotSourceOptions,
} from "../source/OneShotSource.js";

export interface ToneConstantSourceOptions<TypeName extends UnitName>
	extends OneShotSourceOptions {
	convert: boolean;
	offset: UnitMap[TypeName];
	units: TypeName;
	minValue?: number;
	maxValue?: number;
}

/**
 * Wrapper around the native fire-and-forget ConstantSource.
 * Adds the ability to reschedule the stop method.
 * @category Signal
 */
export class ToneConstantSource<
	TypeName extends UnitName = "number",
> extends OneShotSource<ToneConstantSourceOptions<TypeName>> {
	readonly name: string = "ToneConstantSource";

	/**
	 * The signal generator
	 */
	private _source?: ConstantSourceNode;

	/**
	 * Whether the native source was started, so it can be stopped
	 */
	private _sourceStarted = false;

	/**
	 * The offset of the signal generator
	 */
	readonly offset: Param<TypeName>;

	/**
	 * @param  offset   The offset value
	 */
	constructor(offset: UnitMap[TypeName]);
	constructor(options?: Partial<ToneConstantSourceOptions<TypeName>>);
	constructor() {
		const options = optionsFromArguments(
			ToneConstantSource.getDefaults(),
			arguments,
			["offset"]
		);
		super(options);

		this._onContextRunning(() => this._contextStarted());

		this.offset = new Param({
			context: this.context,
			convert: options.convert,
			param: !this._source
				? // placeholder param until the context is started
					this.context.createGain().gain
				: this._source.offset,
			swappable: !this._source,
			units: options.units,
			value: options.offset,
			minValue: options.minValue,
			maxValue: options.maxValue,
		});
	}

	static getDefaults(): ToneConstantSourceOptions<any> {
		return Object.assign(OneShotSource.getDefaults(), {
			convert: true,
			offset: 1,
			units: "number" as UnitName,
		});
	}

	/**
	 * Once the context is started, kick off source.
	 */
	private _contextStarted() {
		this._source = this.context.createConstantSource();
		connect(this._source, this._gainNode);
		this.offset?.setParam(this._source.offset);
		const isStarted = this._startTime !== -1;
		const isStoppedBeforeStart =
			this._stopTime !== -1 && this._stopTime < this._startTime;
		if (isStarted && !isStoppedBeforeStart) {
			this._source.start(this._startTime);
			this._sourceStarted = true;
		}
	}

	/**
	 * Start the source node at the given time
	 * @param  time When to start the source
	 */
	start(time?: Time): this {
		const computedTime = this.toSeconds(time);
		this.log("start", computedTime);
		this._startGain(computedTime);
		if (this._source) {
			this._source.start(computedTime);
			this._sourceStarted = true;
		}
		return this;
	}

	protected _stopSource(time?: Seconds): void {
		// state is already "stopped" here: OneShotSource defers this call
		// until after _stopTime, so check the native node instead
		if (this._sourceStarted) {
			this._source?.stop(time);
		}
	}

	dispose(): this {
		super.dispose();
		if (this.state === "started") {
			this.stop();
		}
		this._source?.disconnect();
		this.offset.dispose();
		return this;
	}
}

