				expect(noise.type).to.equal(type);
			});
			noise.dispose();
		});

		it("cant set invalid type", () => {
			const noise = new Noise();
			expect(() => {
				// @ts-ignore
				noise.type = "else";
			}).to.throw(Error);
			noise.dispose();
		});

		it("outputs white noise", () => {
			return OutputAudio(() => {
				const noise = new Noise("white");
				noise.toDestination();
				noise.start();
			});
		});

		it("outputs pink noise", () => {
			return OutputAudio(() => {
				const noise = new Noise("pink");
				noise.toDestination();
				noise.start();
			});
		});

		it("outputs brown noise", () => {
			return OutputAudio(() => {
				const noise = new Noise("brown");
				noise.toDestination();
				noise.start();
			});
		});

		it("can set the type after the noise is started", () => {
			return OutputAudio(() => {
				const noise = new Noise();
				noise.toDestination();
				noise.start();
				noise.type = "brown";
			});
		});
	});
});

import { ToneAudioBuffer } from "../core/context/ToneAudioBuffer.js";
import { Positive, Time } from "../core/type/Units.js";
import { assert } from "../core/util/Debug.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { Source, SourceOptions } from "../source/Source.js";
import { ToneBufferSource } from "./buffer/ToneBufferSource.js";

export type NoiseType = "white" | "brown" | "pink";

export interface NoiseOptions extends SourceOptions {
	type: NoiseType;
	playbackRate: Positive;
	fadeIn: Time;
	fadeOut: Time;
}

/**
 * Noise is a noise generator. It uses looped noise buffers to save on performance.
 * Noise supports the noise types: "pink", "white", and "brown". Read more about
 * colors of noise on [Wikipedia](https://en.wikipedia.org/wiki/Colors_of_noise).
 *
 * @example
 * // initialize the noise and start
 * const noise = new Tone.Noise("pink").start();
 * // make an autofilter to shape the noise
 * const autoFilter = new Tone.AutoFilter({
 * 	frequency: "8n",
 * 	baseFrequency: 200,
 * 	octaves: 8
 * }).toDestination().start();
 * // connect the noise
 * noise.connect(autoFilter);
 * // start the autofilter LFO
 * autoFilter.start();
 * @category Source
 */
export class Noise extends Source<NoiseOptions> {
	readonly name: string = "Noise";

	/**
	 * Private reference to the source
	 */
	private _source: ToneBufferSource | null = null;

	/**
	 * private reference to the type
	 */
	private _type!: NoiseType;

	/**
	 * The playback rate of the noise. Affects
	 * the "frequency" of the noise.
	 */
	private _playbackRate: Positive;

	/**
	 * The fadeIn time of the amplitude envelope.
	 */
	protected _fadeIn: Time;

	/**
	 * The fadeOut time of the amplitude envelope.
	 */
	protected _fadeOut: Time;

	/**
	 * @param type the noise type (white|pink|brown)
	 */
	constructor(type?: NoiseType);
	constructor(options?: Partial<NoiseOptions>);
	constructor() {
		const options = optionsFromArguments(Noise.getDefaults(), arguments, [
			"type",
		]);
		super(options);

		this._playbackRate = options.playbackRate;
		this.type = options.type;
		this._fadeIn = options.fadeIn;
		this._fadeOut = options.fadeOut;
	}

	static getDefaults(): NoiseOptions {
		return Object.assign(Source.getDefaults(), {
			fadeIn: 0,
			fadeOut: 0,
			playbackRate: 1,
			type: "white" as NoiseType,
		});
	}

	/**
	 * The type of the noise. Can be "white", "brown", or "pink".
	 * @example
	 * const noise = new Tone.Noise().toDestination().start();
	 * noise.type = "brown";
	 */
	get type(): NoiseType {
		return this._type;
	}
	set type(type: NoiseType) {
		assert(type in _noiseBuffers, "Noise: invalid type: " + type);
		if (this._type !== type) {
			this._type = type;
			// if it's playing, stop and restart it
			if (this.state === "started") {
				const now = this.now();
				this._stop(now);
				this._start(now);
			}
		}
	}

	/**
	 * The playback rate of the noise. Affects
	 * the "frequency" of the noise.
	 */
	get playbackRate(): Positive {
		return this._playbackRate;
	}
	set playbackRate(rate: Positive) {
		this._playbackRate = rate;
		if (this._source) {
			this._source.playbackRate.value = rate;
		}
	}

	/**
	 * internal start method
	 */
	protected _start(time?: Time): void {
		const buffer = _noiseBuffers[this._type];
		this._source = new ToneBufferSource({
			url: buffer,
			context: this.context,
			fadeIn: this._fadeIn,
			fadeOut: this._fadeOut,
			loop: true,
			onended: () => this.onstop(this),
			playbackRate: this._playbackRate,
		}).connect(this.output);
		this._source.start(
			this.toSeconds(time),
			Math.random() * (buffer.duration - 0.001)
		);
	}

	/**
	 * internal stop method
	 */
	protected _stop(time?: Time): void {
		if (this._source) {
			this._source.stop(this.toSeconds(time));
			this._source = null;
		}
	}

	/**
	 * The fadeIn time of the amplitude envelope.
	 */
	get fadeIn(): Time {
		return this._fadeIn;
	}
	set fadeIn(time) {
		this._fadeIn = time;
		if (this._source) {
			this._source.fadeIn = this._fadeIn;
		}
	}

	/**
	 * The fadeOut time of the amplitude envelope.
	 */
	get fadeOut(): Time {
		return this._fadeOut;
	}
	set fadeOut(time) {
		this._fadeOut = time;
		if (this._source) {
			this._source.fadeOut = this._fadeOut;
		}
	}

	protected _restart(time?: Time): void {
		// TODO could be optimized by cancelling the buffer source 'stop'
		this._stop(time);
		this._start(time);
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this._source?.disconnect();
		return this;
	}
}

//--------------------
// THE NOISE BUFFERS
//--------------------

// Noise buffer stats
const BUFFER_LENGTH = 44100 * 5;
const NUM_CHANNELS = 2;

/**
 * The cached noise buffers
 */
interface NoiseCache {
	[key: string]: ToneAudioBuffer | null;
}

/**
 * Cache the noise buffers
 */
const _noiseCache: NoiseCache = {
	brown: null,
	pink: null,
	white: null,
};

/**
 * The noise arrays. Generated on initialization.
 * borrowed heavily from https://github.com/zacharydenton/noise.js
 * (c) 2013 Zach Denton (MIT)
 */
const _noiseBuffers = {
	get brown(): ToneAudioBuffer {
		if (!_noiseCache.brown) {
			const buffer: Float32Array[] = [];
			for (let channelNum = 0; channelNum < NUM_CHANNELS; channelNum++) {
				const channel = new Float32Array(BUFFER_LENGTH);
				buffer[channelNum] = channel;
				let lastOut = 0.0;
				for (let i = 0; i < BUFFER_LENGTH; i++) {
					const white = Math.random() * 2 - 1;
					channel[i] = (lastOut + 0.02 * white) / 1.02;
					lastOut = channel[i];
					channel[i] *= 3.5; // (roughly) compensate for gain
				}
			}
			_noiseCache.brown = new ToneAudioBuffer().fromArray(buffer);
		}
		return _noiseCache.brown;
	},

	get pink(): ToneAudioBuffer {
		if (!_noiseCache.pink) {
			const buffer: Float32Array[] = [];
			for (let channelNum = 0; channelNum < NUM_CHANNELS; channelNum++) {
				const channel = new Float32Array(BUFFER_LENGTH);
				buffer[channelNum] = channel;
				let b0, b1, b2, b3, b4, b5, b6;
				b0 = b1 = b2 = b3 = b4 = b5 = b6 = 0.0;
				for (let i = 0; i < BUFFER_LENGTH; i++) {
					const white = Math.random() * 2 - 1;
					b0 = 0.99886 * b0 + white * 0.0555179;
					b1 = 0.99332 * b1 + white * 0.0750759;
					b2 = 0.969 * b2 + white * 0.153852;
					b3 = 0.8665 * b3 + white * 0.3104856;
					b4 = 0.55 * b4 + white * 0.5329522;
					b5 = -0.7616 * b5 - white * 0.016898;
					channel[i] =
						b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
					channel[i] *= 0.11; // (roughly) compensate for gain
					b6 = white * 0.115926;
				}
			}
			_noiseCache.pink = new ToneAudioBuffer().fromArray(buffer);
		}
		return _noiseCache.pink;
	},

	get white(): ToneAudioBuffer {
		if (!_noiseCache.white) {
			const buffer: Float32Array[] = [];
			for (let channelNum = 0; channelNum < NUM_CHANNELS; channelNum++) {
				const channel = new Float32Array(BUFFER_LENGTH);
				buffer[channelNum] = channel;
				for (let i = 0; i < BUFFER_LENGTH; i++) {
					channel[i] = Math.random() * 2 - 1;
				}
			}
			_noiseCache.white = new ToneAudioBuffer().fromArray(buffer);
		}
		return _noiseCache.white;
	},
};

import { Gain } from "../core/context/Gain.js";
import {
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { GainFactor, Seconds, Time } from "../core/type/Units.js";
import { assert } from "../core/util/Debug.js";
import { noOp } from "../core/util/Interface.js";
import { BasicPlaybackState } from "../core/util/StateTimeline.js";

export type OneShotSourceCurve = "linear" | "exponential";

type onEndedCallback = (source: OneShotSource<any>) => void;

export interface OneShotSourceOptions extends ToneAudioNodeOptions {
	onended: onEndedCallback;
	fadeIn: Time;
	fadeOut: Time;
	curve: OneShotSourceCurve;
}

/**
 * Base class for fire-and-forget nodes
 */
export abstract class OneShotSource<
	Options extends ToneAudioNodeOptions,
> extends ToneAudioNode<Options> {
	/**
	 * The callback to invoke after the
	 * source is done playing.
	 */
	onended: onEndedCallback = noOp;

	/**
	 * Sources do not have input nodes
	 */
	input: undefined;

	/**
	 * The start time
	 */
	protected _startTime = -1;

	/**
	 * The stop time
	 */
	protected _stopTime = -1;

	/**
	 * The id of the timeout
	 */
	private _timeout = -1;

	/**
	 * The public output node
	 */
	output: Gain = new Gain({
		context: this.context,
		gain: 0,
	});

	/**
	 * The output gain node.
	 */
	protected _gainNode = this.output;

	/**
	 * The fadeIn time of the amplitude envelope.
	 */
	protected _fadeIn: Time;

	/**
	 * The fadeOut time of the amplitude envelope.
	 */
	protected _fadeOut: Time;

	/**
	 * The curve applied to the fades, either "linear" or "exponential"
	 */
	protected _curve: OneShotSourceCurve;

	constructor(options: OneShotSourceOptions) {
		super(options);

		this._fadeIn = options.fadeIn;
		this._fadeOut = options.fadeOut;
		this._curve = options.curve;
		this.onended = options.onended;
	}

	static getDefaults(): OneShotSourceOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			curve: "linear" as OneShotSourceCurve,
			fadeIn: 0,
			fadeOut: 0,
			onended: noOp,
		});
	}

	/**
	 * Stop the source node
	 */
	protected abstract _stopSource(time: Seconds): void;

	/**
	 * Start the source node at the given time
	 * @param  time When to start the node
	 */
	protected abstract start(time?: Time): this;
	/**
	 * Start the source at the given time
	 * @param  time When to start the source
	 */
	protected _startGain(time: Seconds, gain: GainFactor = 1): this {
		assert(
			this._startTime === -1,
			"Source cannot be started more than once"
		);
		// apply a fade in envelope
		const fadeInTime = this.toSeconds(this._fadeIn);

		// record the start time
		this._startTime = time + fadeInTime;
		this._startTime = Math.max(this._startTime, this.context.currentTime);

		// schedule the envelope
		if (fadeInTime > 0) {
			this._gainNode.gain.setValueAtTime(0, time);
			if (this._curve === "linear") {
				this._gainNode.gain.linearRampToValueAtTime(
					gain,
					time + fadeInTime
				);
			} else {
				this._gainNode.gain.exponentialApproachValueAtTime(
					gain,
					time,
					fadeInTime
				);
			}
		} else {
			this._gainNode.gain.setValueAtTime(gain, time);
		}
		return this;
	}

	/**
	 * Stop the source node at the given time.
	 * @param time When to stop the source
	 */
	stop(time?: Time): this {
		this.log("stop", time);
		this._stopGain(this.toSeconds(time));
		return this;
	}

	/**
	 * Stop the source at the given time
	 * @param  time When to stop the source
	 */
	protected _stopGain(time: Seconds): this {
		assert(this._startTime !== -1, "'start' must be called before 'stop'");
		// cancel the previous stop
		this.cancelStop();

		// the fadeOut time
		const fadeOutTime = this.toSeconds(this._fadeOut);

		// schedule the stop callback
		this._stopTime = this.toSeconds(time) + fadeOutTime;
		this._stopTime = Math.max(this._stopTime, this.now());
		if (fadeOutTime > 0) {
			// start the fade out curve at the given time
			if (this._curve === "linear") {
				this._gainNode.gain.linearRampTo(0, fadeOutTime, time);
			} else {
				this._gainNode.gain.targetRampTo(0, fadeOutTime, time);
			}
		} else {
			// stop any ongoing ramps, and set the value to 0
			this._gainNode.gain.cancelAndHoldAtTime(time);
			this._gainNode.gain.setValueAtTime(0, time);
		}
		this.context.clearTimeout(this._timeout);
		this._timeout = this.context.setTimeout(() => {
			// allow additional time for the exponential curve to fully decay
			const additionalTail =
				this._curve === "exponential" ? fadeOutTime * 2 : 0;
			this._stopSource(this.now() + additionalTail);
			this._onended();
		}, this._stopTime - this.context.currentTime);
		return this;
	}

	/**
	 * Invoke the onended callback
	 */
	protected _onended(): void {
		if (this.onended === noOp) {
			return;
		}

		this.onended(this);
		// overwrite onended to make sure it only is called once
		this.onended = noOp;
		// dispose when it's ended to free up for garbage collection only in the online context
		if (!this.context.isOffline) {
			const disposeCallback = () => this.dispose();
			if (typeof requestIdleCallback !== "undefined") {
				requestIdleCallback(disposeCallback);
			} else {
				setTimeout(disposeCallback, 10);
			}
		}
	}

	/**
	 * Get the playback state at the given time
	 */
	getStateAtTime = (time: Time): BasicPlaybackState => {
		const computedTime = this.toSeconds(time);
		if (
			this._startTime !== -1 &&
			computedTime >= this._startTime &&
			(this._stopTime === -1 || computedTime <= this._stopTime)
		) {
			return "started";
		} else {
			return "stopped";
		}
	};

	/**
	 * Get the playback state at the current time
	 */
	get state(): BasicPlaybackState {
		return this.getStateAtTime(this.now());
	}

	/**
	 * Cancel a scheduled stop event
	 */
	cancelStop(): this {
		this.log("cancelStop");
		assert(this._startTime !== -1, "Source is not started");
		// cancel the stop envelope
		this._gainNode.gain.cancelScheduledValues(
			this._startTime + this.sampleTime
		);
		this.context.clearTimeout(this._timeout);
		this._stopTime = -1;
		return this;
	}

	dispose(): this {
		super.dispose();
		this._gainNode.dispose();
		this.onended = noOp;
		return this;
	}
}

import { expect } from "chai";

import { atTime, holdClock, Offline } from "../../test/helper/Offline.js";
import { ToneAudioBuffer } from "../core/context/ToneAudioBuffer.js";
import { getContext } from "../core/Global.js";
import { noOp } from "../core/util/Interface.js";
import { Player } from "./buffer/Player.js";
import { Oscillator } from "./oscillator/Oscillator.js";

describe("Source", () => {
	it("can be started and stopped", () => {
		const source = new Oscillator();
		source.start(0);
		source.stop(1);
		source.dispose();
	});

	it("can be constructed with an options object", () => {
		const source = new Oscillator({
			volume: -20,
		});
		expect(source.volume.value).to.be.closeTo(-20, 0.1);
		source.dispose();
	});

	it("can be muted in the constructor options", () => {
		const source = new Oscillator({
			mute: true,
		});
		expect(source.mute).to.be.true;
		source.dispose();
	});

	it("can set the volume", () => {
		const source = new Oscillator();
		source.volume.value = -8;
		expect(source.volume.value).to.be.closeTo(-8, 0.1);
		source.dispose();
	});

	it("can mute and unmute the source", () => {
		const source = new Oscillator();
		source.volume.value = -8;
		source.mute = true;
		expect(source.mute).to.be.true;
		expect(source.volume.value).to.equal(-Infinity);
		source.mute = false;
		// returns the volume to what it was
		expect(source.volume.value).to.be.closeTo(-8, 0.1);
		source.dispose();
	});

	it("can get and set values with an object", () => {
		const source = new Oscillator();
		source.set({ volume: -10 });
		expect(source.get().volume).to.be.closeTo(-10, 0.1);
		source.dispose();
	});

	it("is initially stopped", () => {
		const source = new Oscillator();
		expect(source.state).to.equal("stopped");
		source.dispose();
	});

	it("cannot be scheduled to stop/start twice in a row", () => {
		return Offline(() => {
			const source = new Oscillator();
			source.start(0).start(1);
			source.stop(2).stop(3);
			source.dispose();
		});
	});

	it("can be scheduled with multiple starts/stops", () => {
		return Offline(() => {
			const source = new Oscillator();
			source.start(0).stop(0.5).start(0.75).stop(1).start(1.25).stop(1.5);
			return [
				atTime(0.1, () => {
					expect(source.state).to.equal("started");
				}),
				atTime(0.5, () => {
					expect(source.state).to.equal("stopped");
				}),
				atTime(0.8, () => {
					expect(source.state).to.equal("started");
				}),
				atTime(1, () => {
					expect(source.state).to.equal("stopped");
				}),
				atTime(1.25, () => {
					expect(source.state).to.equal("started");
				}),
				atTime(1.6, () => {
					expect(source.state).to.equal("stopped");
				}),
			];
		}, 2);
	});

	it("clamps start time to the currentTime", (done) => {
		const source = new Oscillator();
		expect(source.state).to.equal("stopped");
		source.start(0);
		setTimeout(() => {
			expect(source.state).to.equal("started");
			source.dispose();
			done();
		}, 10);
	});

	it("clamps stop time to the currentTime", (done) => {
		const source = new Oscillator();
		expect(source.state).to.equal("stopped");
		source.start(0);
		setTimeout(() => {
			expect(source.state).to.equal("started");
			source.stop(0);
			setTimeout(() => {
				expect(source.state).to.equal("stopped");
				source.dispose();
				done();
			}, 10);
		}, 10);
	});

	it("correctly returns the scheduled play state", () => {
		return Offline(() => {
			const source = new Oscillator();
			expect(source.state).to.equal("stopped");
			source.start(0).stop(0.5);

			return (time) => {
				if (time >= 0 && time < 0.5) {
					expect(source.state).to.equal("started");
				} else if (time > 0.5) {
					expect(source.state).to.equal("stopped");
				}
			};
		}, 0.6);
	});

	it("start needs to be greater than the previous start time", () => {
		return Offline(() => {
			const source = new Oscillator();
			source.start(0);
			expect(() => {
				source.start(0);
			}).to.throw(Error);
			source.dispose();
		});
	});

	context("sync", () => {
		const ramp = new Float32Array(getContext().sampleRate);
		ramp.forEach((val, index) => {
			ramp[index] = index / getContext().sampleRate;
		});
		const rampBuffer = ToneAudioBuffer.fromArray(ramp);

		it("can sync its start to the transport", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0);
				expect(source.state).to.equal("stopped");
				transport.start(source.now());
				expect(source.state).to.equal("started");
				source.dispose();
				transport.stop();
			});
		});

		it("calling sync multiple times has no affect", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().sync().start(0);
				expect(source.state).to.equal("stopped");
				transport.start(source.now());
				expect(source.state).to.equal("started");
				source.dispose();
				transport.stop();
			});
		});

		it("can unsync after it was synced", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0);
				source.unsync();
				transport.start();
				expect(source.state).to.equal("stopped");
			});
		});

		it("calling unsync multiple times has no affect", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0);
				source.unsync().unsync();
				transport.start();
				expect(source.state).to.equal("stopped");
			});
		});

		it("can sync its stop to the transport", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0);
				expect(source.state).to.equal("stopped");
				transport.start(0).stop(0.4);
				expect(source.state).to.equal("started");

				return (time) => {
					if (time > 0.4) {
						expect(source.state).to.equal("stopped");
					}
				};
			}, 0.5);
		});

		it("can schedule multiple starts/stops", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0.1).stop(0.2).start(0.3);
				transport.start(0).stop(0.4);
				expect(source.state).to.equal("stopped");

				return (time) => {
					if (time > 0.1 && time < 0.19) {
						expect(source.state).to.equal("started");
					} else if (time > 0.2 && time < 0.29) {
						expect(source.state).to.equal("stopped");
					} else if (time > 0.3 && time < 0.39) {
						expect(source.state).to.equal("started");
					} else if (time > 0.4) {
						expect(source.state).to.equal("stopped");
					}
				};
			}, 0.6);
		});

		it.skip("can sync schedule multiple starts", () => {
			return Offline(({ transport }) => {
				const buff = ToneAudioBuffer.fromArray(
					new Float32Array(1024).map((v) => 1)
				);
				const source = new Player(buff);
				source.sync().start(0.1).start(0.3);
				transport.start(0);
				expect(source.state).to.equal("stopped");

				return [
					atTime(0.11, () => {
						expect(source.state).to.equal("started");
					}),
					atTime(0.31, () => {
						expect(source.state).to.equal("started");
					}),
				];
			}, 0.6);
		});

		it("has correct offset when the transport is started with an offset", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0.3).stop(0.4);
				transport.start(0, 0.1);
				expect(source.state).to.equal("stopped");

				return (time) => {
					if (time > 0.21 && time < 0.29) {
						expect(source.state).to.equal("started");
					} else if (time > 0.31) {
						expect(source.state).to.equal("stopped");
					}
				};
			}, 0.5);
		});

		it("can start with an offset after the start time of the source", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0);
				transport.start(0, 0.1);
				expect(source.state).to.equal("started");
				source.dispose();
			}, 0.1);
		});

		it("can sync its start to the transport after a delay", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0.3);
				transport.start(0).stop(0.4);
				expect(source.state).to.equal("stopped");

				return (time) => {
					if (time > 0.3 && time < 0.39) {
						expect(source.state).to.equal("started");
					} else if (time > 0.4) {
						expect(source.state).to.equal("stopped");
					}
				};
			}, 0.6);
		});

		it("correct state when the transport position is changed", () => {
			return Offline(({ transport }) => {
				const source = new Oscillator();
				source.sync().start(0.3).stop(0.4);
				transport.start(0).stop(0.4);
				expect(source.state).to.equal("stopped");
				transport.seconds = 0.305;
				expect(source.state).to.equal("started");
				transport.seconds = 0.405;
				return atTime(0.01, () => {
					expect(source.state).to.equal("stopped");
				});
			}, 0.1);
		});

		it("gives the correct offset on time on start/stop events", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2, 0.1).stop(0.3);
				transport.start(0.2);
			}, 0.7);
			expect(output.getValueAtTime(0.41)).to.be.closeTo(0.1, 0.01);
			expect(output.getValueAtTime(0.45)).to.be.closeTo(0.15, 0.001);
			expect(output.getValueAtTime(0.5)).to.be.equal(0);
		});

		it("stops the playing source when the transport is stopped and restarted at the same time", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0);
				transport.start(0);
				return atTime(
					0.2,
					holdClock(transport, (time) => {
						transport.stop(time);
						transport.start(time, 0.5);
					})
				);
			}, 0.5);
			// before the restart the ramp plays from 0
			expect(output.getValueAtTime(0.1)).to.be.closeTo(0.1, 0.01);
			// after the restart only the source started at offset 0.5 plays;
			// if the first source were orphaned the two ramps would sum
			expect(output.getValueAtTime(0.3)).to.be.closeTo(0.6, 0.01);
			expect(output.getValueAtTime(0.4)).to.be.closeTo(0.7, 0.01);
		});

		it("stops a source whose start was pending in the same clock update as a pause (#1289)", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.5);
				transport.start(0);
				// the clip's start tick at 0.5 and the pause at ~0.52 are
				// processed in the same clock update
				return atTime(
					0.52,
					holdClock(transport, (time) => {
						transport.pause(time);
					})
				);
			}, 1);
			expect(output.getValueAtTime(0.7)).to.equal(0);
			expect(output.getValueAtTime(0.9)).to.equal(0);
		});

		it("stops a source whose start was pending in the same clock update as a stop (#1289)", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.5);
				transport.start(0);
				return atTime(
					0.52,
					holdClock(transport, (time) => {
						transport.stop(time);
					})
				);
			}, 1);
			expect(output.getValueAtTime(0.7)).to.equal(0);
			expect(output.getValueAtTime(0.9)).to.equal(0);
		});

		it("stops a source whose start was pending in the same clock update as a stop scheduled ahead of time", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.5);
				transport.start(0);
				// stop scheduled in advance; the start tick at 0.5 and the
				// stop at 0.52 are both pending when the clock catches up
				transport.stop(0.52);
				return atTime(0.55, holdClock(transport, noOp));
			}, 1);
			expect(output.getValueAtTime(0.51)).to.be.closeTo(0.01, 0.005);
			expect(output.getValueAtTime(0.7)).to.equal(0);
			expect(output.getValueAtTime(0.9)).to.equal(0);
		});

		it("gives the correct offset on time on start/stop events when started with an offset", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2, 0.1).stop(0.4);
				transport.start(0.2, 0.1);
			}, 0.7);
			expect(output.getValueAtTime(0.21)).to.be.closeTo(0.0, 0.01);
			expect(output.getValueAtTime(0.31)).to.be.closeTo(0.1, 0.01);
			expect(output.getValueAtTime(0.41)).to.be.closeTo(0.2, 0.01);
			expect(output.getValueAtTime(0.45)).to.be.closeTo(0.25, 0.01);
			expect(output.getValueAtTime(0.51)).to.be.equal(0);
		});

		it("gives the correct offset on time on start/stop events invoked with a transport offset that's in the middle of the event", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2, 0.1).stop(0.4);
				transport.start(0, 0.3);
			}, 0.7);
			expect(output.getValueAtTime(0.01)).to.be.closeTo(0.2, 0.01);
			expect(output.getValueAtTime(0.05)).to.be.closeTo(0.25, 0.01);
			expect(output.getValueAtTime(0.11)).to.be.equal(0);
		});

		it("gives the correct duration when invoked with a transport offset that's in the middle of the event", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2, 0.1, 0.3);
				transport.start(0, 0.3);
			}, 0.7);
			expect(output.getValueAtTime(0.01)).to.be.closeTo(0.2, 0.01);
			expect(output.getValueAtTime(0.1)).to.be.closeTo(0.3, 0.01);
			expect(output.getValueAtTime(0.199)).to.be.closeTo(0.4, 0.01);
			expect(output.getValueAtTime(0.31)).to.be.equal(0);
		});

		it("stops at the right time when transport.stop is invoked before the scheduled stop", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2).stop(0.4);
				transport.start(0).stop(0.3);
			}, 0.7);
			expect(output.getValueAtTime(0.2)).to.be.closeTo(0.0, 0.01);
			expect(output.getValueAtTime(0.25)).to.be.closeTo(0.05, 0.01);
			expect(output.getValueAtTime(0.31)).to.be.equal(0);
		});

		it("invokes the right methods and offsets when the transport is seeked", async () => {
			const output = await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.sync().start(0.2);
				transport.start(0, 0.3);

				return atTime(0.1, () => {
					// seek forward in time
					transport.seconds = 0.1;
				});
			}, 0.7);
			expect(output.getValueAtTime(0.01)).to.be.closeTo(0.1, 0.01);
			expect(output.getValueAtTime(0.05)).to.be.closeTo(0.15, 0.01);
			expect(output.getValueAtTime(0.11)).to.be.closeTo(0.0, 0.01);
			expect(output.getValueAtTime(0.21)).to.be.closeTo(0.0, 0.01);
			expect(output.getValueAtTime(0.25)).to.be.closeTo(0.05, 0.01);
			expect(output.getValueAtTime(0.3)).to.be.closeTo(0.1, 0.01);
		});

		it("does not replay a clip synced at time 0 after stopping and restarting at a later offset (#1417)", async () => {
			let onStopCount = 0;
			await Offline(({ transport }) => {
				const source = new Player(rampBuffer).toDestination();
				source.onstop = () => {
					onStopCount++;
				};
				// rampBuffer duration is 1s. Sync at time 0 with duration 0.2s.
				// This clip only spans [0, 0.2]. At transport time 0.4, it is over.
				source.sync().start(0, 0, 0.2);
				transport.start(0, 0);

				return [
					atTime(0.25, () => {
						transport.stop();
					}),
					atTime(0.3, () => {
						// restart past the clip duration at offset 0.4
						transport.start(0.3, 0.4);
					}),
				];
			}, 0.5);

			expect(onStopCount).to.equal(1);
		});
	});
});

import "../core/context/Destination.js";
import "../core/clock/Transport.js";

import { Volume } from "../component/channel/Volume.js";
import { Param } from "../core/context/Param.js";
import {
	OutputNode,
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { Decibels, Seconds, Time } from "../core/type/Units.js";
import { assert, assertContextRunning } from "../core/util/Debug.js";
import { defaultArg } from "../core/util/Defaults.js";
import { noOp, readOnly } from "../core/util/Interface.js";
import { GT } from "../core/util/Math.js";
import {
	BasicPlaybackState,
	StateTimeline,
	StateTimelineEvent,
} from "../core/util/StateTimeline.js";
import { isDefined, isUndef } from "../core/util/TypeCheck.js";

type onStopCallback = (source: Source<any>) => void;

export interface SourceOptions extends ToneAudioNodeOptions {
	volume: Decibels;
	mute: boolean;
	onstop: onStopCallback;
}

/**
 * Base class for sources.
 * start/stop of this.context.transport.
 *
 * ```
 * // Multiple state change events can be chained together,
 * // but must be set in the correct order and with ascending times
 * // OK
 * state.start().stop("+0.2");
 * // OK
 * state.start().stop("+0.2").start("+0.4").stop("+0.7")
 * // BAD
 * state.stop("+0.2").start();
 * // BAD
 * state.start("+0.3").stop("+0.2");
 * ```
 */
export abstract class Source<
	Options extends SourceOptions,
> extends ToneAudioNode<Options> {
	/**
	 * The output volume node
	 */
	private _volume: Volume;

	/**
	 * The output node
	 */
	output: OutputNode;

	/**
	 * Sources have no inputs
	 */
	input = undefined;

	/**
	 * The volume of the output in decibels.
	 * @example
	 * const source = new Tone.PWMOscillator().toDestination();
	 * source.volume.value = -6;
	 */
	volume: Param<"decibels">;

	/**
	 * The callback to invoke when the source is stopped.
	 */
	onstop: onStopCallback;

	/**
	 * Keep track of the scheduled state.
	 */
	protected _state: StateTimeline<{
		duration?: Seconds;
		offset?: Seconds;
		/**
		 * Either the buffer is explicitly scheduled to end using the stop method,
		 * or its implicitly ended when the buffer is over.
		 */
		implicitEnd?: boolean;
	}> = new StateTimeline("stopped");

	/**
	 * The synced `start` callback function from the transport
	 */
	protected _synced = false;

	/**
	 * Keep track of all of the scheduled event ids
	 */
	private _scheduled: number[] = [];

	/**
	 * Placeholder functions for syncing/unsyncing to transport
	 */
	private _syncedStart: (time: Seconds, offset: Seconds) => void = noOp;
	private _syncedStop: (time: Seconds) => void = noOp;

	constructor(options: SourceOptions) {
		super(options);
		this._state.memory = 100;
		this._state.increasing = true;

		this._volume = this.output = new Volume({
			context: this.context,
			mute: options.mute,
			volume: options.volume,
		});
		this.volume = this._volume.volume;
		readOnly(this, "volume");
		this.onstop = options.onstop;
	}

	static getDefaults(): SourceOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			mute: false,
			onstop: noOp,
			volume: 0,
		});
	}

	/**
	 * Returns the playback state of the source, either "started" or "stopped".
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/ahntone_c3.mp3", () => {
	 * 	player.start();
	 * 	console.log(player.state);
	 * }).toDestination();
	 */
	get state(): BasicPlaybackState {
		if (this._synced) {
			if (this.context.transport.state === "started") {
				return this._state.getValueAtTime(
					this.context.transport.seconds
				) as BasicPlaybackState;
			} else {
				return "stopped";
			}
		} else {
			return this._state.getValueAtTime(this.now()) as BasicPlaybackState;
		}
	}

	/**
	 * Mute the output.
	 * @example
	 * const osc = new Tone.Oscillator().toDestination().start();
	 * // mute the output
	 * osc.mute = true;
	 */
	get mute(): boolean {
		return this._volume.mute;
	}
	set mute(mute: boolean) {
		this._volume.mute = mute;
	}

	// overwrite these functions
	protected abstract _start(time: Time, offset?: Time, duration?: Time): void;
	protected abstract _stop(time: Time): void;
	protected abstract _restart(
		time: Seconds,
		offset?: Time,
		duration?: Time
	): void;

	/**
	 * Compute the buffer offset to use when the source is started mid-playback.
	 * @param explicitOffset The buffer-time offset the caller passed to `start()`
	 * @param transportElapsed Seconds of Transport time that have elapsed since
	 *   this source was scheduled to start.
	 */
	protected _getSyncedStartOffset(
		explicitOffset: Seconds,
		transportElapsed: Seconds
	): Seconds {
		return explicitOffset + transportElapsed;
	}

	/**
	 * Ensure that the scheduled time is not before the current time.
	 * Should only be used when scheduled unsynced.
	 */
	private _clampToCurrentTime(time: Seconds): Seconds {
		if (this._synced) {
			return time;
		} else {
			return Math.max(time, this.context.currentTime);
		}
	}

	/**
	 * Start the source at the specified time. If no time is given,
	 * start the source now.
	 * @param  time When the source should be started.
	 * @example
	 * const source = new Tone.Oscillator().toDestination();
	 * source.start("+0.5"); // starts the source 0.5 seconds from now
	 */
	start(time?: Time, offset?: Time, duration?: Time): this {
		let computedTime =
			isUndef(time) && this._synced
				? this.context.transport.seconds
				: this.toSeconds(time);
		computedTime = this._clampToCurrentTime(computedTime);
		// if it's started, stop it and restart it
		if (
			!this._synced &&
			this._state.getValueAtTime(computedTime) === "started"
		) {
			// time should be strictly greater than the previous start time
			assert(
				GT(
					computedTime,
					(this._state.get(computedTime) as StateTimelineEvent).time
				),
				"Start time must be strictly greater than previous start time"
			);
			this._state.cancel(computedTime);
			this._state.setStateAtTime("started", computedTime);
			this.log("restart", computedTime);
			this.restart(computedTime, offset, duration);
		} else {
			this._state.setStateAtTime("started", computedTime);
			if (this._synced) {
				// add the offset time to the event
				const event = this._state.get(computedTime);
				if (event) {
					event.offset = this.toSeconds(defaultArg(offset, 0));
					event.duration = duration
						? this.toSeconds(duration)
						: undefined;
				}
				const sched = this.context.transport.schedule((t) => {
					this._start(t, offset, duration);
				}, computedTime);
				this._scheduled.push(sched);

				// if the transport is already started
				// and the time is greater than where the transport is
				if (
					this.context.transport.state === "started" &&
					this.context.transport.getSecondsAtTime(this.immediate()) >
						computedTime
				) {
					this._syncedStart(
						this.now(),
						this.context.transport.seconds
					);
				}
			} else {
				assertContextRunning(this.context);
				this._start(computedTime, offset, duration);
			}
		}
		return this;
	}

	/**
	 * Stop the source at the specified time. If no time is given,
	 * stop the source now.
	 * @param  time When the source should be stopped.
	 * @example
	 * const source = new Tone.Oscillator().toDestination();
	 * source.start();
	 * source.stop("+0.5"); // stops the source 0.5 seconds from now
	 */
	stop(time?: Time): this {
		let computedTime =
			isUndef(time) && this._synced
				? this.context.transport.seconds
				: this.toSeconds(time);
		computedTime = this._clampToCurrentTime(computedTime);
		if (
			this._state.getValueAtTime(computedTime) === "started" ||
			isDefined(this._state.getNextState("started", computedTime))
		) {
			this.log("stop", computedTime);
			if (!this._synced) {
				this._stop(computedTime);
			} else {
				const sched = this.context.transport.schedule(
					this._stop.bind(this),
					computedTime
				);
				this._scheduled.push(sched);
			}
			this._state.cancel(computedTime);
			this._state.setStateAtTime("stopped", computedTime);
		}
		return this;
	}

	/**
	 * Restart the source.
	 */
	restart(time?: Time, offset?: Time, duration?: Time): this {
		time = this.toSeconds(time);
		if (this._state.getValueAtTime(time) === "started") {
			this._state.cancel(time);
			this._restart(time, offset, duration);
		}
		return this;
	}

	/**
	 * Sync the source to the Transport so that all subsequent
	 * calls to `start` and `stop` are synced to the TransportTime
	 * instead of the AudioContext time.
	 *
	 * @example
	 * const osc = new Tone.Oscillator().toDestination();
	 * // sync the source so that it plays between 0 and 0.3 on the Transport's timeline
	 * osc.sync().start(0).stop(0.3);
	 * // start the transport.
	 * Tone.Transport.start();
	 * // set it to loop once a second
	 * Tone.Transport.loop = true;
	 * Tone.Transport.loopEnd = 1;
	 */
	sync(): this {
		if (!this._synced) {
			this._synced = true;
			this._syncedStart = (time, offset) => {
				if (GT(offset, 0)) {
					// get the playback state at that time
					const stateEvent = this._state.get(offset);
					// listen for start events which may occur in the middle of the sync'ed time
					if (
						stateEvent &&
						stateEvent.state === "started" &&
						stateEvent.time !== offset
					) {
						// get the offset
						const startOffset =
							offset - this.toSeconds(stateEvent.time);
						let duration: number | undefined;
						if (stateEvent.duration) {
							duration =
								this.toSeconds(stateEvent.duration) -
								startOffset;
							if (duration <= 0) {
								return;
							}
						}
						this._start(
							time,
							this._getSyncedStartOffset(
								this.toSeconds(stateEvent.offset),
								startOffset
							),
							duration
						);
					}
				}
			};
			this._syncedStop = (time) => {
				const seconds = this.context.transport.getSecondsAtTime(
					Math.max(time - this.sampleTime, 0)
				);
				if (this._state.getValueAtTime(seconds) === "started") {
					this._stop(time);
				}
			};
			this.context.transport.on("start", this._syncedStart);
			this.context.transport.on("loopStart", this._syncedStart);
			this.context.transport.on("stop", this._syncedStop);
			this.context.transport.on("pause", this._syncedStop);
			this.context.transport.on("loopEnd", this._syncedStop);
		}
		return this;
	}

	/**
	 * Unsync the source to the Transport.
	 * @see {@link sync}
	 */
	unsync(): this {
		if (this._synced) {
			this.context.transport.off("stop", this._syncedStop);
			this.context.transport.off("pause", this._syncedStop);
			this.context.transport.off("loopEnd", this._syncedStop);
			this.context.transport.off("start", this._syncedStart);
			this.context.transport.off("loopStart", this._syncedStart);
		}
		this._synced = false;
		// clear all of the scheduled ids
		this._scheduled.forEach((id) => this.context.transport.clear(id));
		this._scheduled = [];
		this._state.cancel(0);
		// stop it also
		this._stop(0);
		return this;
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this.onstop = noOp;
		this.unsync();
		this._volume.dispose();
		this._state.dispose();
		return this;
	}
}

import { expect, use } from "chai";
import sinon from "sinon";
import sinonChai from "sinon-chai";
use(sinonChai);

import { BasicTests } from "../../test/helper/Basic.js";
import { Context } from "../core/context/Context.js";
import { OfflineContext } from "../core/context/OfflineContext.js";
import { UserMedia } from "./UserMedia.js";

describe("UserMedia", () => {
	// run the common tests
	BasicTests(UserMedia);

	context("Source Tests", () => {
		it("can be constructed with the input number", () => {
			const extIn = new UserMedia();
			extIn.dispose();
		});

		it("can be constructed with an options object", () => {
			const extIn = new UserMedia({
				volume: -10,
				mute: false,
			});
			expect(extIn.volume.value).to.be.closeTo(-10, 0.1);
			expect(extIn.mute).to.be.false;
			extIn.dispose();
		});

		it("properties return undefined before open", () => {
			const extIn = new UserMedia();
			expect(extIn.deviceId).to.be.undefined;
			expect(extIn.groupId).to.be.undefined;
			expect(extIn.label).to.be.undefined;
			extIn.dispose();
		});

		it("indicates if the browser has UserMedia support", () => {
			expect(UserMedia.supported).to.be.a("boolean");
		});
	});

	context("Opening and closing", () => {
		beforeEach(() => {
			const mockTrack = { stop: sinon.stub() };
			const mockStream = {
				active: true,
				getAudioTracks: () => [mockTrack],
			} as unknown as MediaStream;
			const mockMediaStreamSource = {
				connect: sinon.stub(),
				disconnect: sinon.stub(),
				numberOfOutputs: 1,
			} as unknown as MediaStreamAudioSourceNode;
			sinon.stub(UserMedia, "enumerateDevices").resolves([
				{
					deviceId: "default",
					groupId: "default",
					label: "Default Device",
				},
				{
					deviceId: "other",
					groupId: "default",
					label: "Other Device",
				},
			] as MediaDeviceInfo[]);
			sinon
				.stub(navigator.mediaDevices, "getUserMedia")
				.resolves(mockStream);
			sinon
				.stub(Context.prototype, "createMediaStreamSource")
				.returns(mockMediaStreamSource);
		});

		afterEach(() => {
			sinon.restore();
		});

		it("open returns a promise", async () => {
			const extIn = new UserMedia();
			const promise = extIn.open();
			expect(promise).to.be.instanceOf(Promise);
			await promise;
			extIn.dispose();
		});

		it("can open an input", async () => {
			const extIn = new UserMedia();
			await extIn.open();
			extIn.dispose();
		});

		it("can open an input by name", async () => {
			const extIn = new UserMedia();
			const devices = await UserMedia.enumerateDevices();
			const name = devices[0].deviceId;

			await extIn.open(name);

			expect(extIn.deviceId).to.equal(name);
			expect(navigator.mediaDevices.getUserMedia).to.have.been.calledWith(
				sinon.match.hasNested("audio.deviceId", name)
			);
			extIn.dispose();
		});

		it("can open an input by index", async () => {
			const extIn = new UserMedia();

			await extIn.open(0);

			expect(navigator.mediaDevices.getUserMedia).to.have.been.calledWith(
				sinon.match.hasNested("audio.deviceId", "default")
			);
			extIn.dispose();
		});

		it("can pass in additional constraints", async () => {
			const extIn = new UserMedia();
			await extIn.open({
				preferCurrentTab: true,
			});
			expect(navigator.mediaDevices.getUserMedia).to.have.been.calledWith(
				sinon.match.hasNested("preferCurrentTab", true)
			);
			extIn.dispose();
		});

		it("throws an error if it cant find the device name", async () => {
			const extIn = new UserMedia();
			try {
				await extIn.open("doesn't exist");
				throw new Error("shouldn't reach here");
			} catch {
				extIn.dispose();
			}
		});

		it("is 'started' after media is open and 'stopped' otherwise", async () => {
			const extIn = new UserMedia();
			expect(extIn.state).to.equal("stopped");

			await extIn.open();

			expect(extIn.state).to.equal("started");
			extIn.dispose();
		});

		it("has a label, group and device id when open", async () => {
			const extIn = new UserMedia();
			expect(extIn.deviceId).to.be.undefined;
			expect(extIn.groupId).to.be.undefined;
			expect(extIn.label).to.be.undefined;

			await extIn.open();

			expect(extIn.deviceId).to.be.a("string");
			expect(extIn.groupId).to.be.a("string");
			expect(extIn.label).to.be.a("string");
			extIn.dispose();
		});

		it("can reopen an input", async () => {
			const extIn = new UserMedia();
			await extIn.open();
			extIn.close();
			await extIn.open();
			extIn.dispose();
		});

		it("can close an input", async () => {
			const extIn = new UserMedia();
			await extIn.open();
			extIn.close();
			extIn.dispose();
		});

		it("can enumerate devices", async () => {
			const devices = await UserMedia.enumerateDevices();
			expect(devices).to.be.instanceOf(Array);
		});

		it("doesn't work in OfflineContext", async () => {
			const context = new OfflineContext(2, 2, 44100);
			const extIn = new UserMedia({ context });
			try {
				await extIn.open();
				throw new Error("shouldn't reach here");
			} catch {
				// expected to throw in OfflineContext
			}
		});
	});
});

import { Volume } from "../component/channel/Volume.js";
import { Param } from "../core/context/Param.js";
import {
	connect,
	OutputNode,
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "../core/context/ToneAudioNode.js";
import { Decibels } from "../core/type/Units.js";
import { assert } from "../core/util/Debug.js";
import { deepMerge, optionsFromArguments } from "../core/util/Defaults.js";
import { readOnly } from "../core/util/Interface.js";
import { isDefined, isNumber, isObject } from "../core/util/TypeCheck.js";

export interface UserMediaOptions extends ToneAudioNodeOptions {
	volume: Decibels;
	mute: boolean;
}
/**
 * UserMedia uses MediaDevices.getUserMedia to open up and external microphone or audio input.
 * Check [MediaDevices API Support](https://developer.mozilla.org/en-US/docs/Web/API/MediaDevices/getUserMedia)
 * to see which browsers are supported. Access to an external input
 * is limited to secure (HTTPS) connections.
 * @example
 * const meter = new Tone.Meter();
 * const mic = new Tone.UserMedia().connect(meter);
 * mic.open().then(() => {
 * 	// promise resolves when input is available
 * 	console.log("mic open");
 * 	// print the incoming mic levels in decibels
 * 	setInterval(() => console.log(meter.getValue()), 100);
 * }).catch(e => {
 * 	// promise is rejected when the user doesn't have or allow mic access
 * 	console.log("mic not open");
 * });
 * @category Source
 */

export class UserMedia extends ToneAudioNode<UserMediaOptions> {
	readonly name: string = "UserMedia";

	readonly input: undefined;
	readonly output: OutputNode;

	/**
	 * The MediaStreamNode
	 */
	private _mediaStream?: MediaStreamAudioSourceNode;

	/**
	 * The media stream created by getUserMedia.
	 */
	private _stream?: MediaStream;

	/**
	 * The open device
	 */
	private _device?: MediaDeviceInfo;

	/**
	 * The output volume node
	 */
	private _volume: Volume;

	/**
	 * The volume of the output in decibels.
	 */
	readonly volume: Param<"decibels">;

	/**
	 * @param volume The level of the input in decibels
	 */
	constructor(volume?: Decibels);
	constructor(options?: Partial<UserMediaOptions>);
	constructor() {
		const options = optionsFromArguments(
			UserMedia.getDefaults(),
			arguments,
			["volume"]
		);
		super(options);

		this._volume = this.output = new Volume({
			context: this.context,
			volume: options.volume,
		});
		this.volume = this._volume.volume;
		readOnly(this, "volume");
		this.mute = options.mute;
	}

	static getDefaults(): UserMediaOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			mute: false,
			volume: 0,
		});
	}

	/**
	 * Open the media stream. If a string is passed in, it is assumed
	 * to be the label or id of the stream, if a number is passed in,
	 * it is the input number of the stream.
	 * @param  labelOrIdOrConstraints The label or id of the audio input media device, or a getUserMedia constraints object.
	 *                   			  With no argument, the default stream is opened.
	 * @return The promise is resolved when the stream is open.
	 */
	async open(
		labelOrIdOrConstraints?: string | number | MediaStreamConstraints
	): Promise<this> {
		assert(UserMedia.supported, "UserMedia is not supported");
		// close the previous stream
		if (this.state === "started") {
			this.close();
		}
		let constraints: MediaStreamConstraints = {
			audio: {
				echoCancellation: false,
				sampleRate: this.context.sampleRate,
				noiseSuppression: false,
			},
		};
		if (isObject(labelOrIdOrConstraints)) {
			// if the user passed in a constraints object
			constraints = deepMerge(constraints, labelOrIdOrConstraints);
		} else {
			// if the user passed in a label or id
			const devices = await UserMedia.enumerateDevices();
			if (isNumber(labelOrIdOrConstraints)) {
				this._device = devices[labelOrIdOrConstraints];
			} else {
				this._device = devices.find((device) => {
					return (
						device.label === labelOrIdOrConstraints ||
						device.deviceId === labelOrIdOrConstraints
					);
				});
				// didn't find a matching device
				if (!this._device && devices.length > 0) {
					this._device = devices[0];
				}
				assert(
					isDefined(this._device),
					`No matching device ${labelOrIdOrConstraints}`
				);
			}
			// if there is a device, set the deviceId
			if (this._device) {
				// @ts-ignore
				constraints.audio.deviceId = this._device.deviceId;
			}
		}
		const stream = await navigator.mediaDevices.getUserMedia(constraints);
		// start a new source only if the previous one is closed
		if (!this._stream) {
			this._stream = stream;
			// Wrap a MediaStreamSourceNode around the live input stream.
			const mediaStreamNode =
				this.context.createMediaStreamSource(stream);
			// Connect the MediaStreamSourceNode to a gate gain node
			connect(mediaStreamNode, this.output);
			this._mediaStream = mediaStreamNode;
		}
		return this;
	}

	/**
	 * Close the media stream
	 */
	close(): this {
		if (this._stream && this._mediaStream) {
			this._stream.getAudioTracks().forEach((track) => {
				track.stop();
			});
			this._stream = undefined;
			// remove the old media stream
			this._mediaStream.disconnect();
			this._mediaStream = undefined;
		}
		this._device = undefined;
		return this;
	}

	/**
	 * Returns a promise which resolves with the list of audio input devices available.
	 * @return The promise that is resolved with the devices
	 * @example
	 * Tone.UserMedia.enumerateDevices().then((devices) => {
	 * 	// print the device labels
	 * 	console.log(devices.map(device => device.label));
	 * });
	 */
	static async enumerateDevices(): Promise<MediaDeviceInfo[]> {
		const allDevices = await navigator.mediaDevices.enumerateDevices();
		return allDevices.filter((device) => {
			return device.kind === "audioinput";
		});
	}

	/**
	 * Returns the playback state of the source, "started" when the microphone is open
	 * and "stopped" when the mic is closed.
	 */
	get state() {
		return this._stream?.active ? "started" : "stopped";
	}

	/**
	 * Returns an identifier for the represented device that is
	 * persisted across sessions. It is un-guessable by other applications and
	 * unique to the origin of the calling application. It is reset when the
	 * user clears cookies (for Private Browsing, a different identifier is
	 * used that is not persisted across sessions). Returns undefined when the
	 * device is not open.
	 */
	get deviceId(): string | undefined {
		return this._device?.deviceId;
	}

	/**
	 * Returns a group identifier. Two devices have the
	 * same group identifier if they belong to the same physical device.
	 * Returns null  when the device is not open.
	 */
	get groupId(): string | undefined {
		return this._device?.groupId;
	}

	/**
	 * Returns a label describing this device (for example "Built-in Microphone").
	 * Returns undefined when the device is not open or label is not available
	 * because of permissions.
	 */
	get label(): string | undefined {
		return this._device?.label;
	}

	/**
	 * Mute the output.
	 * @example
	 * const mic = new Tone.UserMedia();
	 * mic.open().then(() => {
	 * 	// promise resolves when input is available
	 * });
	 * // mute the output
	 * mic.mute = true;
	 */
	get mute(): boolean {
		return this._volume.mute;
	}
	set mute(mute) {
		this._volume.mute = mute;
	}

	dispose(): this {
		super.dispose();
		this.close();
		this._volume.dispose();
		this.volume.dispose();
		return this;
	}

	/**
	 * If getUserMedia is supported by the browser.
	 */
	static get supported(): boolean {
		return (
			isDefined(navigator.mediaDevices) &&
			isDefined(navigator.mediaDevices.getUserMedia)
		);
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { CompareToFile } from "../../../test/helper/CompareToFile.js";
import { Offline, whenBetween } from "../../../test/helper/Offline.js";
import { SourceTests } from "../../../test/helper/SourceTests.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { GrainPlayer } from "./GrainPlayer.js";

describe("GrainPlayer", () => {
	const buffer = new ToneAudioBuffer();

	beforeEach(() => {
		return buffer.load("./test/audio/sine.wav");
	});

	// run the common tests
	BasicTests(GrainPlayer, buffer);
	SourceTests(GrainPlayer, buffer);

	it("matches a file", () => {
		return CompareToFile(
			() => {
				const player = new GrainPlayer(buffer).toDestination();
				player.start(0.1).stop(0.2);
				(player.detune = -100), (player.playbackRate = 2);
			},
			"grainPlayer.wav",
			0.16
		);
	});

	it("matches another file", () => {
		return CompareToFile(
			() => {
				const player = new GrainPlayer(buffer).toDestination();
				player.start(0.1, 0.2);
				player.loop = true;
				player.overlap = 0.005;
				player.grainSize = 0.05;
				(player.detune = 1200), (player.playbackRate = 0.5);
			},
			"grainPlayer2.wav",
			0.2
		);
	});

	context("Constructor", () => {
		it("can be constructed with a Tone.Buffer", (done) => {
			const player = new GrainPlayer(buffer);
			expect(player.buffer.get()).to.equal(buffer.get());
			player.dispose();
			done();
		});

		it("can be constructed with an AudioBuffer", (done) => {
			const player = new GrainPlayer(buffer.get());
			expect(player.buffer.get()).to.equal(buffer.get());
			player.dispose();
			done();
		});

		it("makes a sound", async () => {
			const output = await Offline(() => {
				const player = new GrainPlayer(buffer).toDestination();
				player.start();
			});
			expect(output.isSilent()).to.be.false;
		});
	});

	context("Loading", () => {
		it("loads a url which was passed in", (done) => {
			const player = new GrainPlayer("./test/audio/sine.wav", () => {
				expect(player.loaded).to.be.true;
				player.dispose();
				done();
			});
		});

		it("can be created with an options object", (done) => {
			const player = new GrainPlayer({
				url: "./test/audio/sine.wav",
				loop: true,
				onload: function () {
					expect(player.loop).to.be.true;
					player.dispose();
					done();
				},
			});
		});

		it("invokes onerror if no url", (done) => {
			const source = new GrainPlayer({
				url: "./nosuchfile.wav",
				onerror() {
					source.dispose();
					done();
				},
			});
		});
	});

	context("Looping", () => {
		beforeEach(() => {
			buffer.load("./test/audio/short_sine.wav");
		});

		it("can be set to loop", () => {
			const player = new GrainPlayer();
			player.loop = true;
			expect(player.loop).to.be.true;
			player.dispose();
		});
	});

	context("start/stop", () => {
		beforeEach(() => {
			buffer.load("./test/audio/short_sine.wav");
		});

		it("can be play for a specific duration", async () => {
			const output = await Offline(() => {
				const player = new GrainPlayer(buffer);
				player.toDestination();
				player.start(0).stop(0.1);
				return function (time) {
					whenBetween(time, 0.1, Infinity, () => {
						expect(player.state).to.equal("stopped");
					});
					whenBetween(time, 0, 0.1, () => {
						expect(player.state).to.equal("started");
					});
				};
			}, 0.3);
			expect(output.getTimeOfLastSound()).to.be.closeTo(0.1, 0.02);
		});

		it("can be play for a specific duration passed in the 'start' method", async () => {
			const output = await Offline(() => {
				const player = new GrainPlayer(buffer);
				player.toDestination();
				player.start(0, 0, 0.1);
				return function (time) {
					whenBetween(time, 0.1, Infinity, () => {
						expect(player.state).to.equal("stopped");
					});
					whenBetween(time, 0, 0.1, () => {
						expect(player.state).to.equal("started");
					});
				};
			}, 0.3);
			expect(output.getTimeOfLastSound()).to.be.closeTo(0.1, 0.02);
		});

		it("invokes the onstop method on restart", async () => {
			let wasInvoked = 0;
			await Offline(() => {
				const player = new GrainPlayer(buffer);
				player.start(0).restart(0.1).stop(0.2);
				player.onstop = () => {
					wasInvoked++;
				};
			}, 0.3);
			expect(wasInvoked).to.equal(2);
		});

		it("can play to the end of the file", async () => {
			const bufferDuration = buffer.duration;
			const output = await Offline(() => {
				const player = new GrainPlayer(buffer).toDestination();
				player.grainSize = 0.1;
				player.start(0);
			}, bufferDuration * 1.2);
			expect(output.getTimeOfLastSound()).to.be.closeTo(
				bufferDuration,
				0.1
			);
		});

		it("plays for the right time when playbackRate = 2", async () => {
			const bufferDuration = buffer.duration;
			const output = await Offline(() => {
				const player = new GrainPlayer(buffer).toDestination();
				player.playbackRate = 2;
				player.start(0);
			}, bufferDuration);
			expect(output.getTimeOfLastSound()).to.be.closeTo(
				bufferDuration * 0.5,
				0.1
			);
		});
	});

	context("Get/Set", () => {
		it("can be set with an options object", () => {
			const player = new GrainPlayer();
			expect(player.loop).to.be.false;
			player.set({
				loop: true,
				loopStart: 0.4,
			});
			expect(player.loop).to.be.true;
			expect(player.loopStart).to.equal(0.4);
			player.dispose();
		});

		it("can get an options object", () => {
			const player = new GrainPlayer({
				url: "./test/audio/sine.wav",
				loopStart: 0.2,
				loopEnd: 0.3,
				loop: true,
				reverse: true,
			});
			expect(player.get().loopStart).to.equal(0.2);
			expect(player.get().loopEnd).to.equal(0.3);
			expect(player.get().loop).to.be.true;
			expect(player.get().reverse).to.be.true;
			player.dispose();
		});

		it("can get/set the playbackRate", () => {
			const player = new GrainPlayer();
			player.playbackRate = 0.5;
			expect(player.playbackRate).to.equal(0.5);
			player.dispose();
		});
	});
});

import { Clock } from "../../core/clock/Clock.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { intervalToFrequencyRatio } from "../../core/type/Conversions.js";
import { Cents, Positive, Seconds, Time } from "../../core/type/Units.js";
import { assertRange } from "../../core/util/Debug.js";
import { defaultArg, optionsFromArguments } from "../../core/util/Defaults.js";
import { noOp } from "../../core/util/Interface.js";
import { Source, SourceOptions } from "../Source.js";
import { ToneBufferSource } from "./ToneBufferSource.js";

interface GrainPlayerOptions extends SourceOptions {
	onload: () => void;
	onerror: (error: Error) => void;
	reverse: boolean;
	url?: ToneAudioBuffer | string | AudioBuffer;
	overlap: Seconds;
	grainSize: Seconds;
	playbackRate: Positive;
	detune: Cents;
	loop: boolean;
	loopStart: Time;
	loopEnd: Time;
}

/**
 * GrainPlayer implements [granular synthesis](https://en.wikipedia.org/wiki/Granular_synthesis).
 * Granular Synthesis enables you to adjust pitch and playback rate independently. The grainSize is the
 * amount of time each small chunk of audio is played for and the overlap is the
 * amount of crossfading transition time between successive grains.
 * @category Source
 */
export class GrainPlayer extends Source<GrainPlayerOptions> {
	readonly name: string = "GrainPlayer";

	/**
	 * The audio buffer belonging to the player.
	 */
	buffer: ToneAudioBuffer;

	/**
	 * Create a repeating tick to schedule the grains.
	 */
	private _clock: Clock;

	/**
	 * Internal loopStart value
	 */
	private _loopStart = 0;

	/**
	 * Internal loopStart value
	 */
	private _loopEnd = 0;

	/**
	 * All of the currently playing BufferSources
	 */
	private _activeSources: ToneBufferSource[] = [];

	/**
	 * Internal reference to the playback rate
	 */
	private _playbackRate: Positive;

	/**
	 * Internal grain size reference;
	 */
	private _grainSize: Seconds;

	/**
	 * Internal overlap reference;
	 */
	private _overlap: Seconds;

	/**
	 * Adjust the pitch independently of the playbackRate.
	 */
	detune: Cents;

	/**
	 * If the buffer should loop back to the loopStart when completed
	 */
	loop: boolean;

	/**
	 * @param url Either the AudioBuffer or the url from which to load the AudioBuffer
	 * @param onload The function to invoke when the buffer is loaded.
	 */
	constructor(
		url?: string | AudioBuffer | ToneAudioBuffer,
		onload?: () => void
	);
	constructor(options?: Partial<GrainPlayerOptions>);
	constructor() {
		const options = optionsFromArguments(
			GrainPlayer.getDefaults(),
			arguments,
			["url", "onload"]
		);
		super(options);

		this.buffer = new ToneAudioBuffer({
			onload: options.onload,
			onerror: options.onerror,
			reverse: options.reverse,
			url: options.url,
		});
		this._clock = new Clock({
			context: this.context,
			callback: this._tick.bind(this),
			frequency: 1 / options.grainSize,
		});
		this._playbackRate = options.playbackRate;
		this._grainSize = options.grainSize;
		this._overlap = options.overlap;
		this.detune = options.detune;

		// setup
		this.overlap = options.overlap;
		this.loop = options.loop;
		this.playbackRate = options.playbackRate;
		this.grainSize = options.grainSize;
		this.loopStart = options.loopStart;
		this.loopEnd = options.loopEnd;
		this.reverse = options.reverse;
		this._clock.on("stop", this._onstop.bind(this));
	}

	static getDefaults(): GrainPlayerOptions {
		return Object.assign(Source.getDefaults(), {
			onload: noOp,
			onerror: noOp,
			overlap: 0.1,
			grainSize: 0.2,
			playbackRate: 1,
			detune: 0,
			loop: false,
			loopStart: 0,
			loopEnd: 0,
			reverse: false,
		});
	}

	/**
	 * Internal start method
	 */
	protected _start(time?: Time, offset?: Time, duration?: Time): void {
		offset = defaultArg(offset, 0);
		offset = this.toSeconds(offset);
		time = this.toSeconds(time);

		const grainSize = 1 / this._clock.frequency.getValueAtTime(time);
		this._clock.start(time, offset / grainSize);

		if (duration) {
			this.stop(time + this.toSeconds(duration));
		}
	}

	/**
	 * Stop and then restart the player from the beginning (or offset)
	 * @param  time When the player should start.
	 * @param  offset The offset from the beginning of the sample to start at.
	 * @param  duration How long the sample should play. If no duration is given,
	 * 					it will default to the full length of the sample (minus any offset)
	 */
	restart(time?: Seconds, offset?: Time, duration?: Time): this {
		super.restart(time, offset, duration);
		return this;
	}

	protected _restart(time?: Seconds, offset?: Time, duration?: Time): void {
		this._stop(time);
		this._start(time, offset, duration);
	}

	/**
	 * Internal stop method
	 */
	protected _stop(time?: Time): void {
		this._clock.stop(time);
	}

	/**
	 * Invoked when the clock is stopped
	 */
	private _onstop(time: Seconds): void {
		// stop the players
		this._activeSources.forEach((source) => {
			source.fadeOut = 0;
			source.stop(time);
		});
		this.onstop(this);
	}

	/**
	 * Invoked on each clock tick. scheduled a new grain at this time.
	 */
	private _tick(time: Seconds): void {
		// check if it should stop looping
		const ticks = this._clock.getTicksAtTime(time);
		const offset = ticks * this._grainSize;
		this.log("offset", offset);

		if (!this.loop && offset > this.buffer.duration) {
			this.stop(time);
			return;
		}

		// at the beginning of the file, the fade in should be 0
		const fadeIn = offset < this._overlap ? 0 : this._overlap;

		// create a buffer source
		const source = new ToneBufferSource({
			context: this.context,
			url: this.buffer,
			fadeIn: fadeIn,
			fadeOut: this._overlap,
			loop: this.loop,
			loopStart: this._loopStart,
			loopEnd: this._loopEnd,
			// compute the playbackRate based on the detune
			playbackRate: intervalToFrequencyRatio(this.detune / 100),
		}).connect(this.output);

		source.start(time, this._grainSize * ticks);
		source.stop(time + this._grainSize / this.playbackRate);

		// add it to the active sources
		this._activeSources.push(source);
		// remove it when it's done
		source.onended = () => {
			const index = this._activeSources.indexOf(source);
			if (index !== -1) {
				this._activeSources.splice(index, 1);
			}
		};
	}

	/**
	 * The playback rate of the sample
	 */
	get playbackRate(): Positive {
		return this._playbackRate;
	}
	set playbackRate(rate) {
		assertRange(rate, 0.001);
		this._playbackRate = rate;
		this.grainSize = this._grainSize;
	}

	/**
	 * The loop start time.
	 */
	get loopStart(): Time {
		return this._loopStart;
	}
	set loopStart(time) {
		if (this.buffer.loaded) {
			assertRange(this.toSeconds(time), 0, this.buffer.duration);
		}
		this._loopStart = this.toSeconds(time);
	}

	/**
	 * The loop end time.
	 */
	get loopEnd(): Time {
		return this._loopEnd;
	}
	set loopEnd(time) {
		if (this.buffer.loaded) {
			assertRange(this.toSeconds(time), 0, this.buffer.duration);
		}
		this._loopEnd = this.toSeconds(time);
	}

	/**
	 * The direction the buffer should play in
	 */
	get reverse() {
		return this.buffer.reverse;
	}

	set reverse(rev) {
		this.buffer.reverse = rev;
	}

	/**
	 * The size of each chunk of audio that the
	 * buffer is chopped into and played back at.
	 */
	get grainSize(): Time {
		return this._grainSize;
	}
	set grainSize(size) {
		this._grainSize = this.toSeconds(size);
		this._clock.frequency.setValueAtTime(
			this._playbackRate / this._grainSize,
			this.now()
		);
	}

	/**
	 * The duration of the cross-fade between successive grains.
	 */
	get overlap(): Time {
		return this._overlap;
	}
	set overlap(time) {
		const computedTime = this.toSeconds(time);
		assertRange(computedTime, 0);
		this._overlap = computedTime;
	}

	/**
	 * If all the buffer is loaded
	 */
	get loaded(): boolean {
		return this.buffer.loaded;
	}

	dispose(): this {
		super.dispose();
		this.buffer.dispose();
		this._clock.dispose();
		this._activeSources.forEach((source) => source.dispose());
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { CompareToFile } from "../../../test/helper/CompareToFile.js";
import { atTime, Offline, whenBetween } from "../../../test/helper/Offline.js";
import { SourceTests } from "../../../test/helper/SourceTests.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { getContext } from "../../core/Global.js";
import { Player } from "./Player.js";

describe("Player", () => {
	const buffer = new ToneAudioBuffer();

	beforeEach(() => {
		return buffer.load("./test/audio/sine.wav");
	});

	// run the common tests
	BasicTests(Player, buffer);
	SourceTests(Player, buffer);

	it("matches a file", () => {
		return CompareToFile(
			() => {
				const player = new Player(buffer).toDestination();
				player.start(0.1).stop(0.2);
				player.playbackRate = 2;
			},
			"player.wav",
			0.005
		);
	});

	context("Constructor", () => {
		it("can be constructed with a Tone.Buffer", () => {
			const player = new Player(buffer);
			expect(player.buffer.get()).to.equal(buffer.get());
			player.dispose();
		});

		it("can be constructed with an AudioBuffer", () => {
			const player = new Player(buffer.get());
			expect(player.buffer.get()).to.equal(buffer.get());
			player.dispose();
		});

		it("can be constructed with an unloaded Tone.Buffer", (done) => {
			const playerBuffer = new ToneAudioBuffer("./test/audio/sine.wav");
			const player = new Player(playerBuffer, () => {
				expect(player.buffer.get()).to.equal(playerBuffer.get());
				player.dispose();
				done();
			});
		});

		it("can be constructed with no arguments", () => {
			const player = new Player();
			// set the buffer
			player.buffer = buffer;
			expect(player.buffer.get()).to.equal(buffer.get());
			player.dispose();
		});
	});

	context("onstop", () => {
		it("invokes the onstop method when the player is explicitly stopped", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const player = new Player({
					onstop: () => {
						wasInvoked = true;
					},
					url: buffer,
				});
				player.start(0).stop(0.1);
			}, 0.2);
			expect(wasInvoked).to.equal(true);
		});

		it("invokes the onstop method when the file is naturally over", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const player = new Player(buffer);
				player.start(0);
				player.onstop = () => {
					wasInvoked = true;
					expect(player.state).to.equal("stopped");
				};
			}, buffer.duration * 1.1);
			expect(wasInvoked).to.equal(true);
		});

		it("invokes the onstop method on restart", async () => {
			let wasInvoked = 0;
			await Offline(() => {
				const player = new Player(buffer);
				player.start(0).restart(0.1).stop(0.2);
				player.onstop = () => {
					wasInvoked++;
				};
			}, 0.3);
			expect(wasInvoked).to.equal(2);
		});
	});

	context("Loading", () => {
		it("loads a url which was passed in", (done) => {
			const player = new Player("./test/audio/sine.wav", () => {
				expect(player.loaded).to.be.true;
				player.dispose();
				done();
			});
		});

		it("loads a url using the load method", async () => {
			const player = new Player();
			await player.load("./test/audio/sine.wav");
			expect(player.buffer).to.be.instanceof(ToneAudioBuffer);
		});

		it("can be created with an options object", () => {
			const player = new Player({
				loop: true,
				url: "./test/audio/sine.wav",
			});
			player.dispose();
		});

		it("invokes onerror if no url", (done) => {
			const source = new Player({
				url: "./nosuchfile.wav",
				onerror(e) {
					expect(e).to.be.instanceOf(Error);
					source.dispose();
					done();
				},
			});
		});

		it("can autostart after loading", (done) => {
			const player = new Player({
				autostart: true,
				onload(): void {
					setTimeout(() => {
						expect(player.state).to.be.equal("started");
						done();
					}, 10);
				},
				url: "./test/audio/sine.wav",
			});
		});
	});

	context("Reverse", () => {
		it("can get/set reverse", () => {
			const player = new Player();
			player.reverse = true;
			expect(player.reverse).to.equal(true);
			player.dispose();
		});

		it("can be played in reverse", async () => {
			const shorterBuffer = buffer.slice(0, buffer.duration / 2);
			const audioBuffer = (
				shorterBuffer.get() as AudioBuffer
			).getChannelData(0);
			const lastSample = audioBuffer[audioBuffer.length - 1];
			expect(lastSample).to.not.equal(0);
			const buff = await Offline(() => {
				const player = new Player({
					reverse: true,
					url: shorterBuffer.get(),
				}).toDestination();
				player.start(0);
			});
			const firstSample = buff.toArray()[0][0];
			expect(firstSample).to.equal(lastSample);
		});
	});

	context("Looping", () => {
		beforeEach(() => {
			return buffer.load("./test/audio/short_sine.wav");
		});

		it("can be set to loop", () => {
			const player = new Player();
			player.loop = true;
			expect(player.loop).to.be.true;
			player.dispose();
		});

		it("can set the loop points", () => {
			const player = new Player();
			player.loopStart = 0.4;
			expect(player.loopStart).to.equal(0.4);
			player.loopEnd = 0.5;
			expect(player.loopEnd).to.equal(0.5);
			player.setLoopPoints(0, 0.2);
			expect(player.loopStart).to.equal(0);
			expect(player.loopEnd).to.equal(0.2);
			player.dispose();
		});

		it("loops the audio", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.loop = true;
				player.toDestination();
				player.start(0);
			}, buffer.duration * 1.5);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 1.2)).to.be.above(0);
		});

		it("setting the loop multiple times has no affect", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.loop = true;
				player.loop = true;
				player.toDestination();
				player.start(0);
			}, buffer.duration * 1.5);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 1.2)).to.be.above(0);
		});

		it("loops the audio when loop is set after start", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player.start(0);
				player.loop = true;
			}, buffer.duration * 1.5);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 1.2)).to.be.above(0);
		});

		it("offset is the loopStart when set to loop", async () => {
			const testSample =
				buffer.toArray(0)[Math.floor(0.1 * getContext().sampleRate)];
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.loopStart = 0.1;
				player.loop = true;
				player.toDestination();
				player.start(0);
			}, 0.05);
			expect(buff.toArray()[0][0]).to.equal(testSample);
		});

		it("loops the audio for the specific duration", async () => {
			const playDur = buffer.duration * 1.5;
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.loop = true;
				player.toDestination();
				player.start(0, 0, playDur);
			}, buffer.duration * 2);
			for (let time = 0; time < buffer.duration * 2; time += 0.1) {
				const val = buff.getRmsAtTime(time);
				if (time < playDur - 0.01) {
					expect(val).to.be.greaterThan(0);
				} else if (time > playDur) {
					expect(val).to.equal(0);
				}
			}
		});

		it("correctly compensates if the offset is greater than the loopEnd", async () => {
			const buff = await Offline(() => {
				// make a ramp between 0-1
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = (i / ramp.length) * 0.3;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loopStart = 0.1;
				player.loopEnd = 0.2;
				player.loop = true;
				player.start(0, 0.35);
			}, 0.05);
			buff.forEach((sample, time) => {
				if (time < 0.04) {
					expect(sample).to.be.within(0.15, 0.2);
				} else if (time > 0.05 && time < 0.09) {
					expect(sample).to.be.within(0.1, 0.15);
				}
			});
		});
	});

	context("PlaybackRate", () => {
		it("reports itself as completed after the stop time when playbackRate = 1", () => {
			return Offline(() => {
				const player = new Player(buffer);
				player.start(0);
				return atTime(buffer.duration + 0.1, () => {
					expect(player.state).to.equal("stopped");
				});
			}, buffer.duration * 1.1);
		});

		it("no longer reports itself as stopped when playback rate is changed to < 1", () => {
			return Offline(() => {
				const player = new Player(buffer);
				player.start(0);
				player.playbackRate = 0.5;
				return atTime(buffer.duration + 0.1, () => {
					expect(player.state).to.equal("started");
				});
			}, buffer.duration * 1.1);
		});

		it("when end is explicitly scheduled, it does not matter if playbackRate is changed", () => {
			return Offline(() => {
				const player = new Player(buffer);
				player.start(0).stop(0.1);
				player.playbackRate = 0.5;
				return atTime(0.11, () => {
					expect(player.state).to.equal("stopped");
				});
			}, buffer.duration);
		});
	});

	context("Get/Set", () => {
		it("can be set with an options object", () => {
			const player = new Player();
			expect(player.loop).to.be.false;
			player.set({
				fadeIn: 0.1,
				fadeOut: 0.2,
				loop: true,
				loopStart: 0.4,
			});
			expect(player.loop).to.be.true;
			expect(player.loopStart).to.equal(0.4);
			expect(player.fadeIn).to.equal(0.1);
			expect(player.fadeOut).to.equal(0.2);
			player.dispose();
		});

		it("can set attributes after player is started", () => {
			const player = new Player(buffer);
			expect(player.loop).to.be.false;
			player.start();
			player.set({
				loop: true,
				loopEnd: 0.3,
				loopStart: 0.2,
				playbackRate: 0.9,
			});
			expect(player.loop).to.be.true;
			expect(player.loopStart).to.equal(0.2);
			expect(player.loopEnd).to.equal(0.3);
			expect(player.playbackRate).to.equal(0.9);
			player.dispose();
		});

		it("can get an options object", () => {
			const player = new Player({
				loop: true,
				loopEnd: 0.3,
				loopStart: 0.2,
				reverse: true,
				url: "./test/audio/sine.wav",
			});
			expect(player.get().loopStart).to.equal(0.2);
			expect(player.get().loopEnd).to.equal(0.3);
			expect(player.get().loop).to.be.true;
			expect(player.get().reverse).to.be.true;
			player.dispose();
		});

		it("can get/set the playbackRate", () => {
			const player = new Player();
			player.playbackRate = 0.5;
			expect(player.playbackRate).to.equal(0.5);
			player.dispose();
		});
	});

	context("Start Scheduling", () => {
		it("can be start with an offset", async () => {
			const testSample =
				buffer.toArray(0)[Math.floor(0.1 * getContext().sampleRate)];
			const buff = await Offline(() => {
				const player = new Player(buffer.get());
				player.toDestination();
				player.start(0, 0.1);
			});
			expect(buff.toArray()[0][0]).to.equal(testSample);
		});

		it("is stopped and restarted when start is called twice", async () => {
			const buff = await Offline(() => {
				// make a ramp between 0-1
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / (ramp.length - 1);
				}
				const playerBuff = new ToneAudioBuffer().fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.start(0);
				player.start(0.1);
			}, 0.31);
			expect(buff.max()).to.be.lessThan(1);
		});

		it("only seeks if player is started", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer).toDestination();
				player.seek(0.2, 0.01);
			}, 0.05);
			expect(buff.isSilent()).to.be.true;
		});

		it("seeking updates stopped state", async () => {
			await Offline(() => {
				const player = new Player(buffer).toDestination();
				player.start(0);
				player.seek(buffer.duration * 0.75, 0.5);

				return (time) => {
					whenBetween(time, 0, 0.5, () => {
						expect(player.state).to.equal("started");
					});
					whenBetween(time, 0.5, 0.5 + buffer.duration * 0.25, () => {
						expect(player.state).to.equal("started");
					});
					whenBetween(
						time,
						0.5 + buffer.duration * 0.25,
						Infinity,
						() => {
							expect(player.state).to.equal("stopped");
						}
					);
				};
			}, buffer.duration);
		});

		it("can seek to a position at the given time", async () => {
			const buff = await Offline(() => {
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = (i / ramp.length) * 0.3;
				}
				const playerBuff = new ToneAudioBuffer().fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.start(0);
				player.seek(0.2, 0.1);
			}, 0.3);
			buff.forEach((sample, time) => {
				if (time < 0.09) {
					expect(sample).to.be.within(0, 0.1);
				} else if (time > 0.1 && time < 0.19) {
					expect(sample).to.be.within(0.2, 0.3);
				}
			});
		});

		it("can be play for a specific duration", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player.start(0).stop(0.1);
				return (time_2) => {
					whenBetween(time_2, 0.1, Infinity, () => {
						expect(player.state).to.equal("stopped");
					});
					whenBetween(time_2, 0, 0.1, () => {
						expect(player.state).to.equal("started");
					});
				};
			}, 0.3);
			buff.forEachBetween(
				(sample) => {
					expect(sample).to.equal(0);
				},
				0.11,
				0.15
			);
		});

		it("stops playing if invoked with 'stop' at a sooner time", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player.start(0).stop(0.1).stop(0.05);
			}, 0.3);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.05, 0.02);
		});

		it("stops playing if at the last scheduled 'stop' time", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player
					.start(0, 0, 0.05)
					.start(0.1, 0, 0.05)
					.start(0.2, 0, 0.05);
				player.stop(0.1);
			}, 0.3);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.1, 0.02);
		});

		it("can retrigger multiple sources which all stop at the stop time", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player.loop = true;
				player.start(0).start(0.1).start(0.2).stop(0.25);
			}, 0.4);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.25, 0.02);
		});

		it("can be play for a specific duration passed in the 'start' method", async () => {
			const buff = await Offline(() => {
				const player = new Player(buffer);
				player.toDestination();
				player.start(0, 0, 0.1);
				return (time) => {
					whenBetween(time, 0.1, Infinity, () => {
						expect(player.state).to.equal("stopped");
					});
					whenBetween(time, 0, 0.1, () => {
						expect(player.state).to.equal("started");
					});
				};
			}, 0.3);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.1, 0.02);
		});

		it("reports itself as stopped after a single iterations of the buffer", () => {
			return Offline(() => {
				const player = new Player(buffer).toDestination();
				player.start();

				return (time) => {
					whenBetween(time, buffer.duration, Infinity, () => {
						expect(player.state).to.equal("stopped");
					});
					whenBetween(time, 0, buffer.duration, () => {
						expect(player.state).to.equal("started");
					});
				};
			}, buffer.duration * 1.1);
		});

		it("plays synced to the Transport", async () => {
			const buff = await Offline(({ transport }) => {
				const player = new Player(buffer)
					.sync()
					.start(0)
					.toDestination();
				transport.start(0);
			}, 0.05);
			expect(buff.isSilent()).to.be.false;
		});

		it("does not play twice when the offset is very small", () => {
			// addresses #999 and #944
			return CompareToFile(
				() => {
					const player = new Player(buffer).toDestination();
					player.sync().start(0);
					getContext().transport.bpm.value = 125;
					getContext().transport.setLoopPoints(0, "1:0:0");
					getContext().transport.loop = true;
					getContext().transport.start(0);
				},
				"playerSyncLoop.wav",
				0.01
			);
		});

		it("offsets correctly when started by the Transport", async () => {
			const testSample =
				buffer.toArray(0)[
					Math.floor(0.13125 * getContext().sampleRate)
				];
			const buff = await Offline(({ transport }) => {
				const player = new Player(buffer)
					.sync()
					.start(0, 0.1)
					.toDestination();
				transport.start(0, 0.03125);
			}, 0.05);
			expect(buff.toArray()[0][0]).to.equal(testSample);
		});

		it("starts at the correct position when Transport is offset and playbackRate is not 1", async () => {
			const buff = await Offline(({ transport }) => {
				// make a ramp between 0-1
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.playbackRate = 0.5;
				player.sync().start(0);
				// start halfway through
				transport.start(0, 0.15);
			}, 0.05);
			// With playbackRate=0.5, transport position 0.15 maps to buffer position
			// 0.15 * 0.5 = 0.075. The ramp value there is 0.075 / 0.3 = 0.25.
			expect(buff.getValueAtTime(0)).to.be.closeTo(0.25, 0.03);
		});

		it("seeks to the correct buffer position when Transport starts at a non-zero offset with playbackRate != 1", async () => {
			const buff = await Offline(({ transport }) => {
				// Ramp 0 -> 1 over 0.4 s
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.4)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				// Buffer plays at 2x speed: 1 transport-second advances 2 buffer-seconds
				player.playbackRate = 2;
				player.sync().start(0);
				// Seek transport to 0.1 s. The player should start at buffer position
				// 0.1 * 2 = 0.2, giving a ramp value of 0.2 / 0.4 = 0.5.
				transport.start(0, 0.1);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(0.5, 0.03);
		});

		it("explicit buffer-time offset is not scaled by playbackRate when synced", async () => {
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				player.playbackRate = 2;
				player.sync().start(0, 0.1);
				transport.start(0);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(1 / 3, 0.03);
		});

		it("combines explicit buffer-time offset with transport-elapsed time scaled by playbackRate", async () => {
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				player.playbackRate = 2;
				player.sync().start(0, 0.1);
				transport.start(0, 0.05);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(2 / 3, 0.03);
		});

		it("looping player wraps correctly when transport offset exceeds buffer duration (playbackRate=1)", async () => {
			// buffer duration = 1s, transport seeks to 2.5s
			// buffer offset = 2.5 * 1 = 2.5 → wrapped = 2.5 % 1 = 0.5
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(getContext().sampleRate); // 1 s
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				player.sync().start(0);
				transport.start(0, 2.5);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(0.5, 0.03);
		});

		it("looping player wraps correctly when transport offset exceeds buffer duration (playbackRate=2)", async () => {
			// buffer duration = 1s, transport seeks to 1.25s, playbackRate=2
			// buffer offset = 1.25 * 2 = 2.5 → wrapped = 2.5 % 1 = 0.5
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(getContext().sampleRate); // 1 s
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				player.playbackRate = 2;
				player.sync().start(0);
				transport.start(0, 1.25);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(0.5, 0.03);
		});

		it("looping player with loopStart/loopEnd wraps correctly when transport offset exceeds loop duration (playbackRate=2)", async () => {
			// buffer duration = 1s, loopStart=0.2, loopEnd=1.0, loopDuration=0.8
			// transport seeks to 1.15s, playbackRate=2
			// buffer offset = 1.15 * 2 = 2.3
			// wrapped = ((2.3 - 0.2) % 0.8) + 0.2 = (2.1 % 0.8) + 0.2 = 0.5 + 0.2 = 0.7
			// ramp value at 0.7 in a 1s ramp = 0.7
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(getContext().sampleRate); // 1 s
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = i / ramp.length;
				}
				const playerBuff = ToneAudioBuffer.fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				player.loopStart = 0.2;
				player.loopEnd = 1.0;
				player.playbackRate = 2;
				player.sync().start(0);
				transport.start(0, 1.15);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.be.closeTo(0.7, 0.03);
		});

		it("starts with an offset when synced and started after Transport is running", async () => {
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = (i / ramp.length) * 0.3;
				}
				const playerBuff = new ToneAudioBuffer().fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				transport.start(0);
				return atTime(0.1, () => {
					player.sync().start(0);
				});
			}, 0.3);
			expect(buff.getValueAtTime(0)).to.equal(0);
			expect(buff.getValueAtTime(0.05)).to.equal(0);
			expect(buff.getValueAtTime(0.11)).to.be.closeTo(0.11, 0.01);
			expect(buff.getValueAtTime(0.2)).to.be.closeTo(0.2, 0.01);
		});

		it("can pass in an offset when synced and started after Transport is running", async () => {
			const buff = await Offline(({ transport }) => {
				const ramp = new Float32Array(
					Math.floor(getContext().sampleRate * 0.3)
				);
				for (let i = 0; i < ramp.length; i++) {
					ramp[i] = (i / ramp.length) * 0.3;
				}
				const playerBuff = new ToneAudioBuffer().fromArray(ramp);
				const player = new Player(playerBuff).toDestination();
				player.loop = true;
				transport.start(0);
				return atTime(0.1, () => {
					player.sync().start(0, 0.1);
				});
			}, 0.3);
			expect(buff.getValueAtTime(0)).to.equal(0);
			expect(buff.getValueAtTime(0.05)).to.equal(0);
			expect(buff.getValueAtTime(0.11)).to.be.closeTo(0.21, 0.01);
			expect(buff.getValueAtTime(0.15)).to.be.closeTo(0.25, 0.01);
			expect(buff.getValueAtTime(0.2)).to.be.closeTo(0.0, 0.01);
			expect(buff.getValueAtTime(0.25)).to.be.closeTo(0.05, 0.01);
		});

		it("fades in and out correctly", async () => {
			let duration = 0.5;
			const buff = await Offline(() => {
				const onesArray = new Float32Array(
					getContext().sampleRate * duration
				);
				onesArray.forEach((sample, index) => {
					onesArray[index] = 1;
				});
				const onesBuffer = ToneAudioBuffer.fromArray(onesArray);
				const player = new Player({
					url: onesBuffer,
					fadeOut: 0.1,
					fadeIn: 0.1,
				}).toDestination();
				player.start(0);
			}, 0.6);
			expect(buff.getRmsAtTime(0)).to.be.closeTo(0, 0.1);
			expect(buff.getRmsAtTime(0.05)).to.be.closeTo(0.5, 0.1);
			expect(buff.getRmsAtTime(0.1)).to.be.closeTo(1, 0.1);
			duration -= 0.1;
			expect(buff.getRmsAtTime(duration)).to.be.closeTo(1, 0.1);
			expect(buff.getRmsAtTime(duration + 0.05)).to.be.closeTo(0.5, 0.1);
			expect(buff.getRmsAtTime(duration + 0.1)).to.be.closeTo(0, 0.1);
		});

		it("stops only last activeSource when restarting at intervals < latencyHint", (done) => {
			const originalLookAhead = getContext().lookAhead;
			getContext().lookAhead = 0.3;
			const player = new Player({
				onload(): void {
					player.start(undefined, undefined, 1);
					setTimeout(
						() => player.restart(undefined, undefined, 1),
						50
					);
					setTimeout(
						() => player.restart(undefined, undefined, 1),
						100
					);
					setTimeout(
						() => player.restart(undefined, undefined, 1),
						150
					);
					setTimeout(() => {
						player.restart(undefined, undefined, 1);
						const checkStopTimes = new Set();
						// @ts-ignore
						player._activeSources.forEach((source) => {
							// @ts-ignore
							checkStopTimes.add(source._stopTime);
						});
						getContext().lookAhead = originalLookAhead;
						// ensure each source has a different stopTime
						expect(checkStopTimes.size).to.equal(
							// @ts-ignore
							player._activeSources.size
						);
						done();
					}, 250);
				},
				url: "./test/audio/sine.wav",
			});
		});
	});

	context("progress", () => {
		it("can get the progress of the player", async () => {
			await Offline(() => {
				const player = new Player(buffer);
				player.start(0);
				return (time) => {
					whenBetween(time, 0, buffer.duration, () => {
						expect(player.progress).to.be.closeTo(time, 0.01);
					});
					whenBetween(time, buffer.duration, Infinity, () => {
						expect(player.progress).to.equal(0);
					});
				};
			}, buffer.duration * 1.1);
		});

		it("progress goes back to 0 when the player loops", async () => {
			await Offline(() => {
				const player = new Player(buffer);
				player.loop = true;
				player.start(0);
				return (time) => {
					whenBetween(time, 0, buffer.duration, () => {
						expect(player.progress).to.be.closeTo(time, 0.01);
					});
					whenBetween(
						time,
						buffer.duration,
						buffer.duration * 2,
						() => {
							expect(player.progress).to.be.closeTo(
								time - buffer.duration,
								0.01
							);
						}
					);
				};
			}, buffer.duration * 2);
		});

		it("loops between loopStart and loopEnd", async () => {
			await Offline(() => {
				const player = new Player(buffer);
				player.loop = true;
				player.loopStart = 0.1;
				player.loopEnd = 0.9;
				player.start(0);
				return (time) => {
					whenBetween(time, 0, 0.8, () => {
						expect(player.progress).to.be.closeTo(time + 0.1, 0.01);
					});
					whenBetween(time, 0.8, 1.6, () => {
						expect(player.progress).to.be.closeTo(time - 0.7, 0.01);
					});
					whenBetween(time, 1.6, 2.4, () => {
						expect(player.progress).to.be.closeTo(time - 1.5, 0.01);
					});
				};
			}, 2.4);
		});

		it("progress updates at the rate of the playbackRate", async () => {
			await Offline(() => {
				const player = new Player(buffer);
				player.playbackRate = 2;
				player.start(0);
				return (time) => {
					whenBetween(time, 0, buffer.duration / 2, () => {
						expect(player.progress).to.be.closeTo(time * 2, 0.01);
					});
					whenBetween(time, buffer.duration / 2, Infinity, () => {
						expect(player.progress).to.be.equal(0);
					});
				};
			}, buffer.duration);
		});

		it("playbackRate can be changed after start", async () => {
			let playbackRateChanged = false;
			await Offline(() => {
				const player = new Player(buffer);
				player.start(0);
				return (time) => {
					whenBetween(time, 0, buffer.duration * 0.5, () => {
						expect(player.progress).to.be.closeTo(time, 0.01);
					});
					if (!playbackRateChanged && time > buffer.duration * 0.5) {
						playbackRateChanged = true;
						player.playbackRate = 2;
					}
					// after the playbackRate is changed, the progress should move half as fast
					whenBetween(
						time,
						buffer.duration * 0.5,
						buffer.duration * 0.75,
						() => {
							const timeAfterHalf = time - buffer.duration * 0.5;
							expect(player.progress).to.be.closeTo(
								buffer.duration * 0.5 + timeAfterHalf * 2,
