		});
	});
});

import { TickParam } from "../../core/clock/TickParam.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { Positive, Seconds, Time } from "../../core/type/Units.js";
import { assertRange } from "../../core/util/Debug.js";
import { timeRange } from "../../core/util/Decorator.js";
import { defaultArg, optionsFromArguments } from "../../core/util/Defaults.js";
import { noOp } from "../../core/util/Interface.js";
import { Timeline } from "../../core/util/Timeline.js";
import { isUndef } from "../../core/util/TypeCheck.js";
import { ToneConstantSource } from "../../signal/ToneConstantSource.js";
import { OneShotSource } from "../OneShotSource.js";
import { Source, SourceOptions } from "../Source.js";
import { ToneBufferSource } from "./ToneBufferSource.js";

export interface PlayerOptions extends SourceOptions {
	onload: () => void;
	onerror: (error: Error) => void;
	playbackRate: Positive;
	loop: boolean;
	autostart: boolean;
	loopStart: Time;
	loopEnd: Time;
	reverse: boolean;
	fadeIn: Time;
	fadeOut: Time;
	url?: ToneAudioBuffer | string | AudioBuffer;
}

/**
 * Player is an audio file player with start, loop, and stop functions.
 * @example
 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/gong_1.mp3").toDestination();
 * // play as soon as the buffer is loaded
 * player.autostart = true;
 * @category Source
 */
export class Player extends Source<PlayerOptions> {
	readonly name: string = "Player";

	/**
	 * If the file should play as soon
	 * as the buffer is loaded.
	 */
	autostart: boolean;

	/**
	 * The buffer
	 */
	private _buffer: ToneAudioBuffer;

	/**
	 * if the buffer should loop once its over
	 */
	private _loop: boolean;

	/**
	 * if 'loop' is true, the loop will start at this position
	 */
	private _loopStart: Time;

	/**
	 * if 'loop' is true, the loop will end at this position
	 */
	private _loopEnd: Time;

	/**
	 * the playback rate
	 */
	private _playbackRate: Positive;

	/**
	 * All of the active buffer source nodes
	 */
	private _activeSources: Set<ToneBufferSource> = new Set();

	/**
	 * Used as the source of the TickParam, but not started or used for anything else.
	 */
	private _constantSource = new ToneConstantSource({
		context: this.context,
		units: "hertz",
		offset: 0,
	});

	/**
	 * Used to track the progress of the player.
	 */
	private _progressTracker = new TickParam({
		context: this.context,
		units: "hertz",
		value: 0,
		param: this._constantSource.offset,
	});

	/**
	 * Combined with the _progressTracker param to track the progress of the player in seconds.
	 */
	private _progressOffset = new Timeline<{
		time: Seconds;
		seek: Seconds;
	}>(Infinity);

	/**
	 * The fadeIn time of the amplitude envelope.
	 */
	@timeRange(0)
	fadeIn: Time;

	/**
	 * The fadeOut time of the amplitude envelope.
	 */
	@timeRange(0)
	fadeOut: Time;

	/**
	 * @param url Either the AudioBuffer or the url from which to load the AudioBuffer
	 * @param onload The function to invoke when the buffer is loaded.
	 */
	constructor(
		url?: string | AudioBuffer | ToneAudioBuffer,
		onload?: () => void
	);
	constructor(options?: Partial<PlayerOptions>);
	constructor() {
		const options = optionsFromArguments(Player.getDefaults(), arguments, [
			"url",
			"onload",
		]);
		super(options);

		this._buffer = new ToneAudioBuffer({
			onload: this._onload.bind(this, options.onload),
			onerror: options.onerror,
			reverse: options.reverse,
			url: options.url,
		});
		this.autostart = options.autostart;
		this._loop = options.loop;
		this._loopStart = options.loopStart;
		this._loopEnd = options.loopEnd;
		this._playbackRate = options.playbackRate;
		this.fadeIn = options.fadeIn;
		this.fadeOut = options.fadeOut;
	}

	static getDefaults(): PlayerOptions {
		return Object.assign(Source.getDefaults(), {
			autostart: false,
			fadeIn: 0,
			fadeOut: 0,
			loop: false,
			loopEnd: 0,
			loopStart: 0,
			onload: noOp,
			onerror: noOp,
			playbackRate: 1,
			reverse: false,
		});
	}

	/**
	 * Load the audio file as an audio buffer.
	 * Decodes the audio asynchronously and invokes
	 * the callback once the audio buffer loads.
	 * Note: this does not need to be called if a url
	 * was passed in to the constructor. Only use this
	 * if you want to manually load a new url.
	 * @param url The url of the buffer to load. Filetype support depends on the browser.
	 */
	async load(url: string): Promise<this> {
		await this._buffer.load(url);
		this._onload();
		return this;
	}

	/**
	 * Internal method to get the progress at a specific time.
	 * @param time The time to evaluate the progress at.
	 */
	private _getProgressAtTime(time: Seconds): Seconds {
		const state = this._state.getValueAtTime(time);
		if (state === "stopped") {
			return 0;
		}
		const startTime = this._state.getLastState("started", time)!;

		// sum all of the offsets between the start time and the time
		let seeksSinceStart = 0;
		this._progressOffset.forEachBetween(startTime.time, time, (event) => {
			seeksSinceStart += event.seek;
		});
		const progress =
			this._progressTracker.getTicksAtTime(time) + seeksSinceStart;
		if (this._loop) {
			const loopEnd =
				this.loopEnd === 0
					? this.buffer.duration
					: this.toSeconds(this.loopEnd);
			const loopStart = this.toSeconds(this.loopStart);
			const duration = loopEnd - loopStart;
			return (progress % duration) + loopStart;
		}

		return progress;
	}

	/**
	 * Displays the elapsed seconds since the player was started, taking into account playbackRate changes.
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/gong_1.mp3", () => {
	 * 	player.start();
	 * 	setInterval(() => {
	 * 		console.log(player.progress);
	 * 	}, 100);
	 * }).toDestination();
	 */
	get progress(): Seconds {
		const now = this.now();
		return this._getProgressAtTime(now);
	}

	/**
	 * Internal callback when the buffer is loaded.
	 */
	private _onload(callback: () => void = noOp): void {
		callback();
		if (this.autostart) {
			this.start();
		}
	}

	/**
	 * Internal callback when the buffer is done playing.
	 */
	private _onSourceEnd(source: OneShotSource<any>): void {
		// invoke the onstop function
		this.onstop(this);

		// delete the source from the active sources
		this._activeSources.delete(source as ToneBufferSource);
		if (
			this._activeSources.size === 0 &&
			!this._synced &&
			this._state.getValueAtTime(this.now()) === "started"
		) {
			// remove the 'implicitEnd' event and replace with an explicit end
			this._state.cancel(this.now());
			this._state.setStateAtTime("stopped", this.now());
		}
	}

	/**
	 * Play the buffer at the given startTime. Optionally add an offset
	 * and/or duration which will play the buffer from a position
	 * within the buffer for the given duration.
	 *
	 * @param  time When the player should start.
	 * @param  offset The offset from the beginning of the sample to start at.
	 * @param  duration How long the sample should play. If no duration is given, it will default to the full length of the sample (minus any offset)
	 */
	start(time?: Time, offset?: Time, duration?: Time): this {
		super.start(time, offset, duration);
		return this;
	}

	/**
	 * Factor in the playback rate to compute the buffer offset when the player
	 * is synced to the Transport.
	 */
	protected _getSyncedStartOffset(
		explicitOffset: number,
		transportElapsed: number
	): number {
		return explicitOffset + transportElapsed * this._playbackRate;
	}

	/**
	 * Internal start method
	 */
	protected _start(startTime?: Time, offset?: Time, duration?: Time): void {
		// if it's a loop the default offset is the loopStart point
		if (this._loop) {
			offset = defaultArg(offset, this._loopStart);
		} else {
			// otherwise the default offset is 0
			offset = defaultArg(offset, 0);
		}

		// compute the values in seconds
		const computedOffset = this.toSeconds(offset);

		// compute the duration which is either the passed in duration of the buffer.duration - offset
		const origDuration = duration;
		duration = defaultArg(
			duration,
			Math.max(this._buffer.duration - computedOffset, 0)
		);
		let computedDuration = this.toSeconds(duration);

		// scale it by the playback rate
		computedDuration = computedDuration / this._playbackRate;

		// get the start time
		startTime = this.toSeconds(startTime);

		// make the source
		const source = new ToneBufferSource({
			url: this._buffer,
			context: this.context,
			fadeIn: this.fadeIn,
			fadeOut: this.fadeOut,
			loop: this._loop,
			loopEnd: this._loopEnd,
			loopStart: this._loopStart,
			onended: this._onSourceEnd.bind(this),
			playbackRate: this._playbackRate,
		}).connect(this.output);

		// schedule the "stopped" state
		if (!this._loop && !this._synced) {
			// cancel the previous stop
			this._state.cancel(startTime + computedDuration);
			// if it's not looping, set the state change at the end of the sample
			this._state.setStateAtTime(
				"stopped",
				startTime + computedDuration,
				{
					implicitEnd: true,
				}
			);
		}

		// add it to the array of active sources
		this._activeSources.add(source);

		// used to track the progress of the player
		const seekDelta = computedOffset - this._getProgressAtTime(startTime);
		this._progressOffset.add({
			time: startTime,
			seek: seekDelta,
		});
		this._progressTracker.setValueAtTime(this._playbackRate, startTime);

		// start it
		if (this._loop && isUndef(origDuration)) {
			source.start(startTime, computedOffset);
		} else {
			// subtract the fade out time
			source.start(
				startTime,
				computedOffset,
				computedDuration - this.toSeconds(this.fadeOut)
			);
		}
	}

	/**
	 * Stop playback.
	 */
	protected _stop(time?: Time): void {
		const computedTime = this.toSeconds(time);
		this._activeSources.forEach((source) => source.stop(computedTime));
		this._progressTracker.setValueAtTime(0, computedTime);
	}

	/**
	 * Stop and then restart the player from the beginning (or offset)
	 * @param  time When the player should start.
	 * @param  offset The offset from the beginning of the sample to start at.
	 * @param  duration How long the sample should play. If no duration is given,
	 * 					it will default to the full length of the sample (minus any offset)
	 */
	restart(time?: Seconds, offset?: Time, duration?: Time): this {
		super.restart(time, offset, duration);
		return this;
	}

	protected _restart(time?: Seconds, offset?: Time, duration?: Time): void {
		[...this._activeSources].pop()?.stop(time); // explicitly stop only the most recently created source, to avoid edge case when > 1 source exists and _stop() erroneously sets all stop times past original end offset
		this._start(time, offset, duration);
	}

	/**
	 * Seek to a specific time in the player's buffer. If the
	 * source is no longer playing at that time, it will stop.
	 * @param offset The time to seek to.
	 * @param when The time for the seek event to occur.
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/gurgling_theremin_1.mp3", () => {
	 * 	player.start();
	 * 	// seek to the offset in 1 second from now
	 * 	player.seek(0.4, "+1");
	 * }).toDestination();
	 */
	seek(offset: Time, when?: Time): this {
		const computedTime = this.toSeconds(when);
		if (this._state.getValueAtTime(computedTime) === "started") {
			const computedOffset = this.toSeconds(offset);
			// if it's currently playing, stop it
			this._stop(computedTime);
			// remove the stop event
			this._state.cancel(computedTime);
			// restart it at the given time
			this._start(computedTime, computedOffset);
		}
		return this;
	}

	/**
	 * Set the loop start and end. Will only loop if loop is set to true.
	 * @param loopStart The loop start time
	 * @param loopEnd The loop end time
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/malevoices_aa2_F3.mp3").toDestination();
	 * // loop between the given points
	 * player.setLoopPoints(0.2, 0.3);
	 * player.loop = true;
	 * player.autostart = true;
	 */
	setLoopPoints(loopStart: Time, loopEnd: Time): this {
		this.loopStart = loopStart;
		this.loopEnd = loopEnd;
		return this;
	}

	/**
	 * If loop is true, the loop will start at this position.
	 */
	get loopStart(): Time {
		return this._loopStart;
	}
	set loopStart(loopStart) {
		this._loopStart = loopStart;
		if (this.buffer.loaded) {
			assertRange(this.toSeconds(loopStart), 0, this.buffer.duration);
		}
		// get the current source
		this._activeSources.forEach((source) => {
			source.loopStart = loopStart;
		});
	}

	/**
	 * If loop is true, the loop will end at this position.
	 */
	get loopEnd(): Time {
		return this._loopEnd;
	}
	set loopEnd(loopEnd) {
		this._loopEnd = loopEnd;
		if (this.buffer.loaded) {
			assertRange(this.toSeconds(loopEnd), 0, this.buffer.duration);
		}
		// get the current source
		this._activeSources.forEach((source) => {
			source.loopEnd = loopEnd;
		});
	}

	/**
	 * The audio buffer belonging to the player.
	 */
	get buffer(): ToneAudioBuffer {
		return this._buffer;
	}
	set buffer(buffer) {
		this._buffer.set(buffer);
	}

	/**
	 * If the buffer should loop once its over.
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/drum-samples/breakbeat.mp3").toDestination();
	 * player.loop = true;
	 * player.autostart = true;
	 */
	get loop(): boolean {
		return this._loop;
	}
	set loop(loop) {
		// if no change, do nothing
		if (this._loop === loop) {
			return;
		}
		this._loop = loop;
		// set the loop of all of the sources
		this._activeSources.forEach((source) => {
			source.loop = loop;
		});
		if (loop) {
			// remove the next stopEvent
			const stopEvent = this._state.getNextState("stopped", this.now());
			if (stopEvent) {
				this._state.cancel(stopEvent.time);
			}
		}
	}

	/**
	 * Normal speed is 1. The pitch will change with the playback rate.
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/femalevoices_aa2_A5.mp3").toDestination();
	 * // play at 1/4 speed
	 * player.playbackRate = 0.25;
	 * // play as soon as the buffer is loaded
	 * player.autostart = true;
	 */
	get playbackRate(): Positive {
		return this._playbackRate;
	}
	set playbackRate(rate) {
		this._playbackRate = rate;
		const now = this.now();
		this._progressTracker.setValueAtTime(rate, now);

		// cancel the stop event since it's at a different time now
		const stopEvent = this._state.getNextState("stopped", now);
		if (stopEvent?.implicitEnd) {
			this._state.cancel(stopEvent.time);
			this._activeSources.forEach((source) => source.cancelStop());

			const progress = this._getProgressAtTime(now);
			const remainingTime = this._buffer.duration - progress;
			const newStopTime = now + remainingTime / rate;
			// reschedule the implicit stop event
			this._state.setStateAtTime("stopped", newStopTime, {
				implicitEnd: true,
			});
		}

		// set all the sources
		this._activeSources.forEach((source) => {
			source.playbackRate.setValueAtTime(rate, now);
		});
	}

	/**
	 * If the buffer should be reversed. Note that this sets the underlying {@link ToneAudioBuffer.reverse}, so
	 * if multiple players are pointing at the same ToneAudioBuffer, they will all be reversed.
	 * @example
	 * const player = new Tone.Player("https://tonejs.github.io/audio/berklee/chime_1.mp3").toDestination();
	 * player.autostart = true;
	 * player.reverse = true;
	 */
	get reverse(): boolean {
		return this._buffer.reverse;
	}
	set reverse(rev) {
		this._buffer.reverse = rev;
	}

	/**
	 * If the buffer is loaded
	 */
	get loaded(): boolean {
		return this._buffer.loaded;
	}

	dispose(): this {
		super.dispose();
		// disconnect all of the players
		this._activeSources.forEach((source) => source.dispose());
		this._activeSources.clear();
		this._buffer.dispose();
		this._constantSource.dispose();
		this._progressTracker.dispose();
		this._progressOffset.dispose();
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { Offline } from "../../../test/helper/Offline.js";
import { OutputAudio } from "../../../test/helper/OutputAudio.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { getContext } from "../../core/Global.js";
import { Player } from "./Player.js";
import { Players } from "./Players.js";

describe("Players", () => {
	const buffer = new ToneAudioBuffer();

	beforeEach(() => {
		return buffer.load("./test/audio/sine.wav");
	});

	BasicTests(Players, { test: buffer });

	context("Constructor", () => {
		it("can be constructed with an object containing a ToneAudioBuffer", () => {
			const players = new Players({
				test: buffer,
			});
			expect(players.player("test").buffer.get()).to.equal(buffer.get());
			players.dispose();
		});

		it("can be constructed with an AudioBuffer", () => {
			const players = new Players({
				test: buffer.get() as AudioBuffer,
			});
			expect(players.player("test").buffer.get()).to.equal(buffer.get());
			players.dispose();
		});

		it("can be constructed with a url", (done) => {
			const players = new Players(
				{
					test0: "./test/audio/sine.wav",
					test1: "./test/audio/sine.wav",
				},
				() => {
					expect(players.player("test0")).to.be.instanceOf(Player);
					expect(players.player("test0").buffer.loaded).to.be.true;
					expect(players.player("test1")).to.be.instanceOf(Player);
					expect(players.player("test1").buffer.loaded).to.be.true;
					expect(players.loaded).to.be.true;
					players.dispose();
					done();
				}
			);
		});

		it("can pass in additional args in the second parameters", (done) => {
			const players = new Players(
				{
					test: "./test/audio/sine.wav",
				},
				{
					onload: () => {
						expect(players.player("test").buffer.loaded).to.be.true;
						expect(players.volume.value).to.be.closeTo(-12, 0.1);
						players.dispose();
						done();
					},
					volume: -12,
				}
			);
		});

		it("invokes onerror if no url", (done) => {
			const source = new Players({
				urls: {
					test: "./nosuchfile.wav",
				},
				onerror() {
					source.dispose();
					done();
				},
			});
		});

		it("can get and set fadeIn/Out", () => {
			const players = new Players(
				{
					test: "./test/audio/sine.wav",
				},
				{
					fadeIn: 0.1,
					fadeOut: 0.2,
				}
			);
			expect(players.fadeIn).to.equal(0.1);
			expect(players.fadeOut).to.equal(0.2);
			expect(players.player("test").fadeIn).to.equal(0.1);
			players.fadeIn = 0.2;
			players.fadeOut = 0.3;
			expect(players.fadeIn).to.equal(0.2);
			expect(players.fadeOut).to.equal(0.3);
			expect(players.player("test").fadeOut).to.equal(0.3);
			players.dispose();
		});
	});

	context("get/has/add buffers", () => {
		it("says it 'has' a sample", () => {
			const players = new Players({
				test: buffer,
			});
			expect(players.has("test")).to.be.true;
			expect(players.has("nope")).to.be.false;
			players.dispose();
		});

		it("can get a sample", () => {
			const players = new Players({
				test: buffer,
			});
			expect(players.player("test")).to.be.instanceOf(Player);
			players.dispose();
		});

		it("throws an error if it tries to get a sample which is not there", () => {
			const players = new Players({
				test: buffer,
			});
			expect(() => {
				players.player("nope");
			}).to.throw(Error);
			players.dispose();
		});

		it("can add a player with a buffer", () => {
			const players = new Players();
			expect(players.has("test")).to.be.false;
			players.add("test", buffer);
			expect(players.has("test")).to.be.true;
			players.dispose();
		});

		it("can add a player with a url", (done) => {
			const players = new Players();
			expect(players.has("test")).to.be.false;
			players.add("test", "./test/audio/sine.wav", () => {
				expect(players.has("test")).to.be.true;
				players.dispose();
				done();
			});
		});

		it("can add a player with an unloaded ToneAudioBuffer", (done) => {
			const players = new Players();
			const output = new ToneAudioBuffer("./test/audio/sine.wav");
			players.add("test", output, () => {
				expect(players.has("test")).to.be.true;
				expect(players.player("test").loaded).to.be.true;
				players.dispose();
				done();
			});
		});
	});

	context("start/stop players", () => {
		it("makes a sound", () => {
			return OutputAudio(() => {
				const players = new Players({
					test: buffer,
				}).toDestination();
				players.player("test").start(0);
			});
		});
		it("can be muted", async () => {
			const output = await Offline(() => {
				const players = new Players({
					test: buffer,
				}).toDestination();
				players.player("test").start(0);
				players.mute = true;
				expect(players.mute).to.be.true;
			}, 0.3);
			expect(output.isSilent()).to.be.true;
		});

		it("be scheduled to start in the future", async () => {
			const output = await Offline(() => {
				const players = new Players({
					test: buffer,
				}).toDestination();
				players.player("test").start(0.1);
			}, 0.3);
			output.forEach((sample, time) => {
				if (sample > 0) {
					expect(time).to.be.at.least(0.099);
				}
			});
		});

		it("be scheduled to stop in the future", async () => {
			const output = await Offline(() => {
				const players = new Players({
					test: buffer,
				}).toDestination();
				players.player("test").start(0).stop(0.2);
			}, 0.3);
			output.forEach((sample, time) => {
				if (time > 0.2) {
					expect(sample).to.equal(0);
				}
			});
		});

		it("if any of the players are playing, reports state as 'started'", async () => {
			await Offline(() => {
				const players = new Players({
					test0: buffer,
					test1: buffer,
				}).toDestination();
				players.player("test0").start(0).stop(0.05);
				players.player("test1").start(0).stop(0.1);
				return (time) => {
					if (time <= 0.1) {
						expect(players.state).to.equal("started");
					} else {
						expect(players.state).to.equal("stopped");
					}
				};
			}, 0.2);
		});

		it("can start multiple samples", async () => {
			await OutputAudio(() => {
				const players = new Players({
					test0: buffer,
					test1: buffer,
				}).toDestination();
				players.player("test0").start(0).stop(0.01);
				players.player("test1").start(0);
			});
		});

		it("can stop all of the samples in the future", async () => {
			const output = await Offline(() => {
				const players = new Players({
					test0: buffer,
					test1: buffer,
				}).toDestination();
				players.player("test0").start(0);
				players.player("test1").start(0);
				players.stopAll(0.2);
			}, 0.3);
			output.forEach((sample, time) => {
				if (time > 0.2) {
					expect(sample).to.equal(0);
				}
			});
		});

		it("fades in and out correctly", async () => {
			const output = await Offline(() => {
				const onesArray = new Float32Array(
					getContext().sampleRate * 0.5
				);
				onesArray.forEach((sample, index) => {
					onesArray[index] = 1;
				});
				const onesBuffer = ToneAudioBuffer.fromArray(onesArray);
				const players = new Players(
					{
						test: onesBuffer,
					},
					{
						fadeIn: 0.1,
						fadeOut: 0.1,
					}
				).toDestination();
				players.player("test").start(0);
			}, 0.6);
			output.forEach((sample, time) => {
				if (time < 0.1) {
					expect(sample).to.be.within(0, 1);
				} else if (time < 0.4) {
					expect(sample).to.equal(1);
				} else if (time < 0.5) {
					expect(sample).to.be.within(0, 1);
				} else {
					expect(sample).to.equal(0);
				}
			});
		});
	});
});

import { Volume } from "../../component/channel/Volume.js";
import { Param } from "../../core/context/Param.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import {
	ToneAudioBuffers,
	ToneAudioBuffersUrlMap,
} from "../../core/context/ToneAudioBuffers.js";
import { OutputNode, ToneAudioNode } from "../../core/context/ToneAudioNode.js";
import { Decibels, Time } from "../../core/type/Units.js";
import { assert } from "../../core/util/Debug.js";
import { optionsFromArguments } from "../../core/util/Defaults.js";
import { noOp, readOnly } from "../../core/util/Interface.js";
import { BasicPlaybackState } from "../../core/util/StateTimeline.js";
import { Source, SourceOptions } from "../Source.js";
import { Player } from "./Player.js";

export interface PlayersOptions extends SourceOptions {
	urls: ToneAudioBuffersUrlMap;
	volume: Decibels;
	mute: boolean;
	onload: () => void;
	onerror: (error: Error) => void;
	baseUrl: string;
	fadeIn: Time;
	fadeOut: Time;
}

/**
 * Players combines multiple {@link Player} objects.
 * @category Source
 */
export class Players extends ToneAudioNode<PlayersOptions> {
	readonly name: string = "Players";

	/**
	 * The output volume node
	 */
	private _volume: Volume;

	/**
	 * The volume of the output in decibels.
	 */
	readonly volume: Param<"decibels">;

	/**
	 * The combined output of all of the players
	 */
	readonly output: OutputNode;

	/**
	 * Players has no input.
	 */
	readonly input = undefined;

	/**
	 * The container of all of the players
	 */
	private _players: Map<string, Player> = new Map();

	/**
	 * The container of all the buffers
	 */
	private _buffers: ToneAudioBuffers;

	/**
	 * private holder of the fadeIn time
	 */
	private _fadeIn: Time;

	/**
	 * private holder of the fadeOut time
	 */
	private _fadeOut: Time;

	/**
	 * @param urls An object mapping a name to a url.
	 * @param onload The function to invoke when all buffers are loaded.
	 */
	constructor(urls?: ToneAudioBuffersUrlMap, onload?: () => void);
	/**
	 * @param urls An object mapping a name to a url.
	 * @param options The remaining options associated with the players
	 */
	constructor(
		urls?: ToneAudioBuffersUrlMap,
		options?: Partial<Omit<PlayersOptions, "urls">>
	);
	constructor(options?: Partial<PlayersOptions>);
	constructor() {
		const options = optionsFromArguments(
			Players.getDefaults(),
			arguments,
			["urls", "onload"],
			"urls"
		);
		super(options);

		/**
		 * The output volume node
		 */
		this._volume = this.output = new Volume({
			context: this.context,
			volume: options.volume,
		});

		this.volume = this._volume.volume;
		readOnly(this, "volume");
		this._buffers = new ToneAudioBuffers({
			urls: options.urls,
			onload: options.onload,
			baseUrl: options.baseUrl,
			onerror: options.onerror,
		});
		// mute initially
		this.mute = options.mute;
		this._fadeIn = options.fadeIn;
		this._fadeOut = options.fadeOut;
	}

	static getDefaults(): PlayersOptions {
		return Object.assign(Source.getDefaults(), {
			baseUrl: "",
			fadeIn: 0,
			fadeOut: 0,
			mute: false,
			onload: noOp,
			onerror: noOp,
			urls: {},
			volume: 0,
		});
	}

	/**
	 * Mute the output.
	 */
	get mute(): boolean {
		return this._volume.mute;
	}
	set mute(mute) {
		this._volume.mute = mute;
	}

	/**
	 * The fadeIn time of the envelope applied to the source.
	 */
	get fadeIn(): Time {
		return this._fadeIn;
	}
	set fadeIn(fadeIn) {
		this._fadeIn = fadeIn;
		this._players.forEach((player) => {
			player.fadeIn = fadeIn;
		});
	}

	/**
	 * The fadeOut time of the each of the sources.
	 */
	get fadeOut(): Time {
		return this._fadeOut;
	}
	set fadeOut(fadeOut) {
		this._fadeOut = fadeOut;
		this._players.forEach((player) => {
			player.fadeOut = fadeOut;
		});
	}

	/**
	 * The state of the players object. Returns "started" if any of the players are playing.
	 */
	get state(): BasicPlaybackState {
		const playing = Array.from(this._players).some(
			([_, player]) => player.state === "started"
		);
		return playing ? "started" : "stopped";
	}

	/**
	 * True if the buffers object has a buffer by that name.
	 * @param name  The key or index of the buffer.
	 */
	has(name: string): boolean {
		return this._buffers.has(name);
	}

	/**
	 * Get a player by name.
	 * @param  name  The players name as defined in the constructor object or `add` method.
	 */
	player(name: string): Player {
		assert(
			this.has(name),
			`No Player with the name ${name} exists on this object`
		);
		if (!this._players.has(name)) {
			const player = new Player({
				context: this.context,
				fadeIn: this._fadeIn,
				fadeOut: this._fadeOut,
				url: this._buffers.get(name),
			}).connect(this.output);
			this._players.set(name, player);
		}
		return this._players.get(name) as Player;
	}

	/**
	 * If all the buffers are loaded or not
	 */
	get loaded(): boolean {
		return this._buffers.loaded;
	}

	/**
	 * Add a player by name and url to the Players
	 * @param  name A unique name to give the player
	 * @param  url  Either the url of the buffer or a buffer which will be added with the given name.
	 * @param callback  The callback to invoke when the url is loaded.
	 * @example
	 * const players = new Tone.Players();
	 * players.add("gong", "https://tonejs.github.io/audio/berklee/gong_1.mp3", () => {
	 * 	console.log("gong loaded");
	 * 	players.player("gong").start();
	 * });
	 */
	add(
		name: string,
		url: string | ToneAudioBuffer | AudioBuffer,
		callback?: () => void
	): this {
		assert(
			!this._buffers.has(name),
			"A buffer with that name already exists on this object"
		);
		this._buffers.add(name, url, callback);
		return this;
	}

	/**
	 * Stop all of the players at the given time
	 * @param time The time to stop all of the players.
	 */
	stopAll(time?: Time): this {
		this._players.forEach((player) => player.stop(time));
		return this;
	}

	dispose(): this {
		super.dispose();
		this._volume.dispose();
		this.volume.dispose();
		this._players.forEach((player) => player.dispose());
		this._buffers.dispose();
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { CompareToFile } from "../../../test/helper/CompareToFile.js";
import { Offline } from "../../../test/helper/Offline.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { getContext } from "../../core/Global.js";
import { ToneBufferSource } from "./ToneBufferSource.js";

const sampleRate = getContext().sampleRate;

describe("ToneBufferSource", () => {
	const buffer = new ToneAudioBuffer();

	const ones = new Float32Array(sampleRate * 0.5);
	ones.forEach((sample, index) => (ones[index] = 1));
	const onesBuffer = ToneAudioBuffer.fromArray(ones);

	beforeEach(() => {
		return buffer.load("./test/audio/sine.wav");
	});

	// run the common tests
	BasicTests(ToneBufferSource, buffer);

	it("matches a file", () => {
		return CompareToFile(() => {
			const source = new ToneBufferSource(buffer).toDestination();
			source.start(0).stop(0.2);
		}, "bufferSource.wav");
	});

	context("Constructor", () => {
		it("can be constructed with a Tone.Buffer", () => {
			const source = new ToneBufferSource(buffer);
			expect(source.buffer.get()).to.equal(buffer.get());
			source.dispose();
		});

		it("can be constructed with an AudioBuffer", () => {
			const source = new ToneBufferSource(buffer.get());
			expect(source.buffer.get()).to.equal(buffer.get());
			source.dispose();
		});

		it("can be created with an options object", () => {
			const source = new ToneBufferSource({
				url: buffer,
				loop: true,
				loopEnd: 0.2,
				loopStart: 0.1,
				playbackRate: 0.5,
			});
			expect(source.loop).to.equal(true);
			expect(source.loopEnd).to.equal(0.2);
			expect(source.loopStart).to.equal(0.1);
			expect(source.playbackRate.value).to.equal(0.5);
			source.dispose();
		});

		it("can be constructed with no arguments", () => {
			const source = new ToneBufferSource();
			source.dispose();
		});

		it("can set the buffer after construction", () => {
			const source = new ToneBufferSource();
			expect(source.buffer.loaded).is.equal(false);
			source.buffer = buffer;
			expect(source.buffer.loaded).is.equal(true);
			source.dispose();
		});

		it("can be constructed with a url and onload", (done) => {
			const source = new ToneBufferSource(
				"./test/audio/short_sine.wav",
				() => {
					expect(source.buffer.loaded).is.equal(true);
					source.dispose();
					done();
				}
			);
		});

		it("invokes onerror if no url", (done) => {
			const source = new ToneBufferSource({
				url: "./nosuchfile.wav",
				onerror() {
					source.dispose();
					done();
				},
			});
		});

		it("won't start or stop if there is no buffer", () => {
			const source = new ToneBufferSource();
			expect(() => {
				source.start();
			}).to.throw(Error);
			expect(() => {
				source.stop();
			}).to.throw(Error);
			source.dispose();
		});
	});

	context("Looping", () => {
		beforeEach(() => {
			return buffer.load("./test/audio/short_sine.wav");
		});

		it("can be set to loop", () => {
			const player = new ToneBufferSource();
			player.loop = true;
			expect(player.loop).is.equal(true);
			player.dispose();
		});

		it("loops the audio", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.loop = true;
				player.toDestination();
				player.start(0);
			}, buffer.duration * 2);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 1.5)).to.be.above(0);
		});

		it("loops the audio when loop is set after 'start'", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.start(0);
				player.loop = true;
				player.toDestination();
			}, buffer.duration * 2);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 1.5)).to.be.above(0);
		});

		it("unloops the audio when loop is set after 'start'", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.loop = true;
				player.start(0);
				player.loop = false;
				player.toDestination();
			}, buffer.duration * 2);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration * 0.5)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.closeTo(0, 0.001);
			expect(buff.getRmsAtTime(buffer.duration * 1.5)).to.be.closeTo(
				0,
				0.001
			);
		});

		it("loops the audio for the specific duration", async () => {
			const playDur = buffer.duration * 1.5;
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.loop = true;
				player.toDestination();
				player.start(0, 0, playDur);
			}, buffer.duration * 2);
			expect(buff.getRmsAtTime(0)).to.be.above(0);
			expect(buff.getRmsAtTime(buffer.duration)).to.be.above(0);
			expect(buff.getRmsAtTime(playDur - 0.01)).to.be.above(0);
			expect(buff.getRmsAtTime(playDur + 0.01)).to.equal(0);
		});

		it("starts at the loop start offset if looping", async () => {
			const offsetTime = 0.05;
			const offsetSample =
				buffer.toArray()[Math.floor(offsetTime * sampleRate)];
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.loop = true;
				player.loopStart = offsetTime;
				player.start(0);
			}, 0.1);
			expect(buff.getValueAtTime(0)).to.equal(offsetSample);
		});

		it("the offset is modulo the loopDuration", async () => {
			const testSample = buffer.toArray()[
				Math.floor(0.051 * sampleRate)
			] as number;
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.loop = true;
				player.loopStart = 0;
				player.loopEnd = 0.1;
				player.start(0, 0.351);
			}, 0.1);
			expect(buff.getValueAtTime(0)).to.be.closeTo(testSample, 1e-4);
		});
	});

	context("Get/Set", () => {
		it("can be set with an options object", () => {
			const player = new ToneBufferSource();
			expect(player.loop).is.equal(false);
			player.set({
				loop: true,
				loopEnd: 0.5,
				loopStart: 0.4,
			});
			expect(player.loop).is.equal(true);
			expect(player.loopStart).to.equal(0.4);
			expect(player.loopEnd).to.equal(0.5);
			player.dispose();
		});

		it("can get/set the playbackRate", () => {
			const player = new ToneBufferSource();
			player.playbackRate.value = 0.5;
			expect(player.playbackRate.value).to.equal(0.5);
			player.dispose();
		});
	});

	context("onended", () => {
		beforeEach(() => {
			return buffer.load("./test/audio/sine.wav");
		});

		it.skip("schedules the onended callback in online context", (done) => {
			const player = new ToneBufferSource(buffer);
			player.start().stop("+0.1");
			player.onended = () => {
				expect(player.state).to.equal("stopped");
				player.dispose();
				done();
			};
		});

		it("schedules the onended callback when offline", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0.2).stop(0.4);
				player.onended = () => (wasInvoked = true);
			}, 0.5);
			expect(wasInvoked).to.equal(true);
		});

		it("invokes the onended callback when a looped buffer is scheduled to stop", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.loop = true;
				player.start().stop(0.4);
				player.onended = () => {
					wasInvoked = true;
				};
			}, 0.5);
			expect(wasInvoked).to.equal(true);
		});

		it("schedules the onended callback when the buffer is done without scheduling stop", async () => {
			let wasInvoked = false;
			await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0);
				player.onended = () => {
					wasInvoked = true;
				};
			}, buffer.duration * 1.1);
			expect(wasInvoked).to.equal(true);
		});
	});

	context("state", () => {
		beforeEach(() => {
			return buffer.load("./test/audio/sine.wav");
		});

		it("reports the right state when scheduled to stop", async () => {
			await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0.2).stop(0.4);

				return (time) => {
					if (time >= 0.2 && time < 0.4) {
						expect(player.state).to.equal("started");
					} else {
						expect(player.state).to.equal("stopped");
					}
				};
			}, 0.5);
		});

		it("reports the right state when duration is passed into start method", async () => {
			await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0, 0, 0.1);

				return (time) => {
					if (time >= 0 && time < 0.1) {
						expect(player.state).to.equal("started");
					} else {
						expect(player.state).to.equal("stopped");
					}
				};
			}, 0.2);
		});
	});

	context("Start/Stop Scheduling", () => {
		beforeEach(() => {
			return buffer.load("./test/audio/sine.wav");
		});

		it("can play for a specific duration", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0).stop(0.1);

				return (time) => {
					if (time > 0.1) {
						expect(player.state).to.equal("stopped");
					}
				};
			}, 0.4);
			expect(rms.getRmsAtTime(0)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.09)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.11)).to.equal(0);
			expect(rms.getRmsAtTime(0.3)).to.equal(0);
		});

		it("can be scheduled to stop", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0).stop(0.1);
			}, 0.6);
			expect(rms.getRmsAtTime(0.01)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.08)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.11)).to.equal(0);
		});

		it("plays correctly when playbackRate is < 1", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0);
				player.playbackRate.value = 0.75;
			}, buffer.duration * 1.3);
			expect(rms.getRmsAtTime(0.01)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.1)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.2)).to.be.gt(0);
			expect(rms.getRmsAtTime(buffer.duration)).to.be.gt(0);
		});

		it("plays correctly when playbackRate is > 1", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0);
				player.playbackRate.value = 2;
			}, buffer.duration);
			expect(rms.getRmsAtTime(0.03)).to.be.gt(0);
			expect(rms.getRmsAtTime(buffer.duration * 0.45)).to.be.gt(0);
			expect(rms.getRmsAtTime(buffer.duration * 0.5)).to.closeTo(0, 0.01);
			expect(rms.getRmsAtTime(buffer.duration * 0.7)).to.closeTo(0, 0.01);
		});

		it("can play for a specific duration passed in the 'start' method", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0, 0, 0.1);

				return (time_1) => {
					if (time_1 > 0.1) {
						expect(player.state).to.equal("stopped");
					}
				};
			}, 0.4);
			expect(rms.getRmsAtTime(0)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.09)).to.be.gt(0);
			// after stop is scheduled
			expect(rms.getRmsAtTime(0.11)).to.equal(0);
			expect(rms.getRmsAtTime(0.3)).to.equal(0);
		});

		it("can start at an offset", async () => {
			const offsetTime = 0.1;
			const offsetSample =
				buffer.toArray()[Math.floor(offsetTime * sampleRate)];
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0, offsetTime);
			}, 0.05);
			expect(buff.getValueAtTime(0)).to.equal(offsetSample);
		});

		it("can end start ramp early", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.fadeIn = 0.2;
				player.toDestination();
				player.start(0).stop(0.1);
			}, 0.2);
			expect(rms.getRmsAtTime(0.0)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.05)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.09)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.1)).to.equal(0);
			expect(rms.getRmsAtTime(0.15)).to.equal(0);
		});

		it("can end start ramp with a ramp", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(onesBuffer);
				player.fadeIn = 0.2;
				player.fadeOut = 0.1;
				player.loop = true;
				player.toDestination();
				player.start(0).stop(0.1);
			}, 0.3);
			// fade in
			expect(buff.getRmsAtTime(0.01)).to.be.gt(0);
			expect(buff.getRmsAtTime(0.05)).to.be.gt(0);
			// fade out
			expect(buff.getRmsAtTime(0.1)).to.be.gt(0);
			expect(buff.getRmsAtTime(0.15)).to.be.gt(0);
			expect(buff.getRmsAtTime(0.19)).to.be.gt(0);
			// end of ramp
			expect(buff.getRmsAtTime(0.21)).to.equal(0);
		});

		it("can be scheduled to stop with a ramp", async () => {
			const rms = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.fadeOut = 0.05;
				player.start(0).stop(0.1);
			}, 0.6);
			expect(rms.getRmsAtTime(0.01)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.05)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.08)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.1)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.14)).to.be.gt(0);
			expect(rms.getRmsAtTime(0.16)).to.equal(0);
			expect(rms.getRmsAtTime(0.2)).to.equal(0);
			expect(rms.getRmsAtTime(0.3)).to.equal(0);
			expect(rms.getRmsAtTime(0.4)).to.equal(0);
			expect(rms.getRmsAtTime(0.5)).to.equal(0);
		});

		it("fade is applied after the stop time", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(onesBuffer).toDestination();
				player.fadeOut = 0.1;
				player.start(0).stop(0.2);
			}, 0.32);
			expect(buff.getValueAtTime(0)).to.equal(1);
			expect(buff.getValueAtTime(0.1)).to.equal(1);
			expect(buff.getValueAtTime(0.2)).to.equal(1);
			expect(buff.getValueAtTime(0.25)).to.be.closeTo(0.5, 0.01);
			expect(buff.getValueAtTime(0.29)).to.be.closeTo(0.1, 0.01);
			expect(buff.getValueAtTime(0.3)).to.be.closeTo(0, 0.01);
			expect(buff.getValueAtTime(0.31)).to.equal(0);
		});

		it("can fade with an exponential curve", () => {
			const player = new ToneBufferSource(onesBuffer).toDestination();
			player.curve = "exponential";
			expect(player.curve).to.equal("exponential");
			player.dispose();
		});

		it("fades in and out exponentially", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(onesBuffer).toDestination();
				player.curve = "exponential";
				player.fadeIn = 0.1;
				player.fadeOut = 0.1;
				player.start(0).stop(0.4);
			}, 0.51);
			expect(buff.getValueAtTime(0)).to.equal(0);
			expect(buff.getValueAtTime(0.05)).to.be.closeTo(0.93, 0.01);
			expect(buff.getValueAtTime(0.1)).to.be.closeTo(1, 0.01);
			expect(buff.getValueAtTime(0.4)).to.be.closeTo(1, 0.01);
			expect(buff.getValueAtTime(0.45)).to.be.closeTo(0.06, 0.01);
			expect(buff.getValueAtTime(0.5)).to.closeTo(0, 0.01);
		});

		it("can be scheduled to start at a lower gain", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer).toDestination();
				player.start(0, 0, undefined, 0.5);
			}, 0.5);
			expect(buff.getValueAtTime(0)).to.be.lte(0.5);
			expect(buff.getValueAtTime(0.1)).to.be.lte(0.5);
			expect(buff.getValueAtTime(0.2)).to.be.lte(0.5);
			expect(buff.getValueAtTime(0.3)).to.be.lte(0.5);
			expect(buff.getValueAtTime(0.4)).to.be.lte(0.5);
		});

		it("cannot be started more than once", () => {
			const player = new ToneBufferSource(buffer);
			player.start();
			expect(() => {
				player.start();
			}).to.throw(Error);
			player.dispose();
		});

		it("stops playing if invoked with 'stop' at a sooner time", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.toDestination();
				player.start(0).stop(0.1).stop(0.05);
			}, 0.3);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.05, 0.02);
		});

		it("does not play if the stop time is at the start time", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.toDestination();
				player.start(0).stop(0);
			}, 0.3);
			expect(buff.isSilent()).is.equal(true);
		});

		it("does not play if the stop time is at before start time", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.toDestination();
				player.start(0.1).stop(0);
			}, 0.3);
			expect(buff.isSilent()).is.equal(true);
		});

		it("stops playing at the last scheduled stop time", async () => {
			const buff = await Offline(() => {
				const player = new ToneBufferSource(buffer);
				player.toDestination();
				player.start(0).stop(0.1).stop(0.2);
			}, 0.3);
			expect(buff.getTimeOfLastSound()).to.be.closeTo(0.2, 0.02);
		});
	});
});

import { Param } from "../../core/context/Param.js";
import { ToneAudioBuffer } from "../../core/context/ToneAudioBuffer.js";
import { connect } from "../../core/context/ToneAudioNode.js";
import { GainFactor, Positive, Seconds, Time } from "../../core/type/Units.js";
import { assert } from "../../core/util/Debug.js";
import { defaultArg, optionsFromArguments } from "../../core/util/Defaults.js";
import { noOp } from "../../core/util/Interface.js";
import { EQ, GTE, LT } from "../../core/util/Math.js";
import { isDefined } from "../../core/util/TypeCheck.js";
import {
	OneShotSource,
	OneShotSourceCurve,
	OneShotSourceOptions,
} from "../OneShotSource.js";

export type ToneBufferSourceCurve = OneShotSourceCurve;

export interface ToneBufferSourceOptions extends OneShotSourceOptions {
	url: string | AudioBuffer | ToneAudioBuffer;
	curve: ToneBufferSourceCurve;
	playbackRate: Positive;
	fadeIn: Time;
	fadeOut: Time;
	loopStart: Time;
	loopEnd: Time;
	loop: boolean;
	onload: () => void;
	onerror: (error: Error) => void;
}

/**
 * Wrapper around the native BufferSourceNode.
 * @category Source
 */
export class ToneBufferSource extends OneShotSource<ToneBufferSourceOptions> {
	readonly name: string = "ToneBufferSource";

	/**
	 * The oscillator
	 */
	private _source = this.context.createBufferSource();
	protected _internalChannels = [this._source];

	/**
	 * The frequency of the oscillator
	 */
	readonly playbackRate: Param<"positive">;

	/**
	 * The private instance of the buffer object
	 */
	private _buffer: ToneAudioBuffer;

	/**
	 * indicators if the source has started/stopped
	 */
	private _sourceStarted = false;
	private _sourceStopped = false;

	/**
	 * @param url The buffer to play or url to load
	 * @param onload The callback to invoke when the buffer is done playing.
	 */
	constructor(
		url?: ToneAudioBuffer | AudioBuffer | string,
		onload?: () => void
	);
	constructor(options?: Partial<ToneBufferSourceOptions>);
	constructor() {
		const options = optionsFromArguments(
			ToneBufferSource.getDefaults(),
			arguments,
			["url", "onload"]
		);
		super(options);

		connect(this._source, this._gainNode);
		this._source.onended = () => this._stopSource();

		/**
		 * The playbackRate of the buffer
		 */
		this.playbackRate = new Param({
			context: this.context,
			param: this._source.playbackRate,
			units: "positive",
			value: options.playbackRate,
		});

		// set some values initially
		this.loop = options.loop;
		this.loopStart = options.loopStart;
		this.loopEnd = options.loopEnd;
		this._buffer = new ToneAudioBuffer(
			options.url,
			options.onload,
			options.onerror
		);

		this._internalChannels.push(this._source);
	}

	static getDefaults(): ToneBufferSourceOptions {
		return Object.assign(OneShotSource.getDefaults(), {
			url: new ToneAudioBuffer(),
			loop: false,
			loopEnd: 0,
			loopStart: 0,
			onload: noOp,
			onerror: noOp,
			playbackRate: 1,
		});
	}

	/**
	 * The fadeIn time of the amplitude envelope.
	 */
	get fadeIn(): Time {
		return this._fadeIn;
	}
	set fadeIn(t: Time) {
		this._fadeIn = t;
	}

	/**
	 * The fadeOut time of the amplitude envelope.
	 */
	get fadeOut(): Time {
		return this._fadeOut;
	}
	set fadeOut(t: Time) {
		this._fadeOut = t;
	}

	/**
	 * The curve applied to the fades, either "linear" or "exponential"
	 */
	get curve(): ToneBufferSourceCurve {
		return this._curve;
	}
	set curve(t) {
		this._curve = t;
	}

	/**
	 * Start the buffer
	 * @param  time When the player should start.
	 * @param  offset The offset from the beginning of the sample to start at.
	 * @param  duration How long the sample should play. If no duration is given, it will default to the full length of the sample (minus any offset)
	 * @param  gain  The gain to play the buffer back at.
	 */
	start(
		time?: Time,
		offset?: Time,
		duration?: Time,
		gain: GainFactor = 1
	): this {
		assert(this.buffer.loaded, "buffer is either not set or not loaded");
		const computedTime = this.toSeconds(time);

		// apply the gain envelope
		this._startGain(computedTime, gain);

		// if it's a loop the default offset is the loopstart point
		if (this.loop) {
			offset = defaultArg(offset, this.loopStart);
		} else {
			// otherwise the default offset is 0
			offset = defaultArg(offset, 0);
		}
		// make sure the offset is not less than 0
		let computedOffset = Math.max(this.toSeconds(offset), 0);

		// start the buffer source
		if (this.loop) {
			// modify the offset if it's greater than the loop time
			const loopEnd =
				this.toSeconds(this.loopEnd) || this.buffer.duration;
			const loopStart = this.toSeconds(this.loopStart);
			const loopDuration = loopEnd - loopStart;
			// move the offset back
			if (GTE(computedOffset, loopEnd)) {
				computedOffset =
					((computedOffset - loopStart) % loopDuration) + loopStart;
			}
			// when the offset is very close to the duration, set it to 0
			if (EQ(computedOffset, this.buffer.duration)) {
				computedOffset = 0;
			}
		}

		// this.buffer.loaded would have return false if the AudioBuffer was undefined
		this._source.buffer = this.buffer.get() as AudioBuffer;
		this._source.loopEnd =
			this.toSeconds(this.loopEnd) || this.buffer.duration;
		if (LT(computedOffset, this.buffer.duration)) {
			this._sourceStarted = true;
			this._source.start(computedTime, computedOffset);
		}

		// if a duration is given, schedule a stop
		if (isDefined(duration)) {
			let computedDur = this.toSeconds(duration);
			// make sure it's never negative
			computedDur = Math.max(computedDur, 0);
			this.stop(computedTime + computedDur);
		}

		return this;
	}

	protected _stopSource(time?: Seconds): void {
		if (!this._sourceStopped && this._sourceStarted) {
			this._sourceStopped = true;
			this._source.stop(this.toSeconds(time));
			this._onended();
		}
	}

	/**
	 * If loop is true, the loop will start at this position.
	 */
	get loopStart(): Time {
		return this._source.loopStart;
	}
	set loopStart(loopStart: Time) {
		this._source.loopStart = this.toSeconds(loopStart);
	}

	/**
	 * If loop is true, the loop will end at this position.
	 */
	get loopEnd(): Time {
		return this._source.loopEnd;
	}
	set loopEnd(loopEnd: Time) {
		this._source.loopEnd = this.toSeconds(loopEnd);
	}

	/**
	 * The audio buffer belonging to the player.
	 */
	get buffer(): ToneAudioBuffer {
		return this._buffer;
	}
	set buffer(buffer: ToneAudioBuffer) {
		this._buffer.set(buffer);
	}

	/**
	 * If the buffer should loop once its over.
	 */
	get loop(): boolean {
		return this._source.loop;
	}
	set loop(loop: boolean) {
		this._source.loop = loop;
		if (this._sourceStarted) {
			this.cancelStop();
		}
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this._source.onended = null;
		this._source.disconnect();
		this._buffer.dispose();
		this.playbackRate.dispose();
		return this;
	}
}

