				count: 3,
			});
			fatOsc.start();
			fatOsc.count = 4;
			expect(fatOsc.count).to.equal(4);
			fatOsc.dispose();
		});

		it("correctly distributes the detune spread", () => {
			const fatOsc = new FatOscillator({
				count: 2,
				spread: 20,
			});
			// @ts-ignore
			expect(fatOsc._oscillators.length).to.equal(2);
			// @ts-ignore
			expect(fatOsc._oscillators[0].detune.value).to.equal(-10);
			// @ts-ignore
			expect(fatOsc._oscillators[1].detune.value).to.equal(10);
			fatOsc.dispose();
		});

		it("can get/set the baseType", () => {
			const osc = new FatOscillator();
			osc.type = "sine5";
			expect(osc.baseType).to.equal("sine");
			osc.baseType = "triangle";
			expect(osc.type).to.equal("triangle5");
			expect(osc.partialCount).to.equal(5);
			osc.partialCount = 2;
			expect(osc.type).to.equal("triangle2");
			osc.baseType = "custom";
			expect(osc.type).to.equal("custom");
			osc.partials = [1, 2, 3];
			expect(osc.baseType).to.equal("custom");
			osc.baseType = "square";
			expect(osc.type).to.equal("square");
			osc.dispose();
		});
	});
});

import {
	Cents,
	Degrees,
	Frequency,
	Seconds,
	Time,
} from "../../core/type/Units.js";
import { assertRange } from "../../core/util/Debug.js";
import { optionsFromArguments } from "../../core/util/Defaults.js";
import { noOp, readOnly } from "../../core/util/Interface.js";
import { Signal } from "../../signal/Signal.js";
import { Source } from "../Source.js";
import { Oscillator } from "./Oscillator.js";
import {
	FatConstructorOptions,
	FatOscillatorOptions,
	generateWaveform,
	NonCustomOscillatorType,
	ToneOscillatorInterface,
	ToneOscillatorType,
} from "./OscillatorInterface.js";

export { FatOscillatorOptions } from "./OscillatorInterface.js";

/**
 * FatOscillator is an array of oscillators with detune spread between the oscillators
 * @example
 * const fatOsc = new Tone.FatOscillator("Ab3", "sawtooth", 40).toDestination().start();
 * @category Source
 */
export class FatOscillator
	extends Source<FatOscillatorOptions>
	implements ToneOscillatorInterface
{
	readonly name: string = "FatOscillator";

	readonly frequency: Signal<"frequency">;
	readonly detune: Signal<"cents">;

	/**
	 * The array of oscillators
	 */
	private _oscillators: Oscillator[] = [];

	/**
	 * The total spread of the oscillators
	 */
	private _spread: Cents;

	/**
	 * The type of the oscillator
	 */
	private _type: ToneOscillatorType;

	/**
	 * The phase of the oscillators
	 */
	private _phase: Degrees;

	/**
	 * The partials array
	 */
	private _partials: number[];

	/**
	 * The number of partials to use
	 */
	private _partialCount: number;

	/**
	 * @param frequency The oscillator's frequency.
	 * @param type The type of the oscillator.
	 * @param spread The detune spread between the oscillators.
	 */
	constructor(
		frequency?: Frequency,
		type?: ToneOscillatorType,
		spread?: Cents
	);
	constructor(options?: Partial<FatConstructorOptions>);
	constructor() {
		const options = optionsFromArguments(
			FatOscillator.getDefaults(),
			arguments,
			["frequency", "type", "spread"]
		);
		super(options);

		this.frequency = new Signal({
			context: this.context,
			units: "frequency",
			value: options.frequency,
		});
		this.detune = new Signal({
			context: this.context,
			units: "cents",
			value: options.detune,
		});

		this._spread = options.spread;
		this._type = options.type;
		this._phase = options.phase;
		this._partials = options.partials;
		this._partialCount = options.partialCount;

		// set the count initially
		this.count = options.count;

		readOnly(this, ["frequency", "detune"]);
	}

	static getDefaults(): FatOscillatorOptions {
		return Object.assign(Oscillator.getDefaults(), {
			count: 3,
			spread: 20,
			type: "sawtooth",
		});
	}

	/**
	 * start the oscillator
	 */
	protected _start(time: Time): void {
		time = this.toSeconds(time);
		this._forEach((osc) => osc.start(time));
	}

	/**
	 * stop the oscillator
	 */
	protected _stop(time: Time): void {
		time = this.toSeconds(time);
		this._forEach((osc) => osc.stop(time));
	}

	protected _restart(time: Seconds): void {
		this._forEach((osc) => osc.restart(time));
	}

	/**
	 * Iterate over all of the oscillators
	 */
	private _forEach(iterator: (osc: Oscillator, index: number) => void): void {
		for (let i = 0; i < this._oscillators.length; i++) {
			iterator(this._oscillators[i], i);
		}
	}

	/**
	 * The type of the oscillator
	 */
	get type(): ToneOscillatorType {
		return this._type;
	}
	set type(type: ToneOscillatorType) {
		this._type = type;
		this._forEach((osc) => (osc.type = type));
	}

	/**
	 * The detune spread between the oscillators. If "count" is
	 * set to 3 oscillators and the "spread" is set to 40,
	 * the three oscillators would be detuned like this: [-20, 0, 20]
	 * for a total detune spread of 40 cents.
	 * @example
	 * const fatOsc = new Tone.FatOscillator().toDestination().start();
	 * fatOsc.spread = 70;
	 */
	get spread(): Cents {
		return this._spread;
	}
	set spread(spread: Cents) {
		this._spread = spread;
		if (this._oscillators.length > 1) {
			const start = -spread / 2;
			const step = spread / (this._oscillators.length - 1);
			this._forEach((osc, i) => (osc.detune.value = start + step * i));
		}
	}

	/**
	 * The number of detuned oscillators. Must be an integer greater than 1.
	 * @example
	 * const fatOsc = new Tone.FatOscillator("C#3", "sawtooth").toDestination().start();
	 * // use 4 sawtooth oscillators
	 * fatOsc.count = 4;
	 */
	get count(): number {
		return this._oscillators.length;
	}
	set count(count: number) {
		assertRange(count, 1);
		if (this._oscillators.length !== count) {
			// dispose the previous oscillators
			this._forEach((osc) => osc.dispose());
			this._oscillators = [];
			for (let i = 0; i < count; i++) {
				const osc = new Oscillator({
					context: this.context,
					volume: -6 - count * 1.1,
					type: this._type as NonCustomOscillatorType,
					phase: this._phase + (i / count) * 360,
					partialCount: this._partialCount,
					onstop: i === 0 ? () => this.onstop(this) : noOp,
				});
				if (this.type === "custom") {
					osc.partials = this._partials;
				}
				this.frequency.connect(osc.frequency);
				this.detune.connect(osc.detune);
				osc.detune.overridden = false;
				osc.connect(this.output);
				this._oscillators[i] = osc;
			}
			// set the spread
			this.spread = this._spread;
			if (this.state === "started") {
				this._forEach((osc) => osc.start());
			}
		}
	}

	get phase(): Degrees {
		return this._phase;
	}
	set phase(phase: Degrees) {
		this._phase = phase;
		this._forEach(
			(osc, i) => (osc.phase = this._phase + (i / this.count) * 360)
		);
	}

	get baseType(): OscillatorType {
		return this._oscillators[0].baseType;
	}
	set baseType(baseType: OscillatorType) {
		this._forEach((osc) => (osc.baseType = baseType));
		this._type = this._oscillators[0].type;
	}

	get partials(): number[] {
		return this._oscillators[0].partials;
	}
	set partials(partials: number[]) {
		this._partials = partials;
		this._partialCount = this._partials.length;
		if (partials.length) {
			this._type = "custom";
			this._forEach((osc) => (osc.partials = partials));
		}
	}

	get partialCount(): number {
		return this._oscillators[0].partialCount;
	}
	set partialCount(partialCount: number) {
		this._partialCount = partialCount;
		this._forEach((osc) => (osc.partialCount = partialCount));
		this._type = this._oscillators[0].type;
	}

	async asArray(length = 1024): Promise<Float32Array> {
		return generateWaveform(this, length);
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this.frequency.dispose();
		this.detune.dispose();
		this._forEach((osc) => osc.dispose());
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { Offline } from "../../../test/helper/Offline.js";
import { OutputAudio } from "../../../test/helper/OutputAudio.js";
import { SignalConnectAndDisconnect } from "../../../test/helper/SignalTests.js";
import { Signal } from "../../signal/Signal.js";
import { LFO, LFOOptions } from "./LFO.js";

describe("LFO", () => {
	BasicTests(LFO);
	SignalConnectAndDisconnect(LFO);

	context("API", () => {
		it("can get the current state", () => {
			const lfo = new LFO();
			expect(lfo.state).to.equal("stopped");
			lfo.start();
			expect(lfo.state).to.equal("started");
			lfo.dispose();
		});
	});

	context("Low Oscillations", () => {
		it("can be started and stopped", () => {
			const lfo = new LFO();
			lfo.start();
			lfo.stop();
			lfo.dispose();
		});

		it("can be constructed with an object", () => {
			const lfo = new LFO({
				frequency: 0.3,
				type: "triangle2",
			});
			expect(lfo.type).to.equal("triangle2");
			expect(lfo.frequency.value).to.be.closeTo(0.3, 0.001);
			lfo.dispose();
		});

		it("handles getters/setters as objects", () => {
			return Offline(() => {
				const lfo = new LFO();
				const values = {
					frequency: "8n",
					max: 2,
					min: -1,
					phase: 180,
					type: "square",
				} as Partial<LFOOptions>;
				lfo.set(values);
				expect(lfo.get()).to.contain.keys(Object.keys(values));
				expect(lfo.type).to.equal(values.type);
				expect(lfo.min).to.equal(values.min);
				expect(lfo.max).to.equal(values.max);
				expect(lfo.phase).to.equal(values.phase);
				expect(lfo.frequency.value).to.be.closeTo(4, 0.1);
				lfo.dispose();
			});
		});

		it("outputs a signal", () => {
			return OutputAudio(() => {
				const lfo = new LFO(100, 10, 20);
				lfo.toDestination();
				lfo.start();
			});
		});

		it("can be creates an oscillation in a specific range", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(100, 10, 20).toDestination();
				lfo.start();
			});
			expect(buffer.min()).to.be.gte(10);
			expect(buffer.max()).to.be.lte(20);
		});

		it("can change the oscillation range", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(100, 10, 20).toDestination();
				lfo.start();
				lfo.min = 15;
				lfo.max = 18;
			});
			expect(buffer.min()).to.be.gte(15);
			expect(buffer.max()).to.be.lte(18);
		});

		it("initially outputs a signal at the center of its phase", async () => {
			const buffer = await Offline(() => {
				new LFO(100, 10, 20).toDestination();
			});
			expect(buffer.value()).to.be.closeTo(15, 0.1);
		});

		it("outputs a signal at the correct phase angle", async () => {
			const buffer = await Offline(() => {
				new LFO({
					min: 0,
					phase: 90,
				}).toDestination();
			});
			expect(buffer.value()).to.be.closeTo(0, 0.1);
		});

		it("outputs the right phase when setting a new phase", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO({
					max: 1,
					min: -1,
					phase: 0,
				}).toDestination();
				lfo.phase = 270;
			});
			expect(buffer.value()).to.be.closeTo(1, 0.1);
		});

		it("can convert to other units", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO({
					frequency: 20,
					max: 5,
					min: -20,
					units: "decibels",
				}).toDestination();
				lfo.start();
			});
			expect(buffer.min()).to.be.closeTo(0.099, 0.01);
			expect(buffer.max()).to.be.closeTo(1.78, 0.01);
		});

		it("can converts to the units of the connecting node", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(20, -35, -10);
				const signal = new Signal(0, "decibels");
				expect(lfo.units).to.equal("number");
				lfo.toDestination();
				lfo.connect(signal);
				expect(lfo.units).to.equal("decibels");
				lfo.start();
			});
			expect(buffer.min()).to.be.closeTo(0.017, 0.01);
			expect(buffer.max()).to.be.closeTo(0.31, 0.01);
		});

		it("does not convert to the connected value if that is not set to convert", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(20, -35, -10);
				const signal = new Signal({
					convert: false,
					units: "decibels",
					value: 0,
				});
				expect(lfo.units).to.equal("number");
				lfo.toDestination();
				lfo.connect(signal);
				expect(lfo.units).to.equal("decibels");
				lfo.start();
			});
			expect(buffer.min()).to.be.closeTo(-35, 0.01);
			expect(buffer.max()).to.be.closeTo(-10, 0.01);
		});

		it("can sync the frequency to the Transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const lfo = new LFO(2);
				lfo.sync();
				lfo.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				// transport.start(0)
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(4, 0.1);
		});

		it("can unsync the frequency to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const lfo = new LFO(2);
				lfo.sync();
				lfo.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				lfo.unsync();
				transport.start(0);
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(2, 0.1);
		});

		it("can adjust the amplitude", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(10, -10, 10);
				lfo.amplitude.value = 0.5;
				lfo.toDestination();
				lfo.start();
			}, 0.1);
			expect(buffer.min()).to.be.closeTo(-5, 0.1);
			expect(buffer.max()).to.be.closeTo(5, 0.1);
		});

		it("can adjust the amplitude not centered at 0", async () => {
			const buffer = await Offline(() => {
				const lfo = new LFO(10, 400, 4000);
				lfo.amplitude.value = 0.5;
				lfo.toDestination();
				lfo.start();
			}, 0.1);
			expect(buffer.min()).to.be.closeTo(1300, 1);
			expect(buffer.max()).to.be.closeTo(3100, 1);
		});

		it("can pass in partials to the constructor", () => {
			const lfo = new LFO({
				type: "custom",
				partials: [0, 2, 3],
			});
			expect(lfo.partials).to.deep.equal([0, 2, 3]);
			lfo.partials = [1, 2, 3];
			expect(lfo.partials).to.deep.equal([1, 2, 3]);
		});
	});
});

